INSERT INTO `demo` VALUES (84, 00000000000, 0, 0, 'html', 'html5', NULL, 'HTML5 是World Wide Web Consortium，万维网联盟和Web Hypertext Application Technology Working Group合作的结果,\r\n\r\n    新特性应该基于 HTML、CSS、DOM 以及 JavaScript。\r\n    减少对外部插件的需求（比如 Flash）\r\n    更优秀的错误处理\r\n    更多取代脚本的标记\r\n    HTML5 应该独立于设备\r\n    开发进程应对公众透明\r\n', '44444453454534\n5\n345\n34\n5\n34\n5', NULL, '2016-1-5 18:47:45', '2016-1-16 14:42:50', 0, 0);
