INSERT INTO `demo` VALUES (156, 00000000152, 1, 0, 'html', 'area', '关键词', 'map必须配合img area必须嵌套在map中，为了兼容性必须同时添加name和id', '<img usemap=\"#planetmap\" />\n\n<map name=\"planetmap\" id=\"planetmap\">\n  <area shape=\"circle\" coords=\"180,139,14\" href =\"venus.html\" alt=\"Venus\" />\n</map>', NULL, '2016-1-16 18:49:20', '2016-1-16 18:51:25', 0, 0);
INSERT INTO `demo` VALUES (157, 00000000152, 1, 0, 'html', 'artical', '关键词', 'article 是一个特殊的 section 标签，它比 section 具有更明确的语义, 它代表一个独立的、完整的相关内容块。一般来说， article 会有标题部分(通常包含在 header 内)，有时也会 包含 footer 。虽然 section 也是带有主题性的一块内容，但是无论从结构上还是内容上来说，article 本身就是独立的、完整的。div没有任何语义，纯粹是为了js控制和样式控制的时候推荐div', '<article>\n    <section>\n        <hgroup>\n            <h1></h1>\n            <h2></h2>\n        </hgroup>\n    </section>\n    <aside>\n        <h4></h4>\n        <p></p>\n    </aside>\n</article>\n<style>\n    article{width:100%; overflow:hidden; }\n    section{float:left; width:500px;}\n    aside{float:right; width:310px;}\n</style>', NULL, '2016-1-16 18:56:41', '2016-1-18 13:20:57', 0, 0);
INSERT INTO `demo` VALUES (158, 00000000152, 1, 0, 'html', 'audio', '关键词', 'audio [’ɔːdɪəʊ] ', '<audio src=\"http://developer.mozilla.org/@api/deki/files/2926/=AudioTest_(1).ogg\" autoplay>\n  Your browser does not support the <code>audio</code> element.\n</audio>\n<!-------------demo---------------->\n<audio controls=\"controls\">\n  Your browser does not support the <code>audio</code> element.\n  <source src=\"foo.wav\" type=\"audio/wav\">\n</audio>\n<!-------------demo---------------->\n<audio src=\"foo.ogg\">\n  <track kind=\"captions\" src=\"foo.en.vtt\" srclang=\"en\" label=\"English\">\n  <track kind=\"captions\" src=\"foo.sv.vtt\" srclang=\"sv\" label=\"Svenska\">\n</audio>\n<!-------------demo---------------->\n<audio autoplay=\"autoplay\" controls=\"controls\">\n    <source src=\"file.ogg\" />\n    <source src=\"file.mp3\" />\n    <a href=\"file.mp3\">Download this file.</a>\n</audio>', NULL, '2016-1-16 19:11:05', '2016-3-26 00:50:43', 0, 0);
