INSERT INTO `demo` VALUES (223, 00000000222, 1, 0, 'css', 'CSS3的:nth选择器', '关键词', 'nth-child()/:nth-of-type(),可以是1234还有n，even odd，注意不能是0', ':first-child{color:gray;}/*选择某个元素的第一个子元素；ie6+*/\n:last-child{color:gray;}/*选择某个元素的最后一个子元素；*/\n:nth-child(){color:gray;}/*选择某个元素的一个或多个特定的子元素；*/\n:nth-child(num);/*参数是具体数字*/\n/*倍数相关*/\n:nth-child(n);/*参数是n,n从0开始计算,请注意了，这里的“n”只能是\"n\"，不能使用其他字母代替，不然会没有任何效果的。*/\n.datepicker tr:nth-child(1) th:nth-child(2)\n:nth-child(n*num)/*n的倍数选择，n从0开始算*/\n.cell:nth-child(n+5)/*一行四个，从第二行骑没有margin-bottom  0123+5*/\n:nth-child(n+num);/*选择大于num后面的元素*/\n:nth-child(-n+num)/*选择小于num前面的元素*/\n:nth-child(n*num+1);/*表示隔几选一*/\n:nth-last-child(){color:gray;}/*选择某个元素的一个或多个特定的子元素，从这个元素的最后一个子元素开始算；*/\n/*强类型相关*/\n:nth-of-type(){color:gray;}/*比如div下有好多p元素，li元素，img元素等  ie9+*/\n:nth-of-type(even)\n:nth-of-type(2n)\n.demo p:nth-of-type(even) {background-color: lime;}\n\n:nth-last-of-type(){color:gray;}/*选择指定的元素，从元素的最后一个开始计算；*/\n:first-of-type{color:gray;}/*选择一个上级元素下的第一个同类子元素；*/\n:last-of-type{color:gray;}/*选择一个上级元素的最后一个同类子元素；*/\n:only-child{color:gray;}/*选择的元素是它的父元素的唯一一个了元素；*/\n:only-of-type{color:gray;}/*选择一个元素是它的上级元素的唯一一个相同类型的子元素；*/\n\n:empty{color:gray;}/*选择的元素里面没有任何内容。*/\n\n/*区别*/\n.demo .post p:only-child {background: red;}/*只有一个元素，而且是p*/\np:only-of-type{background-color:red;}/*可以又个元素，只有一个p；比如下面这个demo是可以选择到的*/\n<div class=\"post\">\n    <div>Lorem ipsum dolor sit amet, consectetur</div>\n    <p>Lorem ipsum dolor sit amet, consectetur</p>\n    <div>Lorem ipsum dolor sit amet, consectetur</div>\n</div>\n', NULL, '2016-1-30 10:16:06', '2016-4-5 23:33:51', 0, 0);
INSERT INTO `demo` VALUES (224, 00000000222, 1, 0, 'html', 'ui元素状态伪类', '关键词', '描述', '<input type=\"text\"> :enabled;:disabled  可写与不可写，ie9+\n<input type=\"radio\"><input type=\"checkbox\"> :checked;:unchecked  ie9+', NULL, '2016-1-30 10:19:32', '2016-1-30 10:25:02', 0, 0);
INSERT INTO `demo` VALUES (225, 00000000222, 1, 0, 'css', '动态伪类', '关键词', '描述', 'a:link {color:gray;}/*链接没有被访问时前景色为灰色*/\na:visited{color:yellow;}/*链接被访问过后前景色为黄色*/\na:hover{color:green;}/*鼠标悬浮在链接上时前景色为绿色*/\na:active{color:blue;}/*鼠标点中激活链接那一下前景色为蓝色*/\n*:hover{color:blue;}/*用于当用户把鼠标移动到元素上面时的效果；*/\n*:active{color:blue;}/*用于用户点击元素那一下的效果（正发生在点的那一下，松开鼠标左键此动作也就完成了）*/\n*:focus{color:blue;}/*用于元素成为焦点，这个经常用在表单元素上。*/', NULL, '2016-1-30 10:23:55', '2016-1-30 10:28:33', 0, 0);
INSERT INTO `demo` VALUES (226, 00000000222, 1, 0, 'css', '否定选择器', '关键词', '描述', 'input:not([type=\"submit\"]) {border: 1px solid red;}\n._34yh ._588p a:not([role=\"button\"])/*引自facebook*/\n.datepicker table tr td.day:hover:not(.new):not(.old):not(.disabled), .datepicker table tr td.day.active:not(.new):not(.old):not(.disabled){\n    background-color: #00a2e6;\n    color:#fff;\n}', NULL, '2016-1-30 10:23:56', '2016-2-24 14:32:50', 0, 0);
INSERT INTO `demo` VALUES (227, 00000000222, 1, 0, 'css', '伪元素', '关键词', '两个“：：”和一个“：”css3中主要用来区分伪类和伪元素，到目前来说，这两种方式都是被接受的，也就是说不管使用哪种写法所起的作用都是一样的，只是一个书写格式不同而以。', '::first-letter{};\n::first-line{};\n::before{};\n::after{};', NULL, '2016-1-30 10:51:42', '2016-1-30 10:53:47', 0, 0);
