INSERT INTO `demo` VALUES (295, 00000000292, 1, 0, 'js', '资源链接', '关键词', '', '//官方教程\nhttps://docs.angularjs.org/tutorial/step_12\n//经验总结\nhttp://www.cnblogs.com/hubcarl/p/4207909.html\n中文社区的中英文双文档\nhttp://docs.angularjs.cn/api', NULL, '2016-2-24 09:36:43', '2016-3-19 14:18:39', 0, 0);
INSERT INTO `demo` VALUES (296, 00000000214, 1, 0, 'css', 'placeholder的样式修改', '关键词', '存在兼容问题！', '::-webkit-input-placeholder { /* WebKit browsers */\n    color:    #fff;\n}\n:-moz-placeholder { /* Mozilla Firefox 4 to 18 */\n    color:    #fff;\n}\n::-moz-placeholder { /* Mozilla Firefox 19+ */\n    color:    #fff;\n}\n:-ms-input-placeholder { /* Internet Explorer 10+ */\n    color:    #fff;\n}', NULL, '2016-2-24 11:08:07', '2016-2-24 11:08:56', 0, 0);
INSERT INTO `demo` VALUES (297, 00000000163, 1, 0, 'js', 'jq解绑事件', '关键词', '', '$($0).unbind();\n$($0).unbind(\"click\");\n$($0).click=null;', NULL, '2016-2-24 14:56:05', '2016-2-24 14:56:52', 0, 0);
INSERT INTO `demo` VALUES (298, 00000000259, 1, 0, 'html', 'canvas颜色叠加规则', '关键词', '', '<!DOCTYPE html>\n<html>\n<head>\n<style>\ncanvas\n{\nborder:1px solid #d3d3d3;\nmargin-right:10px;\nmargin-bottom:20px;    \n}\n</style>\n</head>\n<body>\n<script>\n// globalCompositeOperation 属性说明了绘制到画布上的颜色是如何与画布上已有的颜色组合起来的。下面列出了其中可能要设置的值以及它们的含义。这些值中的source一词指的是将要绘制到画布上的颜色，而destination指的是画布上已经存在的颜色，其默认值是source-over。\n// copy：只绘制新图形，删除其他所有内容。\n// darker：在图形重叠的地方，其颜色由两个颜色值相减后决定。\n// destination-atop：画布上已有的内容只会在它和新图形重叠的地方保留。新图形绘制于内容之后。\n// destination-in：在新图形及画布上已有图形重叠的地方，画布上已有内容都保留。所有其他内容均为透明的。\n// destination-out：在画布上已有内容和新图形不重叠的地方，已有内容保留。所有其他内容均为透明的。\n// destination-over：新图形绘制于画布上已有内容的后面。\n// lighter：在图形重叠的地方，其颜色由两种颜色值的加值来决定。\n// source-atop：只有在新图形和画布上已有内容重叠的地方才绘制新图形。\n// source-in：在新图形以及画布上已有内容重叠的地方才绘制新图形。所有其他内容均为透明的。\n// ource-out：只有在和画布上已有图形不重叠的地方才绘制新图形。\n// source-over：新图形绘制于画布上已有图形的顶部。这是默认的设置。\n// xor：在重叠和正常绘制的其他地方，图形都成为透明的。\nvar gco=new Array();\ngco.push(\"source-atop\");\ngco.push(\"source-in\");\ngco.push(\"source-out\");\ngco.push(\"source-over\");\ngco.push(\"destination-atop\");\ngco.push(\"destination-in\");\ngco.push(\"destination-out\");\ngco.push(\"destination-over\");\ngco.push(\"lighter\");\ngco.push(\"copy\");\ngco.push(\"xor\");\nfor (n=0;n<gco.length;n++)\n    {\n    document.write(\"<div id=\'p_\" + n + \"\' style=\'float:left;\'>\" + gco[n] + \":<br>\");\n    var c=document.createElement(\"canvas\");\n    c.width=120;\n    c.height=100;\n    document.getElementById(\"p_\" + n).appendChild(c);\n    var ctx=c.getContext(\"2d\");    \n    ctx.fillStyle=\"blue\";\n    ctx.fillRect(10,10,50,50);\n    ctx.globalCompositeOperation=gco[n];\n    ctx.beginPath();\n    ctx.fillStyle=\"red\";\n    ctx.arc(50,50,30,0,2*Math.PI);\n    ctx.fill();\n    document.write(\"</div>\");    \n    }\n\n</script>\n\n</body>\n</html>', NULL, '2016-2-24 16:19:46', '2016-2-24 16:21:33', 0, 0);
INSERT INTO `demo` VALUES (299, 00000000259, 1, 0, 'js', 'js控制canvas画星星评价', '关键词', '控制图片的时候需要将操作函数写入onload中去异步处理！发现同步时候在firefox造成了绘图失败', 'function getstar(str,width,height){\n    var x = document.createElement(\"CANVAS\");\n    x.width=width;\n    x.height=height;\n    var ctx=x.getContext(\"2d\");\n    var img = new Image();\n    img.onload=function(){\n        ctx.drawImage(img,0,0,200,32,0,0,width,height);\n        ctx.fillStyle=\"#FFD800\";\n        ctx.globalCompositeOperation=\"source-atop\";\n        var float = parseFloat(str);\n        var widthRate = float/5;\n        if(widthRate<0||widthRate>1){\n            widthRate =0;\n        }\n        var wid = 100*widthRate;\n        ctx.fillRect(0,0,wid,height);\n    }\n    img.src=\"data:image/png;base64,\";\n    return x;\n}\n$(\"body\").prepend(getstar(4.5));\n//========================================================\n//看一个别人的demo，js生成图片，然后插入到文档的流程\nfunction myFunction()\n{\nvar x = document.createElement(\"CANVAS\");\nvar ctx=x.getContext(\"2d\");\nctx.fillStyle=\"#FF0000\";\nctx.fillRect(20,20,150,100);\ndocument.body.appendChild(x);\n}\n//于是上面的函数改为：\nfunction getstar(str){\nvar x = document.createElement(\"CANVAS\");\nvar ctx=x.getContext(\"2d\");\nvar img = new Image();\nimg.src=\"...\";\nctx.drawImage(img,0,0,200,32,0,0,100,16);\ncxt.fillStyle=\"#FFD800\";\nvar float = parseFloat(str);\nvar widthRate = float/5;\nif(widthRate <0||widthRate >1){\nwidthRate =0;\n}\nvar wid = 100*widthRate;\ncxt.fillRect(0,0,wid,16);\nreturn x;\n}', NULL, '2016-2-24 18:38:42', '2016-2-25 10:35:40', 0, 0);
INSERT INTO `demo` VALUES (300, 00000000292, 1, 0, 'html', '基本概念理论', '关键词', '', '<!--单向:-->\n向外输出：\nng-bind=\"变量名\"或者{{变量名}}\n向内输入：\nng-click=fn;\n$scope.fn=function(){\n$scope.name=\"小张\";\n}\n<!--双向:-->\nng-model=\"变量名字\"\n<!--模块module:-->\nvar app = angular.module(\"myapp\",[]);定义一个名字为\"myapp\"的模块，返回到变量app，继续后续操作\n然后需要在dom中声明module的作用域范围\n<html ng-app=\"myapp\"></html>\n<body ng-app=\"myapp\"></body>\n<div ng-app=\"myapp\"></div>\n<!--控制器controller:-->\n它是在模块的基础上声明的，声明它以前必须先声明一个模块\napp.control(\"myctrl\",function($scope){\n$scope.name=\"张三\";//$scope将作为控制器的根对象参与编程，是从参数传入的，控制器的所有东西都要挂在这个变量上\n$scope.play=$.noop;\n});\n声明完之后绑定到dom中，就可以工作了！\n<div ng-controller=\"myctrl\">\n', NULL, '2016-2-25 09:25:24', '2016-3-19 15:10:20', 0, 0);
INSERT INTO `demo` VALUES (301, 00000000162, 1, 0, 'js', 'math对象', '关键词', '描述', '新代码', NULL, '2016-2-25 10:44:36', '2016-2-25 10:44:36', 0, 0);
INSERT INTO `demo` VALUES (302, 00000000301, 1, 0, 'js', '基本方法', '关键词', 'Math无需实例化，内置对象，直接调用即可', '//----------属性\nMath.E;                    //返回算术常量 e，即自然对数的底数（约等于2.718）。\nMath.LN2;                //返回 2 的自然对数（约等于0.693）。\nMath.LN10;                //返回 10 的自然对数（约等于2.302）。\nMath.LOG2E;                //返回以 2 为底的 e 的对数（约等于 1.414）。\nMath.LOG10E;            //返回以 10 为底的 e 的对数（约等于0.434）。\nMath.PI;                //返回圆周率（约等于3.14159）。\nMath.SQRT1_2;            //返回返回 2 的平方根的倒数（约等于 0.707）。\nMath.SQRT2;                //返回 2 的平方根（约等于 1.414）。\n//----------方法\nMath.abs(x);             //返回数的绝对值。\nMath.ceil(x);             //对数进行上舍入。\nMath.random();             //返回 0 ~ 1 之间的随机数。\nMath.round(x);             //把数四舍五入为最接近的整数。\nMath.floor(x);             //对数进行下舍入。\nMath.max(x,y);             //返回 x 和 y 中的最高值。\nMath.min(x,y);             //返回 x 和 y 中的最低值。\nMath.acos(x);             //返回数的反余弦值。\nMath.asin(x);             //返回数的反正弦值。\nMath.atan(x);             //以介于 -PI/2 与 PI/2 弧度之间的数值来返回 x 的反正切值。\nMath.atan2(y,x);         //返回从 x 轴到点 (x,y) 的角度（介于 -PI/2 与 PI/2 弧度之间）。\nMath.cos(x);               //返回数的余弦。\nMath.exp(x);            //返回 e 的指数。\nMath.log(x);               //返回数的自然对数（底为e）。\nMath.pow(x,y);             //返回 x 的 y 次幂。\nMath.sin(x);               //返回数的正弦。\nMath.sqrt(x);             //返回数的平方根。\nMath.tan(x);               //返回角的正切。\nMath.toSource();         //返回该对象的源代码。\nMath.valueOf();         //返回 Math 对象的原始值。', NULL, '2016-2-25 10:44:48', '2016-2-25 10:52:53', 0, 0);
INSERT INTO `demo` VALUES (303, 00000000163, 1, 0, 'js', '状态码404,501,301', '关键词', '', '200请求已成功，请求所希望的响应头或数据体将随此响应返回\n301 Moved Permanently资源已永久移动到新位置\n401 Unauthorized用户需要验证\n403 Forbidden服务器正确接受请求，但是拒绝请求\n405请求方法不支持，post或者get不支持\n501 Not Implemented服务器不识别不支持\n502 Bad Gateway网关或代理无效响应\n503 Service Unavailable\n服务气维护或者过载，临时拒绝\n由于临时的服务器维护或者过载，服务器当前无法处理请求。这个状况是临时的，并且将在一段时间以后恢复。如果能够预计延迟时间，那么响应中可以包含一个 Retry-After 头用以标明这个延迟时间。如果没有给出这个 Retry-After 信息，那么客户端应当以处理500响应的方式处理它。\n注意：503状态码的存在并不意味着服务器在过载的时候必须使用它。某些服务器只不过是希望拒绝客户端的连接。', NULL, '2016-2-25 10:58:29', '2016-2-25 10:59:04', 0, 0);
INSERT INTO `demo` VALUES (304, 00000000255, 1, 0, 'html', 'calc[\'kælk]计算', '关键词', 'IE9+、FF4.0+、Chrome19+、Safari6+', 'div{width:calc(100%-200)}\n注意上面这个是错的，计算符号是要左右留空格的，否则无效\ndiv{\n    width:-webkit-calc(100% - 200px);\n    width:-moz-calc(100% - 200px);\n    width:calc(100% - 200px);\n}\nli{\n  width:calc(100% + 143px)\n}', NULL, '2016-2-25 13:10:40', '2016-3-24 15:41:22', 0, 0);
