INSERT INTO `demo` VALUES (306, 00000000305, 1, 0, 'js', 'jquery插件分析', '关键词', '描述', '新代码', NULL, '2016-2-25 17:06:31', '2016-2-25 17:06:31', 0, 0);
INSERT INTO `demo` VALUES (307, 00000000306, 1, 0, 'js', 'lazyload源码', '关键词', '', '/*\n * Lazy Load - jQuery plugin for lazy loading images\n *\n * Copyright (c) 2007-2013 Mika Tuupola\n *\n * Licensed under the MIT license:\n *   http://www.opensource.org/licenses/mit-license.php\n *\n * Project home:\n *   http://www.appelsiini.net/projects/lazyload\n *\n * Version:  1.9.3\n *\n */\n(function($, window, document, undefined) {\n    var $window = $(window);\n    $.fn.lazyload = function(options) {\n        var elements = this;\n        var $container;\n        var settings = {\n            threshold       : 0,\n            failure_limit   : 0,\n            event           : \"scroll\",\n            effect          : \"show\",\n            container       : window,\n            data_attribute  : \"original\",\n            skip_invisible  : true,\n            appear          : null,\n            load            : null,\n            placeholder     : \"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAAAJcEhZcwAADsQAAA7EAZUrDhsAAAANSURBVBhXYzh8+PB/AAffA0nNPuCLAAAAAElFTkSuQmCC\"\n        };\n        function update() {\n            var counter = 0;\n            elements.each(function() {\n                var $this = $(this);\n                if (settings.skip_invisible && !$this.is(\":visible\")) {\n                    return;\n                }\n                if ($.abovethetop(this, settings) ||\n                    $.leftofbegin(this, settings)) {\n                        /* Nothing. */\n                } else if (!$.belowthefold(this, settings) &&\n                    !$.rightoffold(this, settings)) {\n                        $this.trigger(\"appear\");\n                        /* if we found an image we\'ll load, reset the counter */\n                        counter = 0;\n                } else {\n                    if (++counter > settings.failure_limit) {\n                        return false;\n                    }\n                }\n            });\n        }\n        if(options) {\n            /* Maintain BC for a couple of versions. */\n            if (undefined !== options.failurelimit) {\n                options.failure_limit = options.failurelimit;\n                delete options.failurelimit;\n            }\n            if (undefined !== options.effectspeed) {\n                options.effect_speed = options.effectspeed;\n                delete options.effectspeed;\n            }\n            $.extend(settings, options);\n        }\n        /* Cache container as jQuery as object. */\n        $container = (settings.container === undefined ||\n                      settings.container === window) ? $window : $(settings.container);\n        /* Fire one scroll event per scroll. Not one scroll event per image. */\n        if (0 === settings.event.indexOf(\"scroll\")) {\n            $container.bind(settings.event, function() {\n                return update();\n            });\n        }\n        this.each(function() {\n            var self = this;\n            var $self = $(self);\n            self.loaded = false;\n            /* If no src attribute given use data:uri. */\n            if ($self.attr(\"src\") === undefined || $self.attr(\"src\") === false) {\n                if ($self.is(\"img\")) {\n                    $self.attr(\"src\", settings.placeholder);\n                }\n            }\n            /* When appear is triggered load original image. */\n            $self.one(\"appear\", function() {\n                if (!this.loaded) {\n                    if (settings.appear) {\n                        var elements_left = elements.length;\n                        settings.appear.call(self, elements_left, settings);\n                    }\n                    $(\"<img />\")\n                        .bind(\"load\", function() {\n                            var original = $self.attr(\"data-\" + settings.data_attribute);\n                            $self.hide();\n                            if ($self.is(\"img\")) {\n                                $self.attr(\"src\", original);\n                            } else {\n                                $self.css(\"background-image\", \"url(\'\" + original + \"\')\");\n                            }\n                            $self[settings.effect](settings.effect_speed);\n                            self.loaded = true;\n                            /* Remove image from array so it is not looped next time. */\n                            var temp = $.grep(elements, function(element) {\n                                return !element.loaded;\n                            });\n                            elements = $(temp);\n                            if (settings.load) {\n                                var elements_left = elements.length;\n                                settings.load.call(self, elements_left, settings);\n                            }\n                        })\n                        .attr(\"src\", $self.attr(\"data-\" + settings.data_attribute));\n                }\n            });\n            /* When wanted event is triggered load original image */\n            /* by triggering appear.                              */\n            if (0 !== settings.event.indexOf(\"scroll\")) {\n                $self.bind(settings.event, function() {\n                    if (!self.loaded) {\n                        $self.trigger(\"appear\");\n                    }\n                });\n            }\n        });\n        /* Check if something appears when window is resized. */\n        $window.bind(\"resize\", function() {\n            update();\n        });\n        /* With IOS5 force loading images when navigating with back button. */\n        /* Non optimal workaround. */\n        if ((/(?:iphone|ipod|ipad).*os 5/gi).test(navigator.appVersion)) {\n            $window.bind(\"pageshow\", function(event) {\n                if (event.originalEvent && event.originalEvent.persisted) {\n                    elements.each(function() {\n                        $(this).trigger(\"appear\");\n                    });\n                }\n            });\n        }\n        /* Force initial check if images should appear. */\n        $(document).ready(function() {\n            update();\n        });\n        return this;\n    };\n    /* Convenience methods in jQuery namespace.           */\n    /* Use as  $.belowthefold(element, {threshold : 100, container : window}) */\n    $.belowthefold = function(element, settings) {\n        var fold;\n        if (settings.container === undefined || settings.container === window) {\n            fold = (window.innerHeight ? window.innerHeight : $window.height()) + $window.scrollTop();\n        } else {\n            fold = $(settings.container).offset().top + $(settings.container).height();\n        }\n        return fold <= $(element).offset().top - settings.threshold;\n    };\n    $.rightoffold = function(element, settings) {\n        var fold;\n        if (settings.container === undefined || settings.container === window) {\n            fold = $window.width() + $window.scrollLeft();\n        } else {\n            fold = $(settings.container).offset().left + $(settings.container).width();\n        }\n        return fold <= $(element).offset().left - settings.threshold;\n    };\n    $.abovethetop = function(element, settings) {\n        var fold;\n        if (settings.container === undefined || settings.container === window) {\n            fold = $window.scrollTop();\n        } else {\n            fold = $(settings.container).offset().top;\n        }\n        return fold >= $(element).offset().top + settings.threshold  + $(element).height();\n    };\n    $.leftofbegin = function(element, settings) {\n        var fold;\n        if (settings.container === undefined || settings.container === window) {\n            fold = $window.scrollLeft();\n        } else {\n            fold = $(settings.container).offset().left;\n        }\n        return fold >= $(element).offset().left + settings.threshold + $(element).width();\n    };\n    $.inviewport = function(element, settings) {\n         return !$.rightoffold(element, settings) && !$.leftofbegin(element, settings) &&\n                !$.belowthefold(element, settings) && !$.abovethetop(element, settings);\n     };\n    /* Custom selectors for your convenience.   */\n    /* Use as $(\"img:below-the-fold\").something() or */\n    /* $(\"img\").filter(\":below-the-fold\").something() which is faster */\n    $.extend($.expr[\":\"], {\n        \"below-the-fold\" : function(a) { return $.belowthefold(a, {threshold : 0}); },\n        \"above-the-top\"  : function(a) { return !$.belowthefold(a, {threshold : 0}); },\n        \"right-of-screen\": function(a) { return $.rightoffold(a, {threshold : 0}); },\n        \"left-of-screen\" : function(a) { return !$.rightoffold(a, {threshold : 0}); },\n        \"in-viewport\"    : function(a) { return $.inviewport(a, {threshold : 0}); },\n        /* Maintain BC for couple of versions. */\n        \"above-the-fold\" : function(a) { return !$.belowthefold(a, {threshold : 0}); },\n        \"right-of-fold\"  : function(a) { return $.rightoffold(a, {threshold : 0}); },\n        \"left-of-fold\"   : function(a) { return !$.rightoffold(a, {threshold : 0}); }\n    });\n})(jQuery, window, document);\n', NULL, '2016-2-25 17:07:20', '2016-6-3 15:03:10', 0, 0);
INSERT INTO `demo` VALUES (661, 00000000240, 1, 0, 'js', 'create DOM', '关键词', '', 'var iframe = document.createElement(\"iframe\");\niframe.setAttribute(\"frameborder\", 0);\niframe.setAttribute(\"scrolling\", \"no\");\niframe.setAttribute(\"src\", viewUrl+\"&auto_play=0&gpcflag=1&width=354&height=264\");\niframe.setAttribute(\"style\",\"display:block;width:354px;height:264px;\");\nviewEle.html(iframe);', NULL, '2016-6-3 18:03:13', '2016-6-3 18:04:00', 0, 0);
INSERT INTO `demo` VALUES (662, 00000000310, 1, 0, 'html', '基于simsun字的箭头', '关键词', 'font-family: simsun;,纯边框也是采用两个标志摞起来的办法', '<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n<style>\n\n    /* poptip */\n.poptip{position: absolute;top: 20px;left:20px;padding: 6px 10px 5px;*padding: 7px 10px 4px;line-height: 16px;color: #DB7C22;font-size: 12px;background-color: #FFFCEF;border: solid 1px #FFBB76;border-radius: 2px;box-shadow: 0 0 3px #ddd;}\n.poptip-arrow{position: absolute;overflow: hidden;font-style: normal;font-family: simsun;font-size: 12px;text-shadow:0 0 2px #ccc;}\n \n.poptip-arrow em,.poptip-arrow i{position: absolute;left:0;top:0;font-style: normal;}\n.poptip-arrow em{color: #FFBB76;}\n.poptip-arrow i{color: #FFFCEF;text-shadow:none;}\n \n.poptip-arrow-top,.poptip-arrow-bottom{height: 6px;width: 12px;left:12px;margin-left:-6px;}\n.poptip-arrow-left,.poptip-arrow-right{height: 12px;width: 6px;top: 12px;margin-top:-6px;}\n \n.poptip-arrow-top{top: -6px;}\n.poptip-arrow-top em{top: -1px;}\n.poptip-arrow-top i{top: 0px;}\n \n.poptip-arrow-bottom{bottom: -6px;}\n.poptip-arrow-bottom em{top: -8px;}\n.poptip-arrow-bottom i{top: -9px;}\n \n.poptip-arrow-left{left:-6px;}\n.poptip-arrow-left em{left:1px;}\n.poptip-arrow-left i{left:2px;}\n \n.poptip-arrow-right{right:-6px;}\n.poptip-arrow-right em{left:-6px;}\n.poptip-arrow-right i{left:-7px;}\n</style>    \n</head>\n<body>\n    \n<div class=\"poptip\">\n    <span class=\"poptip-arrow poptip-arrow-top\"><em>◆</em><i>◆</i></span>\n    <span class=\"poptip-arrow poptip-arrow-right\"><em>◆</em><i>◆</i></span>\n    <span class=\"poptip-arrow poptip-arrow-bottom\"><em>◆</em><i>◆</i></span>\n    <span class=\"poptip-arrow poptip-arrow-left\"><em>◆</em><i>◆</i></span>\n    Hi，知道吗？ <br>大前端D7主题很快就疯抢了！\n</div>\n</body>\n</html>', NULL, '2016-6-6 09:46:36', '2016-6-6 09:47:25', 0, 0);
