INSERT INTO `demo` VALUES (665, 00000000664, 1, 0, 'js', '调试输出', '关键词', '', 'echo(\"hellow world\");\nprint();\nprint_r()//可打印数组\nvar_dump()//打印数组,带数据类型\nvar_dump($_GET)//查看整个get\nvar_dump($_SERVER);//服务器信息!\nvar_dump(get_defined_vars());//返回了所有的变量!厉害!\nvar_dump(get_defined_functions());//所有可用函数\nprint_r(json_encode(obj));//返回json格式的数据', NULL, '2016-6-6 10:51:47', '2016-6-7 18:33:29', 0, 0);
INSERT INTO `demo` VALUES (666, 00000000566, 1, 0, 'js', 'smarty 模版', '关键词', '描述', '新代码', NULL, '2016-6-6 14:18:31', '2016-6-6 14:18:31', 0, 0);
INSERT INTO `demo` VALUES (667, 00000000666, 1, 0, 'js', '基本', '关键词', '{append}//运行时修改数组\n{assign}//运行时赋值\n{block}/模版继承\n{call}模版自定一函数的调用\n{capture}//模版分块复用\n{config_load}//配置中取值\n{function}//版本内函数\n{extends}模版继承\n{include}//引入其他模版,变量均可用\n{ldelim},{rdelim}//修正编辑符号{}\n{literal}//免解析\n{nocache}//某一块的缓存设置\n{section},{sectionelse}//遍历\n{setfilter}//过滤\n{strip}//换行空格等的修复', '版本:{var_dump($smarty.version)} //Smarty-3.1.21-devi\n----------------------------内置函数:\n//for循环\n<ul>\n{for $foo=1 to 3}\n    <li>{$foo}</li>\n{/for}\n</ul>\n//foreach\n<ul>\n{foreach $myPeople as $value}\n   <li>{$value@key}: {$value}</li>\n{/foreach}\n</ul>\n//while\n{while $foo > 0}\n  {$foo--}\n{/while}\n----------------------------调试模式:\n{debug}\n----------------------------条件判断\n//if else:\n<{if $temp gt 0}>\n临时变量>0\n<{else}>\n临时变量<=0\n<{/if}>\neq //判断是否相等\nneq、ne //不相等\nlt //小于\nlte //小于等于\ngt //大于\ngte //大于等于\nis div by //被某数整除\nis even //为偶数\nis odd //为奇数\n//例子:\n{if $name eq \'Fred\'}\n    Welcome Sir.\n{elseif $name eq \'Wilma\'}\n    Welcome Ma\'am.\n{else}\n    Welcome, whatever you are.\n{/if}\n{if $name eq \'Fred\' or $name eq \'Wilma\'}//an example with \"or\" logic\n   ...\n{/if}\n{if $name == \'Fred\' || $name == \'Wilma\'}// same as above\n   ...\n{/if}\n{if ( $amount < 0 or $amount > 1000 ) and $volume >= #minVolAmt#}// parenthesis are allowed\n   ...\n{/if}\n{if count($var) gt 0}// you can also embed php function calls\n   ...\n{/if}\n{if is_array($foo) }// check for array.\n   .....\n{/if}\n{if isset($foo) }// check for not null.\n   .....\n{/if}\n----------------------------------变量操作\n{assign var=\"icount\" value=1}\n{$icount = $icount +1}\n\n{assign var=\"name\" value=\"韩灵稚\" nocache=”false”scope=”global”}\n//在模板中定义的变量，如果之前定义了相同的变量，则以最后一次定义为准。\n{$name=\"韩灵稚\"}    //给变量直接赋值，如果该变量原来不存在，自动创建，3.0新特性。\n{assign var=foo value=[1,2,3]}     //定义普通数组变量\n{assign var=foo value=[\'y\'=>\'yellow\',\'b\'=>\'blue\']}    //定义关联数组\n{assign var=foo value=[1,[9,8],3]}  //定义数组中的数组\n{$foo[]=1}    //增加变量数组$foo的一个元素\n<span>你好， {$name}</span> //在模板文件中使用\n', NULL, '2016-6-6 14:18:39', '2016-6-27 09:49:08', 0, 0);
