INSERT INTO `demo` VALUES (669, 00000000668, 1, 0, 'js', '常用功能介绍', '关键词', '1编译文档型：比如编译LESS、Sass、Stylus、Coffeescript等；\n 2文件操作型：比如说合并、压缩JavaScript、CSS、图片等；\n 3质量保障型：比如JSHint、Jasmin、Mocha等；\n 4类库构建型：比如说Backbone.js、ember.js、angular.js等。', '    新数据  ', NULL, '2016-6-7 07:52:47', '2016-6-7 07:53:23', 0, 0);
