INSERT INTO `demo` VALUES (671, 00000000654, 1, 0, 'html', '小图文的遍历', '关键词', '目前有bug:\n  {\n    \'NAME\': \'衬衫\',\n    \'URL\': \'//www.jd.com\',\n    \'PIC\': \'//img11.360buyimg.com/cms/jfs/t2674/18/2062720729/5646/f249f87d/575678f1Nce7aab21.png\',\n    \'NAME1\': \'\',\n    \'NAME2\': \'\',\n    \'ANCHOR\': \'\',\n    \'bgColor\': \'\',\n    \'PICHEIGHT\': \'\',\n    \'PICWIDTH\': \'\',\n    \'PIC2\': \'//img10.360buyimg.com/cms/\',\n    \'URL2\': \'\',\n    \'CUSTOM1\': \'\',\n    \'CUSTOM2\': \'\',\n    \'id\': \'34433\'\n  }', '<!-- 单图 -->\n{$portal_cell_id = $portal_cell_id + 1}\n<img data-lazy-img=\"{{{$newsPic}}[0].PIC}\" width=\"{{{$newsPic}}[0].PICWIDTH}\" height=\"{{{$newsPic}}[0].PICHEIGHT}\" >\n<!-- 多图 -->\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsPic}}}\n  <li>\n      <p class=\"p-name\">{{{$newsPic}}[sn].NAME}</p>\n      <p class=\"p-jian\">{{{$newsPic}}[sn].NAME1}</p>\n      <p class=\"p-type\">{{{$newsPic}}[sn].NAME2}</p>\n      <a href=\"{{{$newsPic}}[sn].URL}\">\n          <img data-lazy-img=\"{{{$newsPic}}[sn].PIC}\" >\n      </a>\n  </li>\n{/section}\n<!-- 带子集,包含子集的例子:cms尚未实现 -->\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsPic}}}\n    <li class=\"fore{$smarty.section.sn.index+1}\">\n        <h3>{{{$newsPic}}[sn].NAME}</h3>\n        <div class=\"link-list\">\n            {assign var=\"icount\" value=1}\n            {section name=ch loop={{$newsPic}}[sn].children}\n                <a href=\"{{{$newsPic}}[sn].children[ch].URL}\" title=\"{{{$newsPic}}[sn].children[ch].NAME}\" target=\"_blank\"  clstag=\"channel|keycount|{$portal_id}|LINK{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}_{$icount}\">{{{$newsPic}}[sn].children[ch].NAME}</a>\n                {$icount = $icount +1}\n            {/section}\n        </div>\n    </li>\n{/section}', NULL, '2016-6-7 15:05:44', '2016-6-12 15:31:19', 0, 0);
INSERT INTO `demo` VALUES (672, 00000000654, 1, 0, 'html', '文字链的遍历', '关键词', '{\n    \'NAME\': \'商务西装\',\n    \'URL\': \'//www.jd.com\',\n    \'YFLAG\': \'1\',\n    \'ANCHOR\': \'\',\n    \'property\': \'\',\n    \'YFTA\': \'1\',\n    \'CUSTOM1\': \'外套\',\n    \'id\': \'34416\'\n  }', '<!-- 多文字 -->\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsTitle}}}\n<a href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n{/section}\n<!-- 是否标红 -->\n{section name=sn loop={{$newsTitle}}}\n    {if {{$newsTitle}}[sn].YFLAG eq \'1\'}\n        <a href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\" class=\"txt-lh\">{{{$newsTitle}}[sn].NAME}</a>\n    {else}\n        <a href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {/if}\n{/section}\n<!-- 带子集 -->\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsTitle}}}\n    <h3 class=\"item-title\">{{{$newsTitle}}[sn].NAME}</h3>\n    <div class=\"item-cont\">\n        {assign var=\"icount\" value=1}\n        {section name=ch loop={{$newsTitle}}[sn].children}\n            <a href=\"{{{$newsTitle}}[sn].children[ch].URL}\" title=\"{{{$newsTitle}}[sn].children[ch].NAME}\" target=\"_blank\"  clstag=\"channel|keycount|{$portal_id}|FLA{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}_{$icount}\">{{{$newsTitle}}[sn].children[ch].NAME}</a>\n        {$icount = $icount +1}\n        {/section}\n    </div>\n{/section}', NULL, '2016-6-7 15:06:21', '2016-6-12 17:33:09', 0, 0);
INSERT INTO `demo` VALUES (673, 00000000654, 1, 0, 'js', '打印出变量', '关键词', '1.支持print_r和var_dump两个命令,套以json_encode();可以直接查看对象的数据结构\n2.这条php命令需要有{}包裹,变量也要由{{}}包裹', '{print_r(json_encode({{$newsPic}}))}\n{var_dump(json_encode({{$newsPic}}))}', NULL, '2016-6-7 18:34:20', '2016-6-7 18:40:14', 0, 0);
INSERT INTO `demo` VALUES (674, 00000000654, 1, 0, 'html', '商品池的遍历', '关键词', '数据结构\n[\n  {\n    \'categoryName\': \'1348\',\n    \'title\': \'C2潮朝  短袖衬衫夏季新品13-14-15-16-17-18到20岁的男孩加肥加大 西瓜红 XL\',\n    \'picUrl\': \'//img13.360buyimg.com/n2/jfs/t2683/242/2073388937/198310/9df33d6f/5757a4a9N2d20942c.jpg\',\n    \'picUrl80\': \'//img13.360buyimg.com/cms/jfs/t2683/242/2073388937/198310/9df33d6f/5757a4a9N2d20942c.jpg\',\n    \'picUrl20\': \'jfs/t2683/242/2073388937/198310/9df33d6f/5757a4a9N2d20942c.jpg\',\n    \'spuId\': \'10086838868\',\n    \'skuId\': 10403296938,\n    \'commodityId\': 10403296938,\n    \'picSize\': 2,\n    \'position\': 1,\n    \'url\': \'//item.jd.com/10403296938.html\',\n    \'pool\': \'7464\',\n    \'shortPromoteText\':\'促销语\',//附加字段\n    \'tag\':\'利益点\',//附加字段\n    \'promoteText\':\'推荐文案\',//附加字段\n    \'desc\':\'备注\'//附加字段\n  }\n]', '{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$commodity_pool}}}\n    <a class=\"cutclass\" title=\"{{{$commodity_pool}}[sn].title}\" href=\"{{{$commodity_pool}}[sn].url}\" target=\"_blank\">{{{$commodity_pool}}[sn].title}</a>\n{/section}', NULL, '2016-6-8 13:18:46', '2016-6-12 14:29:01', 0, 0);
INSERT INTO `demo` VALUES (675, 00000000654, 1, 0, 'js', '数组长度的判断', '关键词', '', '{if {{$commodity_pool}}|@count neq 1 }//数组长度如果为1\n12345678//12345678\n{/if}', NULL, '2016-6-8 13:37:42', '2016-6-8 13:38:20', 0, 0);
INSERT INTO `demo` VALUES (676, 00000000666, 1, 0, 'js', 'smarty内置变量', '关键词', '可以在模版中使用{var_dump(XXX)}打印出变量,来查看数据结构', 'Smarty保留变量\nSmarty系统中保留了一些内置变量，可以快速访问相应的变量。但是不能再源php中获得这些变量。\n//1、请求访问变量（Request variables）\n$smarty.get.变量       //显示通过get方式传过来的指定变量的值。\n$smarty.post.变量      //显示通过post方式传过来的指定变量的值。\n$smarty.cookies.变量 //显示通过cookie中指定变量的值。\n$smarty.server.SERVER_NAME   //显示server变量值，phpinfo()中$_SERVER系列变量\n$smarty.env.PATH   //显示系统环境变量值，phpinfo()中$_ENV系列变量\n$smarty.session.变量 //显示session中指定变量的值\n$smarty.request.变量 //显示通过post、get、cookie中指定变量的值。\n//2、时间访问变量\n{$smarty.now} //显示unix系统时间戳，需要变量调节器格式化，参看4.2.4，也可以使使用{time()}\n//3、常量访问变量\n{$smarty.const._MY_CONST_VAL}   //访问php中的常量包括自定义常量和系统常量\n4、{$smarty.capture}\n//参看4.4.1\n//5、配置访问变量\n{$smarty.config.配置变量}   //访问配置变量，等同于 //配置变量// 方式\n6、{$smarty.section}, {$smarty.foreach}\n//参看4.4.3和4.4.4\n7、{$smarty.template}   //显示模板路径和名称', NULL, '2016-6-8 13:49:39', '2016-6-8 13:50:26', 0, 0);
INSERT INTO `demo` VALUES (677, 00000000666, 1, 0, 'js', '变量的格式化', '关键词', ' 变量调节器主要是对变量进行格式化。', '{$var| truncate:30:\"…\":true}    //截取变量的到规定的长度，具体参数看chm文档\n{$var| default:\"no title\" } //当变量为空时，为变量提供一个默认值\n{$var| replace:\"Garden\":\"Vineyard\"} //将变量中要求的内容替换成指定内容\n{$var| regex_replace:\"/[\\r\\t\\n]/\":\" \"} //将变量中的符合正则的内容替换成指定内容\n{$var|capitalize}   //将变量首字大写\n{$var|count_characters:false}   //计算变量里的字符数，false为不计算空格。若变量为数值则为数字和小数点等其他运算符的总和\n{$var| cat:var2} //将var2连接到var，若为数值以字符串处理。\n{$var| count_paragraphs} //计算变量里的段落数量，已“\\n“区分\n{$var| count_sentences} //计算变量中句子的数量，不好使\n{$var| count_words} //计算变量中单词的数量 已非字母和数字的字符分割统计\n{$var| date_format :\"%H:%M:%S\" } //格式化变量日起，具体参数看chm文档\n{$var| escape:url}     //对变量值进行转码，具体参数看chm文档\n{$var| indent:10:\"*\"}    //对变量指定具体字符进行缩进,若为空格在html中不会显示出来，具体参数看chm文档\n{$var| lower}   //将变量小写\n{$var| nl2br }   //将变量中的“\\n“转换成”<br />“\n{$var| spacify:\"^^\"} //将变量字符与字符之间插入指定内容，包括空格\n{$var|string_format:\"%d\"}   //将变量中的内容格式化，格式化参数同printf\n{$var| strip: \"*\"}  //用一个空格或一个给定字符替换所有重复空格,换行和制表符\n{$var| strip_tags} //删除变量中的html标记, 去除<和>标签,包括在<和>之间的任何内容\n{$var| upper}    //将变量大写\n{$var| wordwrap:30:\"\\n\":true}    //规定指定的长度强制换行，具体参数看chm文档\n// 修改器可以复合组合。\n{$articleTitle|lower|spacify|truncate:30:\". . .\"}\n// 设置默认变量调节器\n$smarty->getDefault_modifiers()    //默认为空数组\n$smarty->setDefault_modifiers(array(‘spacify:\"^^\"’,\'capitalize’)   //设置变量的默认调节器，必须用array\n{name}    //模板变量name自动加入上面两个调节器', NULL, '2016-6-8 14:07:20', '2016-6-8 14:08:10', 0, 0);
INSERT INTO `demo` VALUES (678, 00000000666, 1, 0, 'js', '模块的条件性复用capture', '关键词', 'capture函数的作用是捕获模板输出的数据并将其存储到一个变量里,而不是把它们输出到页面.\n例如:任何在 {capture name=\"foo\"}和{/capture}之间的数据将被存储到变量$foo中。\n这样可以根据实际情况，选择性的输出一些内容,输出的语法是$smarty.capture.变量。', '{capture name=\"bottom\"}\n{include file=\"bottom.tpl\" nr=\"这是底部的内容\"}\n{/Capture}\n//一下输出3个底部:\n{if true }  //进行条件判断，确定是否输出\n{$smarty.capture.bottom}\n{/if}\n{if true }  //进行条件判断，确定是否输出\n{$smarty.capture.bottom}\n{/if}\n{if true }  //进行条件判断，确定是否输出\n{$smarty.capture.bottom}\n{/if}', NULL, '2016-6-8 14:11:21', '2016-6-8 14:12:56', 0, 0);
INSERT INTO `demo` VALUES (679, 00000000666, 1, 0, 'js', 'foreach,foreachelse', '关键词', '', 'foreach 适合于简单数组（元素类型相同）\n{foreach name=名称 item=内容 key=键 from=数组}  //2.0中的用法，3.0沿用\n正常执行\n{foreachelse}\nFrom变量数组没有值时（0个元素）执行。\n{/foreach}\n例子：\n{foreach name=for1 item=num from=$foo}\n{$smarty.foreach.for1.index+1}个元素：{$num}<br />\n{if is_array($num)}\n{foreach name=for2 item=num2 key=key2 from=$num}\n{$str|cat:$smarty.foreach.for2.index+1|cat:\"个元素：\"|cat:$num2|cat:\" key是\"|cat:$key2|indent:1:\".\"}<br />\n{/foreach}\n{/if}\n{foreachelse}\n{$smarty.foreach.for1.index+1}个元素：没有值！<br />\n{/foreach}\nforeach的内置变量\n$smarty.foreach.foreachname.index   //（循环内部使用）显示当前循环的索引,如果数组为空，返回-1\n$smarty.foreach.foreachname. iteration    //（循环内部使用）显示当前的循环次数\n$smarty.foreach.foreachname.first //（循环内部使用）如果为第一次循环，返回true\n$smarty.foreach.foreachname.last //（循环内部使用）如果为最后一次循环，返回true\n$smarty.foreach.foreachname.total //（循环内外部使用）显示循环的总次数\nforeach 在3.0中做一定的升级，语法更接近于php，内置变量也更简洁。\n{foreach $myarray as $var}…{/foreach}\nforeach的内置变量，均可在内外部使用\n$var@key           //输出元素的键值，简单为012，关联为具体键值。\n$var@iteration      //显示当前的循环次数，外部使用为最后一次\n$var@index         //显示当前循环的索引,如果数组为空，返回-1，外部使用为最后一次\n$var@total          //显示循环的总次数\n$var@first           //如果为第一次循环，返回true\n$var@last           //如果为最后一次循环，返回t', NULL, '2016-6-8 14:17:27', '2016-6-8 14:17:46', 0, 0);
INSERT INTO `demo` VALUES (680, 00000000666, 1, 0, 'js', 'section,sectionelse ', '关键词', 'section适用于复杂的数组操作，不适合关联数组。但是在3.0中并为对他做什么升级和修改，\n而是直接推出了for命令，for更接近于php语法。可以预见，section将在未来版本中淘汰。', '{section name=名称 loop=循环数组(次数) start=开始(0) step=步阶(1) max=最大循环次数 show=是否显示(true)}\n//2.0中的用法，3.0沿用\n正常执行\n{sectionelse}\n    loop数组没有值时（0个元素）执行。\n{/section }\n例子：\n{section name=sec1 loop=$foo step=1 start=0 show=true}\n    第{$smarty.section.sec1.index+1}个元素：{$foo[sec1]}  循环次数是\n    {$smarty.section.sec1.iteration}<br />\n    {if is_array($foo[sec1])}\n        {section name=sec2 loop=$foo[sec1] step=1 start=0 show=true}\n        第{$smarty.section.sec2.index+1}个元素：{$foo[sec1][sec2]}\n        循环次数是{$smarty.section.sec2.iteration}<br />\n        {/section}\n    {/if}\n{sectionelse}\n        {$smarty.section.sec1.index}个元素：没有值！<br />\n{/section}\n// Section的内置变量与foreach 相同。', NULL, '2016-6-8 14:18:05', '2016-6-8 14:20:12', 0, 0);
INSERT INTO `demo` VALUES (681, 00000000654, 1, 0, 'js', '价格/评论处理', '关键词', '', '//价格相关需要引入price.min.js\n循环体最外层元素追加属性: data-price-area=\"need\"\n在价格的元素标签上加属性: data-price-id=\"{{{$commodity_pool}}[sn].skuId}\"//价格\n--------------------------\n//评论相关需要自写js\n1.在评论的元素标签上加属性: data-comment-id=\"{{{$commodity_pool}}[sn].skuId}\"\n2.自写js用jsonp获取:\nvar b = $(\".floor-tz-buy160408 .product-item .num\");\nvar c = \"\";\nfor (var d = 0; d < b.length; d++) {\n    var e = b[d].getAttribute(\"data-comment-id\");\n    c = c + e + \",\"\n}\n$.ajax({\n    url : \"//club.jd.com/clubservice/summary-m-\" + c + \".html\",\n    type : \"post\",\n    dataType : \"jsonp\",\n    timeout : 3e3,\n    success : function (a) {\n        for (var c = 0; c < b.length; c++)\n            b[c].innerHTML = a.CommentsCount[c].CommentCount\n    },\n    error : function () {\n        b.parent().hide()\n    }\n});\n//这段js严重依赖数据次序,有数据错位的风险!\n-------------------修改上面函数为:\nvar $commentElements = $(\".man-floor160527-01 .p-eva em\");\nfunction getComment(dom){\n    dom.filter(\"[data-comment-id=\'\']\").parent().hide();\n    dom2 = dom.filter(\"[data-comment-id][data-comment-id!=\'\']\");\n    var str = $.map(dom2,function(f){\n    return $(f).attr(\"data-comment-id\");\n    }).join(\",\");\n    $.ajax({\n        url : \"//club.jd.com/clubservice/summary-m-\" + str + \".html\",\n        dataType : \"jsonp\",\n        timeout : 3e3,\n        success : function (data) {\n            for(i in data.CommentsCount){\n                dom2.filter(\"[data-comment-id=\'\"+data.CommentsCount[i].SkuId+\"\']\").text(data.CommentsCount[i].CommentCount);\n            }\n        },\n        error : function () {\n            dom2.parent().hide();\n        }\n    });\n}\ngetComment($commentElements);\n会发出类似格式的请求:\nhttp://club.jd.com/clubservice/summary-m-10337875900,10261812257,10270627617,10260504671,10256612309,10280672929,.html?callback=jQuery2232294&_=1465794887356\n返回如下格式的数据:\njQuery2232294({\n  \'CommentsCount\': [\n    {\n      \'SkuId\': 10337875900,\n      \'ProductId\': 10337875900,\n      \'Score1Count\': 0,\n      \'Score2Count\'\n      : 0,\n      \'Score3Count\': 1,\n      \'Score4Count\': 4,\n      \'Score5Count\': 24,\n      \'ShowCount\': 1,\n      \'CommentCount\': 29,\n      \'AverageScore\': 5,\n      \'GoodCount\': 28,\n      \'GoodRate\': 0.966,\n      \'GoodRateShow\': 97,\n      \'GoodRateStyle\': 145,\n      \'GeneralCount\': 1,\n      \'GeneralRate\'\n      : 0.034,\n      \'GeneralRateShow\': 3,\n      \'GeneralRateStyle\': 5,\n      \'PoorCount\': 0,\n      \'PoorRate\': 0,\n      \'PoorRateShow\': 0,\n      \'PoorRateStyle\'\n      : 0\n    },\n    {\n      \'SkuId\': 10261812257,\n      \'ProductId\': 10261812257,\n      \'Score1Count\': 2,\n      \'Score2Count\': 0,\n      \'Score3Count\': 1,\n      \'Score4Count\'\n      : 13,\n      \'Score5Count\': 186,\n      \'ShowCount\': 33,\n      \'CommentCount\': 202,\n      \'AverageScore\': 5,\n      \'GoodCount\': 199,\n      \'GoodRate\': 0\n      0.987,\n      \'GoodRateShow\': 99,\n      \'GoodRateStyle\': 148,\n      \'GeneralCount\': 1,\n      \'GeneralRate\': 0.004,\n      \'GeneralRateShow\': 0,\n      \'GeneralRateStyle\': 1,\n      \'PoorCount\': 2,\n      \'PoorRate\': 0.009,\n      \'PoorRateShow\': 1,\n      \'PoorRateStyle\': 1\n    },\n    {\n      \'SkuId\': 10270627617,\n      \'ProductId\': 10270627617,\n      \'Score1Count\': 0,\n      \'Score2Count\': 0,\n      \'Score3Count\': 1,\n      \'Score4Count\': 0,\n      \'Score5Count\'\n      : 57,\n      \'ShowCount\': 7,\n      \'CommentCount\': 58,\n      \'AverageScore\': 5,\n      \'GoodCount\': 57,\n      \'GoodRate\': 0.983,\n      \'GoodRateShow\': 98,\n      \'GoodRateStyle\': 147,\n      \'GeneralCount\': 1,\n      \'GeneralRate\': 0.017,\n      \'GeneralRateShow\': 2,\n      \'GeneralRateStyle\': 3,\n      \'PoorCount\'\n      : 0,\n      \'PoorRate\': 0,\n      \'PoorRateShow\': 0,\n      \'PoorRateStyle\': 0\n    },\n    {\n      \'SkuId\': 10260504671,\n      \'ProductId\': 10260504671,\n      \'Score1Count\'\n      : 0,\n      \'Score2Count\': 0,\n      \'Score3Count\': 0,\n      \'Score4Count\': 0,\n      \'Score5Count\': 7,\n      \'ShowCount\': 1,\n      \'CommentCount\': 7,\n      \'AverageScore\'\n      : 5,\n      \'GoodCount\': 7,\n      \'GoodRate\': 1,\n      \'GoodRateShow\': 100,\n      \'GoodRateStyle\': 150,\n      \'GeneralCount\': 0,\n      \'GeneralRate\'\n      : 0,\n      \'GeneralRateShow\': 0,\n      \'GeneralRateStyle\': 0,\n      \'PoorCount\': 0,\n      \'PoorRate\': 0,\n      \'PoorRateShow\': 0,\n      \'PoorRateStyle\'\n      : 0\n    },\n    {\n      \'SkuId\': 10256612309,\n      \'ProductId\': 10256612309,\n      \'Score1Count\': 0,\n      \'Score2Count\': 1,\n      \'Score3Count\': 2,\n      \'Score4Count\'\n      : 5,\n      \'Score5Count\': 200,\n      \'ShowCount\': 4,\n      \'CommentCount\': 208,\n      \'AverageScore\': 5,\n      \'GoodCount\': 205,\n      \'GoodRate\': 0.986,\n      \'GoodRateShow\': 99,\n      \'GoodRateStyle\': 148,\n      \'GeneralCount\': 3,\n      \'GeneralRate\': 0.014,\n      \'GeneralRateShow\': 1,\n      \'GeneralRateStyle\'\n      : 2,\n      \'PoorCount\': 0,\n      \'PoorRate\': 0,\n      \'PoorRateShow\': 0,\n      \'PoorRateStyle\': 0\n    },\n    {\n      \'SkuId\': 10280672929,\n      \'ProductId\'\n      : 10280672929,\n      \'Score1Count\': 1,\n      \'Score2Count\': 0,\n      \'Score3Count\': 1,\n      \'Score4Count\': 1,\n      \'Score5Count\': 3,\n      \'ShowCount\'\n      : 0,\n      \'CommentCount\': 6,\n      \'AverageScore\': 4,\n      \'GoodCount\': 4,\n      \'GoodRate\': 0.668,\n      \'GoodRateShow\': 66,\n      \'GoodRateStyle\'\n      : 100,\n      \'GeneralCount\': 1,\n      \'GeneralRate\': 0.166,\n      \'GeneralRateShow\': 17,\n      \'GeneralRateStyle\': 25,\n      \'PoorCount\': 1,\n      \'PoorRate\'\n      : 0.166,\n      \'PoorRateShow\': 17,\n      \'PoorRateStyle\': 25\n    }\n  ]\n});', NULL, '2016-6-8 14:47:54', '2016-6-13 15:02:03', 0, 0);
