INSERT INTO `demo` VALUES (312, 00000000310, 1, 0, 'css', '基于css的箭头', '关键词', '为了兼容盒子模型,不要显式的设置宽度与高度!', '.page{position:relative}\n.page:after{/*修改颜色和border的宽度可以实现不同的颜色不同的箭头方向*/\n    content: \"\";.\n    border-style: solid;\n    border-width: 8px 8px 8px 0;\n    border-color: transparent #ccc transparent transparent;\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    margin-top: -8px;\n    margin-left: -4px;\n}\n.page:after{/*修改颜色和border的宽度可以实现不同的颜色不同的箭头方向*/\n    content: \"\";.\n    border-style: solid;\n    border-width: 8px 8px 8px 0;\n    border-color: transparent #ccc transparent transparent;\n    position: absolute;\n}', NULL, '2016-2-25 18:10:29', '2016-6-6 10:25:42', 0, 0);
INSERT INTO `demo` VALUES (313, 00000000272, 1, 0, 'js', 'select重构为可搜索', '关键词', '其中使用了闭包的概念，所有逻辑在变量间交织，而不是基于样式的各种dom选择器', '<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"http://www.laibatour.com/statics/js/jquery.js\"></script>\n    <script>\n        \n    $(function(){\n        //拓展一个选择器，以实现不区分大小写\n        jQuery.expr[\':\'].mycontains = function(a, i, m){\n         return jQuery(a).text().toUpperCase()\n           .indexOf(m[3].toUpperCase()) >= 0;\n        };\n        //如果想区分大小写，使用这个\n        // jQuery.expr[\':\'].mycontains = function(a, i, m){\n        //  return jQuery(a).text().indexOf(m[3]) >= 0;\n        // };\n        //给$.fn拓展一个select重构函数\n        $.fn.myInputSelect=function(){\n            //样式\n            var style = \"<style>\";\n            style +=\'    .input-select-wrap{\';\n            style +=\'        position:relative;\';\n            style +=\'        z-index: 1;\';\n            style +=\'    }\';\n            style +=\'    .input-select-ul{\';\n            style +=\'        display: none;\';\n            style +=\'        max-height: 350px;\';\n            style +=\'        overflow: auto;\';\n            style +=\'        position: fixed;\';\n            style +=\'        width: 200px;\';\n            style +=\'        border: 1px solid rgb(204, 204, 204);\';\n            style +=\'        list-style: outside none none;\';\n            style +=\'        padding: 10px 0;\';\n            style +=\'        margin: 0px;\';\n            style +=\'        background: rgb(255, 255, 255) none repeat scroll 0% 0%;\';\n            style +=\'        left: 0;\';\n            style +=\'    }\';\n            style +=\'    .input-select-ul li{\';\n            style +=\'        cursor:default;\';\n            style +=\'        padding:0 10px;\';\n            style +=\'    }\';\n            style +=\'    .input-select-ul li.focus,.input-select-ul li:hover{\';\n            style +=\'        background-color:#efefef\';\n            style +=\'    }\';\n            style +=\'    </style>\';\n            $(\"head\").append(style);\n            //ul容器\n            if($(\"#ul_wrap\").size()==0){\n                var $ulWrap = $(\"<div id=\\\"ul_wrap\\\"></div>\").appendTo($(\"body\"));\n            }\n            // select重构\n            $(this).each(function(){\n                if(!$(this).is(\"select\"))return;\n                var $select = $(this);\n                // ul\n                var $ul = $(\"<ul class=\\\"input-select-ul\\\"></ul>\");\n                var $hiddenInput = $(\"<input type=\\\"hidden\\\"/>\").attr(\"name\",$select.attr(\"name\"));\n                // input\n                var $input = $(\"<input type=\\\"text\\\"/>\").attr(\"class\",$select.attr(\"class\")).attr(\"style\",$select.attr(\"style\")).bind(\"click focus\",function(){\n                    $ul.css({\"top\":$(this).offset().top+$(this).outerHeight(),\"left\":$(this).offset().left}).show();\n                }).bind(\"keyup\",function(evt){\n                    $ul.show().find(\"li\").hide().end().find(\"li:mycontains(\'\"+$(this).val()+\"\')\").show();\n                    var $focus  = $ul.find(\"li.focus:visible\");\n                    if($focus.size()==0){\n                        $focus = $ul.find(\"li:visible:first\").addClass(\"focus\");\n                    }\n                    if(evt.keyCode==13){\n                        $focus.trigger(\"click\");\n                    }\n                    if(evt.keyCode==38){\n                        var $prev = $focus.prevAll(\"li:visible\").eq(0);\n                        if($prev.size()>0){\n                            $focus.removeClass(\"focus\");\n                            $prev.addClass(\"focus\");\n                        }\n                    }\n                    if(evt.keyCode==40){\n                        var $next = $focus.nextAll(\"li:visible\").eq(0);\n                        if($next.size()>0){\n                            $focus.removeClass(\"focus\");\n                            $next.addClass(\"focus\");\n                        }\n                    }\n                });\n                $select.find(\"option\").each(function(){\n                    //默认选中值问题\n                    var val =$(this).attr(\"value\")&&$(this).attr(\"value\")!=\"\"?$(this).attr(\"value\"):$(this).text();\n                    if($(this).attr(\"selected\")){\n                        $hiddenInput.val(val);//hidden input\n                        $input.val($(this).text());//input\n                    }\n                    $(\"<li></li>\").text($(this).text()).bind(\"click\",function(){\n                            $hiddenInput.val(val);//hidden input\n                            $input.val($(this).text());//input\n                            $ul.hide();\n                        }).appendTo($ul);\n                });\n                $select.after($input).after($hiddenInput).remove();\n                $ulWrap.append($ul);\n                $(document).click(function(evt){\n                    if((!$(evt.target).is($input))&&$(evt.target).closest(\"#ul_wrap\").size()==0){\n                        $ul.hide();\n                    }\n                });\n            });\n            return $(this);\n        }\n        //main函数\n        $(\".input-select\").myInputSelect();\n    });\n    </script>\n</head>\n<body>\n使用方法：<br/>\n1.引入js文件<br/>\n2.在原来的select元素上添加样式\"input-select\";<br/>\n说明：<br/>\n1.select正常写，可以自由添加class属性，style属性以及name属性，<br/>\n2.option正常写，可以正常设置value属性，依然有效，seledted属性也有效<br/>\n3.后台依然按照select上设置的name值去接收值<br/>\n4.搜索效果默认不区分大小写，如果想区分，修改js源码中注掉的方法！<br/>\n    <select class=\"input-select\" name=\"myname\">\n        <option value=\"1\">Afghanistan</option>\n        <option value=\"Aland Island\" selected>Aland Island</option>\n        <option value=\"Albania\">Albania</option>\n        <option value=\"Algeria\">Algeria</option>\n        <option value=\"American Samoa\">American Samoa</option>\n        <option value=\"Andorra\">Andorra</option>\n        <option value=\"Angola\">Angola</option>\n        <option value=\"Anguilla\">Anguilla</option>\n        <option value=\"Antarctica\">Antarctica</option>\n        <option value=\"Antigua and Barbuda\">Antigua and Barbuda</option>\n        <option value=\"Argentina\">Argentina</option>\n        <option value=\"Armenia\">Armenia</option>\n        <option value=\"Aruba\">Aruba</option>\n        <option value=\"Ascension Island\">Ascension Island</option>\n        <option value=\"Australia\">Australia</option>\n        <option value=\"Austria\">Austria</option>\n        <option value=\"Azerbaijan\">Azerbaijan</option>\n        <option value=\"Bahrain\">Bahrain</option>\n        <option value=\"Bangladesh\">Bangladesh</option>\n        <option value=\"Barbados\">Barbados</option>\n        <option value=\"Belarus\">Belarus</option>\n        <option value=\"Belgium\">Belgium</option>\n        <option value=\"Belize\">Belize</option>\n        <option value=\"Benin\">Benin</option>\n        <option value=\"Bermuda\">Bermuda</option>\n        <option value=\"Bhutan\">Bhutan</option>\n        <option value=\"Bolivia\">Bolivia</option>\n        <option value=\"Bosnia &amp; Herzegovina\">Bosnia &amp; Herzegovina</option>\n        <option value=\"Botswana\">Botswana</option>\n        <option value=\"Brazil\">Brazil</option>\n        <option value=\"British Indian Ocean Territory\">British Indian Ocean Territory</option>\n        <option value=\"British Virgin Islands\">British Virgin Islands</option>\n        <option value=\"Brunei\">Brunei</option>\n        <option value=\"Brunei Darussalam\">Brunei Darussalam</option>\n        <option value=\"Bulgaria\">Bulgaria</option>\n        <option value=\"Burkina Faso\">Burkina Faso</option>\n        <option value=\"Burma\">Burma</option>\n        <option value=\"Burundi\">Burundi</option>\n        <option value=\"C?te d’Ivoire\">C?te d’Ivoire</option>\n      