INSERT INTO `demo` VALUES (321, 00000000272, 1, 0, 'html', 'mydatepicker1.1（secondes）', '关键词', '主要是增加了精确到分钟的拾取和对已填写日期后激活后的面板将跳转到所填日期', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"jquery.js\"></script>\n    <script>\nvar mydatepicker = {\n    currentInput:null,\n    setting:{},\n    mydefault: {\n        placeholder: \"mydp\",\n        currentMonth: new Date(),\n        monthWidth: 362,\n        originMonth: new Date(),\n        selectable: null,\n        selected: [],\n        monthStr: [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\", \"August\", \"September\", \"October\", \"November\", \"December\"],\n        shortMonthStr: [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"],\n        leftLimit: null,\n        rightLimit: null,\n        range: null,\n        currentDom: null,\n        rootDom: null,\n        dateClick:$.noop,\n        startTime:null,\n        endTime:null,\n        positionLeft:0,\n        positionTop:0,\n        minute:false,\n        currentMinuteDom:null\n    },\n    getRoot:function(){\n        return $(\"#\"+mydatepicker.setting.placeholder);\n    },\n    init:function(obj) {\n        mydatepicker.setting = $.extend({}, mydatepicker.mydefault, obj);\n        //生成dom,先判断是否有dom，没有就生成！有那么就初始化一下！\n        if(mydatepicker.getRoot().size()==0){\n            //生成style\n            var style = \"<style>\";\n            style +=\" .my-dp{\";\n            style +=\"   overflow:hidden;\";\n            style +=\"   height:327px;\";\n            style +=\"   width:363px;\";\n            style +=\"   left: 0;\";\n            style +=\"   position: absolute;\";\n            style +=\"   top: 70px;\";\n            style +=\"   z-index: 100;\";\n            style +=\"   display:none;\";\n            style +=\"   box-shadow: 2px 5px 9px 0 #999;\";\n            style +=\"   background-color: #fff;\";\n            style +=\" }\";\n            style +=\" .my-dp .dp-line{\";\n            style +=\"   position: relative;\";\n            style +=\"   height: 0;\";\n            style +=\"   width: 0;\";\n            style +=\" }\";\n            style +=\" .my-dp .dp-month{\";\n            style +=\"   background-color: #fff;\";\n            style +=\"   width: 362px;\";\n            style +=\"   overflow:hidden;\";\n            style +=\"   padding: 7px 0 8px;\";\n            style +=\"   position: absolute;\";\n            style +=\"   top: 0;\";\n            style +=\" }\";\n            style +=\" .my-dp .dp-month dt,.dp-month dd{\";\n            style +=\"   width:362px;\";\n            style +=\"   margin-left: 13px;\";\n            style +=\" }\";\n            style +=\" .my-dp .dpm-ctrl{\";\n            style +=\"   text-align: center;\";\n            style +=\"   position: relative;\";\n            style +=\"   height: 40px;\";\n            style +=\" }\";\n            style +=\" .my-dp .dpm-title{\";\n            style +=\"   color:#00A0E9;\";\n            style +=\"   line-height: 44px;\";\n            style +=\"   font-size: 18px;\";\n            style +=\"   font-weight: normal;\";\n            style +=\" }\";\n            style +=\" .my-dp .dpm-prev:focus{\";\n            style +=\"   text-decoration:none;\";\n            style +=\" }\";\n            style +=\" .my-dp .dpm-next:focus{\";\n            style +=\"   text-decoration:none;\";\n            style +=\" }\";\n            style +=\" .my-dp .dpm-prev{\";\n            style +=\"   position: absolute;\";\n            style +=\"   top:0;\";\n            style +=\"   left: 0px;\";\n            style +=\"   font-size: 30px;\";\n            style +=\"   text-align: center;\";\n            style +=\"   width: 70px;\";\n            style +=\"   transform: scaleX(0.6);\";\n            style +=\"   color: #0bbcf2;\";\n            style +=\"   text-decoration: none;\";\n            style +=\" }\";\n         