INSERT INTO `demo` VALUES (370, 00000000291, 1, 0, 'js', '执行流程', '关键词', '描述', '新代码', NULL, '2016-3-16 18:01:51', '2016-3-16 18:01:51', 0, 0);
INSERT INTO `demo` VALUES (371, 00000000370, 1, 0, 'js', '初始化流程相关', '关键词', ' ', '1) 浏览器加载静态HTML文件并解析为DOM；\n　　2) 浏览器加载angular.js文件；\n　　3) angular监听DOMContentLoaded 事件，监听到时开始启动；\n　　4) angular寻找ng-app指令，确定作用范围；\n　　5) 找到app中定义的Module使用$injector服务进行依赖注入；\n　　6) 根据$injector服务创建$compile服务用于编译；\n　　7) $compile服务编译DOM中的指令、过滤器等；\n　　8) 使用ng-init指令，将作用域中的变量进行替换；\n　　9) 最后生成了我们在最终视图。\n　　可以看到，ng框架是在DOMcontent加载完毕后才开始发挥作用\n', NULL, '2016-3-16 18:02:04', '2016-5-4 00:25:41', 0, 0);
INSERT INTO `demo` VALUES (372, 00000000292, 1, 0, 'js', 'provider提供者', '关键词', 'directive一般用来写一些通用的组件。\n\ncontroller处理特定页面的逻辑。\n\nfactory/service 是单例模式，service是对factory的封装，相应的还有constant和value方法。一般公用的静态方法（如与后端交互的ajax请求），或者需要在不同的controller、directive、service之间共享的数据都可以定义在service', '  新数据  //=====================demo\n\nvar app = angular.module(\"myApp\", []);// 方法 1\n$provide.provider(\'test\', { \n   n:1; \n   $get: function () { \n      return n; \n    }; \n});\n \n// 方法 2\n$provide.provider(\'test\', function () { \n   this.n = 2; \n   this.$get = function () { \n   return n; \n}; \n});\n//=====================demo\n\n//两种方式，直接提供一个对象，或者是一个构造函数！不管是对象还是构造函数，都必须有一个$get方法，全范围内可随意注入\n// 使用\napp.controller(\'MainCtrl\', function ($scope, test) {//注入刚写的provider！\n    $scope.test = test;\n});\napp.controller(\'MainCtrl\', function ($scope, $http) {//$scope, $http都可以认为是provider！\n  $http.get(....).then(.....); \n}\n//provider的底层源码\nfunction provider(name, provider_) {\n  if (isFunction(provider_)) {\n      provider_ = providerInjector.instantiate(provider_);\n  }\n   if (!provider_.$get) {\n       throw Error(\'Provider \' + name + \' must define $get factory method.\');\n   }\n   return providerCache[name + providerSuffix] = provider_;\n}\n//factory是provider的一个变种，函数的第二个参数就是$get的内容，所有的属性在这个函数里面设置，并返回出来\n// 定义 factory\n$provide.factory(\'dd\', function () {\n   return new Date();\n});\n// 一样使用，注入就好了\napp.controller(\'MainCtrl\', function ($scope, dd) {\n    $scope.mydate = dd;\n});  ', NULL, '2016-3-16 18:04:09', '2016-4-4 20:58:59', 0, 0);
INSERT INTO `demo` VALUES (373, 00000000292, 1, 0, 'js', 'factory工厂', '关键词', '如果说的是 Provider、Factory、Service、Value、Constant 的总称的话，一般来说并没有 Factory 的叫法，要么叫 Service（官方早期是这么叫的，但是会有 a Service is a Service 这种跨层次重名情况），或者叫 Provider（除 Constant 外本质上都是 Provider，Value 和 Service 是调用的 Factory，Factory 是调用的 Provider），或者高雅一点叫 Dependency。这里暂时叫一下 Provider，如果不习惯的话，脑补成别的名词就好。。\n\n其实如果按本文这种顺序的话，用下排除法就知道什么时候该用 Provider 了，所有没有在上面两者的职责内的情况，包括但不仅限于网络、存储等其他一切与展示逻辑无关的内容。\n\n至于这几个东东内部的区别，The Provider（不是泛指）的话具有可配置性，可以在程序运行前进行相应的设定；Factory 和 Service 除了写法上没有什么区别，喜欢用什么用什么，不一定要按它的名字来；Value 和 Constant 为单个对象依赖，Constant 可以在 Provider 的配置阶段使用，其他都不能。Angular 2 把上面这些东西的名词叫法合并了，虽然实际上并没有什么功能上的改变。（不过，依赖注入的机制倒是改了不少。）\n\n综上所述，所有与展示逻辑（或者说交互逻辑）无关的部分都应该写成 Provider（广义的）。\n\n作者：Trotyl Yu\n链接：https://www.zhihu.com/question/27836513/answer/76686560\n来源：知乎\n著作权归作者所有。商业转载请联系作者获得授权，非商业转载请注明出处。', '//============================底层源码\n\nfunction factory(name, factoryFn) {\n return provider(name, { \n   $get: factoryFn \n }); \n}\n\n//============================底层源码\n//可见底层是provider的一个对象书写方式！', NULL, '2016-3-16 18:47:11', '2016-4-4 21:00:42', 0, 0);
INSERT INTO `demo` VALUES (389, 00000000291, 1, 0, 'js', '常见报错', '关键词', '描述', '新代码', NULL, '2016-3-19 14:12:08', '2016-3-19 14:12:08', 0, 0);
INSERT INTO `demo` VALUES (390, 00000000389, 1, 0, 'html', '内部关键字乱用', '关键词', '案列错误原因，正常的html代码中出现了一个ng-transclude，而这个通常是出现再指令内部用来指示位置的指令！angular尝试去解析这个指令，所以报错', '<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myApp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n    <script src=\"jquery.js\"></script>\n</head>\n<body>\n<div>\n    <hello>\n        <hi></hi>\n    </hello>\n</div>\n<script type=\"text/javascript\">\nvar m1 = angular.module(\'myApp\',[]);\nm1.directive(\'hello\',function(){\n    return {\n        restrict : \'E\',\n        replace : true,\n        transclude : true,   //允许自定义指令的嵌套，通过ng-transclude指定嵌套的范围\n        controller : function($scope){\n            $scope.name = \'xiecg\';\n            this.name = \'xiecg\';    //使用this共享给其他指令\n        },\n        template : \'<div>hello angular <h1 ng-transclude></h1></div>\',\n        link : function(scope,element,attr,reController){\n            console.log(\"父亲执行：\"+reController);    //得到父级hello指令中共享出来的数据\n        }\n    };\n});\nm1.directive(\'hi\',function(){\n    return {\n        restrict : \'E\',\n        replace : true,\n        require : \'^hello\',//hello指令属性hi指令的父级，需要用^符号指定。如果无法指定，使用?容错处理。\n        template : \'<span>hi angular {{name}}</span>\',\n        link : function(scope,element,attr,reController){\n            console.log(\"儿子获得\"+reController);    //得到父级hello指令中共享出来的数据\n        }\n    };\n});\n</script>\n\n<div>\n    <div>hello angular \n        <h1 ng-transclude>\n            <span>hi angular xiecg</span>\n        </h1>\n    </div>\n</div>\n</body>\n</html>', NULL, '2016-3-19 14:12:54', '2016-3-19 14:15:22', 0, 0);
INSERT INTO `demo` VALUES (391, 00000000291, 1, 0, 'js', 'jqLite', '关键词', '描述', '新代码', NULL, '2016-3-19 15:02:53', '2016-3-19 15:02:53', 0, 0);
INSERT INTO `demo` VALUES (392, 00000000391, 1, 0, 'js', '基本语法', '关键词', 'angular.element(dom)', 'addClass();\nafter();\nappend();\nattr();// - Does not support functions as parameters\nbind();// - Does not support namespaces, selectors or eventData\nchildren();// - Does not support selectors\nclone();\ncontents();\ncss();// - Only retrieves inline-styles, does not call getComputedStyle();\ndata();\ndetach();\nempty();\neq();\nfind();// - Limited to lookups by tag name\nhasClass();\nhtml();\nnext();// - Does not support selectors\non();// - Does not support namespaces, selectors or eventData\noff();// - Does not support namespaces or selectors\none();// - Does not support namespaces or selectors\nparent();// - Does not support selectors\nprepend();\nprop();\nready();\nremove();\nremoveAttr();\nremoveClass();\nremoveData();\nreplaceWith();\ntext();\ntoggleClass();\ntriggerHandler();// - Passes a dummy event object to handlers.\nunbind();// - Does not support namespaces\nval();\nwrap();\n', NULL, '2016-3-19 15:03:04', '2016-4-28 13:44:05', 0, 0);
INSERT INTO `demo` VALUES (374, 00000000293, 1, 0, 'js', '动态添加元素并移除它', '关键词', 'keyword:$compile', '$scope.userName=\'Welcome to Angular World!\';\n$scope.test = function test(){\nconsole.log(\'Angular 动态添加元素\');\n}\n \n//通过$compile动态编译html\nvar html=\"<div ng-click=\'test()\'>}</div>\";\nvar template = angular.element(html);\nvar mobileDialogElement = $compile(template)($scope);\nangular.element(document.body).append(mobileDialogElement);\n \n// remove移除创建的元素\nvar closeMobileDialog = function () {\nif (mobileDialogElement) {\n  mobileDialogElement.remove();\n}', NULL, '2016-3-16 19:03:37', '2016-3-16 19:04:06', 0, 0);
INSERT INTO `demo` VALUES (375, 00000000292, 1, 0, 'js', '$watch/$digest/$apply', '关键词', '$apply()和$digest()在AngularJS中是两个核心概念，但是有时候它们又让人困惑。而为了了解AngularJS的工作方式，首先需要了解$apply()和$digest()是如何工作的。这篇文章旨在解释$apply()和$digest()是什么，以及在日常的编码中如何应用它们。\n探索$apply()和$digest()\nAngularJS提供了一个非常酷的特性叫做双向数据绑定(Two-way Data Binding)，这个特性大大简化了我们的代码编写方式。数据绑定意味着当View中有任何数据发生了变化，那么这个变化也会自动地反馈到scope的数据上，也即意味着scope模型会自动地更新。类似地，当scope模型发生变化时，view中的数据也会更新到最新的值。那么AngularJS是如何做到这一点的呢？当你写下表达式如{{ aModel }}时，AngularJS在幕后会为你在scope模型上设置一个watcher，它用来在数据发生变化的时候更新view。这里的watcher和你会在AngularJS中设置的watcher是一样的：\n<script>\n    $scope.$watch(‘aModel’, function(newValue, oldValue) {\n      //update the DOM with newValue\n    });\n</script>\n传入到$watch()中的第二个参数是一个回调函数，该函数在aModel的值发生变化的时候会被调用。当aModel发生变化的时候，这个回调函数会被调用来更新view这一点不难理解，但是，还存在一个很重要的问题！AngularJS是如何知道什么时候要调用这个回调函数呢？换句话说，AngularJS是如何知晓aModel发生了变化，才调用了对应的回调函数呢？它会周期性的运行一个函数来检查scope模型中的数据是否发生了变化吗？好吧，这就是$digest循环的用武之地了。\n在$digest循环中，watchers会被触发。当一个watcher被触发时，AngularJS会检测scope模型，如何它发生了变化那么关联到该watcher的回调函数就会被调用。那么，下一个问题就是$digest循环是在什么时候以各种方式开始的？\n在调用了$scope.$digest()后，$digest循环就开始了。假设你在一个ng-click指令对应的handler函数中更改了scope中的一条数据，此时AngularJS会自动地通过调用$digest()来触发一轮$digest循环。当$digest循环开始后，它会触发每个watcher。这些watchers会检查scope中的当前model值是否和上一次计算得到的model值不同。如果不同，那么对应的回调函数会被执行。调用该函数的结果，就是view中的表达式内容(译注：诸如{{ aModel }})会被更新。除了ng-click指令，还有一些其它的built-in指令以及服务来让你更改models(比如ng-model，$timeout等)和自动触发一次$digest循环。\n目前为止还不错！但是，有一个小问题。在上面的例子中，AngularJS并不直接调用$digest()，而是调用$scope.$apply()，后者会调用$rootScope.$digest()。因此，一轮$digest循环在$rootScope开始，随后会访问到所有的children scope中的watchers。\n现在，假设你将ng-click指令关联到了一个button上，并传入了一个function名到ng-click上。当该button被点击时，AngularJS会将此function包装到一个wrapping function中，然后传入到$scope.$apply()。因此，你的function会正常被执行，修改models(如果需要的话)，此时一轮$digest循环也会被触发，用来确保view也会被更新。\nNote: $scope.$apply()会自动地调用$rootScope.$digest()。$apply()方法有两种形式。第一种会接受一个function作为参数，执行该function并且触发一轮$digest循环。第二种会不接受任何参数，只是触发一轮$digest循环。我们马上会看到为什么第一种形式更好。\n什么时候手动调用$apply()方法？\n如果AngularJS总是将我们的代码wrap到一个function中并传入$apply()，以此来开始一轮$digest循环，那么什么时候才需要我们手动地调用$apply()方法呢？实际上，AngularJS对此有着非常明确的要求，就是它只负责对发生于AngularJS上下文环境中的变更会做出自动地响应(即，在$apply()方法中发生的对于models的更改)。AngularJS的built-in指令就是这样做的，所以任何的model变更都会被反映到view中。但是，如果你在AngularJS上下文之外的任何地方修改了model，那么你就需要通过手动调用$apply()来通知AngularJS。这就像告诉AngularJS，你修改了一些models，希望AngularJS帮你触发watchers来做出正确的响应。\n比如，如果你使用了JavaScript中的setTimeout()来更新一个scope model，那么AngularJS就没有办法知道你更改了什么。这种情况下，调用$apply()就是你的责任了，通过调用它来触发一轮$digest循环。类似地，如果你有一个指令用来设置一个DOM事件listener并且在该listener中修改了一些models，那么你也需要通过手动调用$apply()来确保变更会被正确的反映到view中。\n让我们来看一个例子。加入你有一个页面，一旦该页面加载完毕了，你希望在两秒钟之后显示一条信息。你的实现可能是下面这个样子的：\nHTML:\n[html] view plaincopyprint?\n    <body ng-app=“myApp”>\n      <div ng-controller=“MessageController”>\n        Delayed Message: {{message}}\n      </div>\n    </body>\nJavaScript:\n<script>\n    /* What happens without an $apply() */\n        angular.module(‘myApp’,[]).controller(‘MessageController’, function($scope) {\n          $scope.getMessage = function() {\n            setTimeout(function() {\n              $scope.message = ‘Fetched after 3 seconds\';\n              console.log(‘message:’+$scope.message);\n            }, 2000);\n          }\n          $scope.getMessage();\n        });\n</script>\n通过运行这个例子，你会看到过了两秒钟之后，控制台确实会显示出已经更新的model，然而，view并没有更新。原因也许你已经知道了，就是我们忘了调用$apply()方法。因此，我们需要修改getMessage()，如下所示：\n<script>\n    /* What happens with $apply */\n    angular.module(‘myApp’,[]).controller(‘MessageController’, function($scope) {\n          $scope.getMessage = function() {\n            setTimeout(function() {\n              $scope.$apply(function() {\n                //wrapped this within $apply\n                $scope.message = ‘Fetched after 3 seconds\';\n                console.log(‘message:’ + $scope.message);\n              });\n            }, 2000);\n          }\n          $scope.getMessage();\n        });\n</script>\n如果你运行了上面的例子，你会看到view在两秒钟之后也会更新。唯一的变化是我们的代码现在被wrapped到了$scope.$apply()中，它会自动触发$rootScope.$digest()，从而让watchers被触发用以更新view。\nNote:顺便提一下，你应该使用$timeout service来代替setTimeout()，因为前者会帮你调用$apply()，让你不需要手动地调用它。\n而且，注意在以上的代码中你也可以在修改了model之后手动调用没有参数的$apply()，就像下面这样：\n<script>\n    $scope.getMessage = function() {\n      setTimeout(function() {\n        $scope.message = ‘Fetched after two seconds\';\n        console.log(‘message:’ + $scope.message);\n        $scope.$apply(); //this triggers a $digest\n      }, 2000);\n    };\n</script>\n以上的代码使用了$apply()的第二种形式，也就是没有参数的形式。需要记住的是你总是应该使用接受一个function作为参数的$apply()方法。这是因为当你传入一个function到$apply()中的时候，这个function会被包装到一个try…catch块中，所以一旦有异常发生，该异常会被$exceptionHandler service处理。\n$digest循环会运行多少次？\n当一个$digest循环运行时，watchers会被执行来检查scope中的models是否发生了变化。如果发生了变化，那么相应的listener函数就会被执行。这涉及到一个重要的问题。如果listener函数本身会修改一个scope model呢？AngularJS会怎么处理这种情况？\n答案是$digest循环不会只运行一次。在当前的一次循环结束后，它会再执行一次循环用来检查是否有models发生了变化。这就是脏检查(Dirty Checking)，它用来处理在listener函数被执行时可能引起的model变化。因此，$digest循环会持续运行直到model不再发生变化，或者$digest循环的次数达到了10次。因此，尽可能地不要在listener函数中修改model。\nNote: $digest循环最少也会运行两次，即使在listener函数中并没有改变任何model。正如上面讨论的那样，它会多运行一次来确保models没有变化。\n结语\n我希望这篇文章解释清楚了$apply和$digest。需要记住的最重要的是AngularJS是否能检测到你对于model的修改。如果它不能检测到，那么你就需要手动地调用$apply()。', ' ', NULL, '2016-3-17 09:35:48', '2016-3-18 03:28:51', 0, 0);
INSERT INTO `demo` VALUES (376, 00000000292, 1, 0, 'js', '$on/$emit/$broadcast', '关键词', '注意，事件是挂在scope上的。\n各控制器之间存在嵌套关系，但是他们变量是不被共享的，需要使用共同的服务来共享数据，或者使用(发射/接收/广播)机制来通信', '1.$emit只能向parent controller传递event与data\n2.$broadcast只能向child controller传递event与data\n3.$on用于接收event与data\n4.$emit和$broadcast可以传多个参数，$on也可以接收多个参数。\n5在$on的方法中的event事件参数，其对象的属性和方法如下:\nevent.targetScope            //发出或者传播原始事件的作用域\nevent.currentScope            //目前正在处理的事件的作用域\nevent.name                    //事件名称\nevent.stopPropagation()        //一个防止事件进一步传播(冒泡/捕获)的函数(这只适用于使用`$emit`发出的事件)\nevent.preventDefault()        //这个方法实际上不会做什么事，但是会设置`defaultPrevented`为true。直到事件监听器的实现者采取行动之前它才会检查`defaultPrevented`的值。\nevent.defaultPrevented        //如果调用了`preventDefault`则为true\n6.在事件向上或者向下传播的路径上，可以阻止继续冒泡和捕获：event.stopPropagation() \n\n<div ng-controller=\"ParentCtrl\">                <!--父级-->\n    <div ng-controller=\"SelfCtrl\">              <!--自己-->\n        <a ng-click=\"click()\">click me</a>\n        <div ng-controller=\"ChildCtrl\"></div>   <!--子级-->\n    </div>\n    <div ng-controller=\"BroCtrl\"></div>         <!--平级-->\n</div>\n\n<script>\napp.controller(\'SelfCtrl\', function($scope) {\n  $scope.click = function () {\n    $scope.$broadcast(\'to-child\', \'child\');\n    $scope.$emit(\'to-parent\', \'parent\');\n  }\n});\n\napp.controller(\'ParentCtrl\', function($scope) {\n  $scope.$on(\'to-parent\', function(event,data) {\n    console.log(\'ParentCtrl\', data);       //父级能得到值\n  });\n  $scope.$on(\'to-child\', function(event,data) {\n    console.log(\'ParentCtrl\', data);       //子级得不到值\n  });\n});\n\napp.controller(\'ChildCtrl\', function($scope){\n  $scope.$on(\'to-child\', function(event,data) {\n    console.log(\'ChildCtrl\', data);         //子级能得到值\n  });\n  $scope.$on(\'to-parent\', function(event,data) {\n    console.log(\'ChildCtrl\', data);         //父级得不到值\n  });\n});\n\napp.controller(\'BroCtrl\', function($scope){\n  $scope.$on(\'to-parent\', function(event,data) {\n    console.log(\'BroCtrl\', data);          //平级得不到值\n  });\n  $scope.$on(\'to-child\', function(event,data) {\n    console.log(\'BroCtrl\', data);          //平级得不到值\n  });\n});\n</script>\n/*相关理论：\n  AngularJS中的作用域具有继承性，并且结构是嵌套的。也就是说，对于每个Angular应用或者ng-app来说，只有一个主作用域$rootScope，其他所有作用域都会继承这个主作用域，或者嵌套在这个主作用域内部。通常情况下，你会发现作用域之间不会共享变量，并且互相之间不会基于原型继承。\n        如果需要在两个作用域之间进行通信，应该怎么做呢？其中一种方法是：创建一个服务，这个服务在整个应用范围内是一个单例，并且所有作用域之间的交互都通过它进行。另一种方法是：通过作用域上的事件进行交互。但是，这样做存在一些局限性。例如，你通常不能向正在监听的所有作用域同时广播事件。你必须选择是和父节点交互还是和子节点交互。*/\n', NULL, '2016-3-17 09:37:10', '2016-4-13 12:04:00', 0, 0);
INSERT INTO `demo` VALUES (377, 00000000365, 1, 0, 'js', 'AppCache +manifest', '关键词', '判断是否支持if(window.applicationCache)\nApplication Cache（简称 AppCache)似乎是为支持 Web App 离线使用而开发的缓存机制。它的缓存机制类似于浏览器的缓存（Cache-Control 和 Last-Modified）机制，都是以文件为单位进行缓存，且文件有一定更新机制。但 AppCache 是对浏览器缓存机制的补充，不是替代。\n\n先拿 W3C 官方的一个例子，说下 AppCache 机制的用法与功能。\n\"Get Date and TimeTry opening this page, then go offline, and reload the page. The script and the image should still work.“\n上面 HTML 文档，引用外部一个 JS 文件和一个 GIF 图片文件，在其 HTML 头中通过 manifest 属性引用了一个 appcache 结尾的文件。\n\n我们在 Google Chrome 浏览器中打开这个 HTML 链接，JS 功能正常，图片也显示正常。禁用网络，关闭浏览器重新打开这个链接，发现 JS 工作正常，图片也显示正常。当然也有可能是浏览缓存起的作用，我们可以在文件的浏览器缓存过期后，禁用网络再试，发现 HTML 页面也是正常的。\n\n通过 Google Chrome 浏览器自带的工具，我们可以查看已经缓存的 AppCache（分 HOST)。\n\nhq9dR63.gif\n\n上面截图中的缓存，就是我们刚才打开 HTML 的页面 AppCache。从截图中看，HTML 页面及 HTML 引用的 JS、GIF 图像文件都被缓存了；另外 HTML 头中 manifest 属性引用的 appcache 文件也缓存了。\n\nAppCache 的原理有两个关键点：manifest 属性和 manifest 文件。\n\nHTML 在头中通过 manifest 属性引用 manifest 文件。manifest 文件，就是上面以 appcache 结尾的文件，是一个普通文件文件，列出了需要缓存的文件。\n上面截图中的 manifest 文件，就 HTML 代码引用的 manifest 文件。文件比较简单，第一行是关键字，第二、三行就是要缓存的文件路径（相对路径）。这只是最简单的 manifest 文件，完整的还包括其他关键字与内容。引用 manifest 文件的 HTML 和 manifest 文件中列出的要缓存的文件最终都会被浏览器缓存。\n\n完整的 manifest 文件，包括三个 Section，类型 Windows 中 ini 配置文件的 Section，不过不要中括号。\n\nCACHE MANIFEST - Files listed under this header will be cached after they are downloaded for the first time\nNETWORK - Files listed under this header require a connection to the server, and will never be cached\nFALLBACK - Files listed under this header specifies fallback pages if a page is inaccessible\n完整的 manifest 文件，如：\nCACHE MANIFEST\n# 2012-02-21 v1.0.0\n/theme.css\n/logo.gif\n/main.js\nNETWORK:\nlogin.asp\nFALLBACK:\n/html/ /offline.html\n总的来说，浏览器在首次加载 HTML 文件时，会解析 manifest 属性，并读取 manifest 文件，获取 Section：CACHE MANIFEST 下要缓存的文件列表，再对文件缓存。\n\nAppCache 的缓存文件，与浏览器的缓存文件分开存储的，还是一份？应该是分开的。因为 AppCache 在本地也有 5MB（分 HOST）的空间限制。\n\nAppCache 在首次加载生成后，也有更新机制。被缓存的文件如果要更新，需要更新 manifest 文件。因为浏览器在下次加载时，除了会默认使用缓存外，还会在后台检查 manifest 文件有没有修改（byte by byte)。发现有修改，就会重新获取 manifest 文件，对 Section：CACHE MANIFEST 下文件列表检查更新。manifest 文件与缓存文件的检查更新也遵守浏览器缓存机制。\n\n如用用户手动清了 AppCache 缓存，下次加载时，浏览器会重新生成缓存，也可算是一种缓存的更新。另外， Web App 也可用代码实现缓存更新。\n\n分析：AppCache 看起来是一种比较好的缓存方法，除了缓存静态资源文件外，也适合构建 Web 离线 App。在实际使用中有些需要注意的地方，有一些可以说是”坑“。\n\n要更新缓存的文件，需要更新包含它的 manifest 文件，那怕只加一个空格。常用的方法，是修改 manifest 文件注释中的版本号。如：# 2012-02-21 v1.0.0\n被缓存的文件，浏览器是先使用，再通过检查 manifest 文件是否有更新来更新缓存文件。这样缓存文件可能用的不是最新的版本。\n在更新缓存过程中，如果有一个文件更新失败，则整个更新会失败。\nmanifest 和引用它的HTML要在相同 HOST。\nmanifest 文件中的文件列表，如果是相对路径，则是相对 manifest 文件的相对路径。\nmanifest 也有可能更新出错，导致缓存文件更新失败。\n没有缓存的资源在已经缓存的 HTML 中不能加载，即使有网络。例如：http://appcache-demo.s3-website-us-east-1.amazonaws.com/without-network/\nmanifest 文件本身不能被缓存，且 manifest 文件的更新使用的是浏览器缓存机制。所以 manifest 文件的 Cache-Control 缓存时间不能设置太长。\n另外，根据官方文档，AppCache 已经不推荐使用了，标准也不会再支持。现在主流的浏览器都是还支持 AppCache的，以后就不太确定了。\n\n在Android 内嵌 Webview中，需要通过 Webview 设置接口启用 AppCache，同时还要设置缓存文件的存储路径，另外还可以设置缓存的空间大小。\nWebView myWebView = (WebView) findViewById(R.id.webview);\nWebSettings webSettings = myWebView.getSettings();\nwebSettings.setAppCacheEnabled(true);\nfinal String cachePath = getApplicationContext().getDir(\"cache\", Context.MODE_PRIVATE).getPath();\nwebSettings.setAppCachePath(cachePath);\nwebSettings.setAppCacheMaxSize(5*1024*1024);', 'CACHE MANIFEST\n# 2012-02-21 v1.0.0\n/theme.css\n/logo.gif\n/main.js\nNETWORK:\nlogin.asp\nFALLBACK:\n/html/ /offline.html', NULL, '2016-3-18 04:01:57', '2016-4-17 21:05:30', 0, 0);
INSERT INTO `demo` VALUES (378, 00000000292, 1, 0, 'js', '$compile/pre-link/post-link', '关键词', '如何理解打印结果\n1.compile中的tElem是最原始的模版，未编译过的，\n2.pre-link是提前预订的一个对post-link函数的一个初始化，相当于一个静态function，会在模版编译完毕即初始化，\n但是模版编译是一个迭代的过程，直到深层编译完毕，才算完毕，所以3个compile都执行了，才开始执行pre-link\n3.编译完成，初始化完成，这时候的post-link才开始运行，但是这种嵌套是由里向外的，就好比a(b(c()));肯定是最深层象开始执行，逐步向外，所以这里post-link的执行是一个反向的，当父函数执行的时候，子函数已经执行完毕，父函数都可以使用子函数的返回值了\n4.第四点说一下compile的参数tElem是最原始的模版，没有经过任何编译的，而pre-link和post-link中的iElem的都是经过compile函数处理过的，都是编译后的模版。', 'var app = angular.module(\'plunker\', []);\n\n    function createDirective(name){\n      return function(){\n        return {\n          restrict: \'E\',\n          compile: function(tElem, tAttrs){\n            console.log(name + \': compile => \' + tElem.html());\n            return {\n              pre: function(scope, iElem, iAttrs){\n                console.log(name + \': pre link => \' + iElem.html());\n              },\n              post: function(scope, iElem, iAttrs){\n                console.log(name + \': post link => \' + iElem.html());\n              }\n            }\n          }\n        }\n      }\n    }\n\n    app.directive(\'levelOne\', createDirective(\'levelOne\'));\n    app.directive(\'levelTwo\', createDirective(\'levelTwo\'));\n    app.directive(\'levelThree\', createDirective(\'levelThree\'));\n\n//打印结果\n    // HERE THE ELEMENTS ARE STILL THE ORIGINAL TEMPLATE ELEMENTS\n\n    // COMPILE PHASE\n    // levelOne:    compile function is called on original DOM\n    // levelTwo:    compile function is called on original DOM\n    // levelThree:  compile function is called on original DOM\n\n    // AS OF HERE, THE ELEMENTS HAVE BEEN INSTANTIATED AND\n    // ARE BOUND TO A SCOPE\n    // (E.G. NG-REPEAT WOULD HAVE MULTIPLE INSTANCES)\n\n    // PRE-LINK PHASE\n    // levelOne:    pre link function is called on element instance\n    // levelTwo:    pre link function is called on element instance\n    // levelThree:  pre link function is called on element instance\n\n    // POST-LINK PHASE (Notice the reverse order)\n    // levelThree:  post link function is called on element instance\n    // levelTwo:    post link function is called on element instance\n    // levelOne:    post link function is called on element instance', NULL, '2016-3-18 09:51:12', '2016-3-18 10:37:33', 0, 0);
INSERT INTO `demo` VALUES (379, 00000000240, 1, 0, 'html', 'slice/substr/substring', '关键词', 'substr\n该方法的arg2和其它两个方法的arg2压根就代表不同意义，所以单独揪出来。\n当arg1<0时，不同浏览器的结果不同。IE 直接将arg1改成0， Chrome 下标读取方式由原来的从左往右读改成从右往左读\n\nsubstring和slice\n(1)arg2 > arg1，即参数2大于参数1时\nsubstring：自动颠倒位置，数值大的在arg2位置上，数值小的在arg1位置上\nslice：返回空字符串\n(2)对负数的处理\nsubstring：将数值为负数的参数转换为0\nslice：将数值为负数的参数转换为(字符串长度-参数数值) ', '//==================demo\n//substr:\ndocument.write(\"|\" + str.substr(0,5) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substr(0) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substr(5,1) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substr(-5,2) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substr(-2,-5) + \"|\" + \"<br />\"); \n//substring \ndocument.write(\"|\" + str.substring(0,5) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substring(0) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substring(5,1) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substring(-5,2) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substring(-2,-5) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.substring(2,-5) + \"|\" + \"<br />\"); \n//slice\ndocument.write(\"|\" + str.slice(0,5) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.slice(0) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.slice(5,1) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.slice(-5,2) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.slice(-2,-5) + \"|\" + \"<br />\");\ndocument.write(\"|\" + str.slice(2,-5) + \"|\" + \"<br />\"); ', NULL, '2016-3-18 13:34:52', '2016-3-18 13:41:59', 0, 0);
INSERT INTO `demo` VALUES (380, 00000000232, 1, 0, 'js', '单双字节混排的截取', '关键词', '', '//方法一，长短的判断\nString.prototype.getLength=function(){\n var text=this.replace(/[^\\x00-\\xff]/g,\"**\");\n return text.length;\n}\n//方法二，循环截取并返回：\nString.prototype.getShortForm=function(len,alt){\n var tempStr=this;\n if(this.getLength()>len){\n  if(!alt) {\n   alt=\"...\";\n  }\n  var i=0;\n  for(var z=0;z<len;z++){\n   if(tempStr.charCodeAt(z)>255){\n    i=i+2;\n   }else{\n    i=i+1;\n   }\n   if(i>=len){\n    tempStr=tempStr.slice(0,(z + 1))+alt;\n    break;\n   }\n  }\n  return tempStr;\n }else{\n  return this+\"\";\n }\n} ', NULL, '2016-3-18 13:44:14', '2016-3-18 13:45:40', 0, 0);
INSERT INTO `demo` VALUES (381, 00000000084, 1, 0, 'js', '新的属性attribute', '关键词', '描述', '新代码', NULL, '2016-3-18 14:47:04', '2016-3-18 14:47:04', 0, 0);
INSERT INTO `demo` VALUES (382, 00000000381, 1, 0, 'js', 'contenteditable', '关键词', '', '<div contenteditable=\"true\">这是一段可编辑的段落。请试<img src=\"\">着编辑该文本。</div>', NULL, '2016-3-18 14:47:13', '2016-3-18 14:47:29', 0, 0);
INSERT INTO `demo` VALUES (383, 00000000292, 1, 0, 'js', '$transclude', '关键词', '1.transclude的简单用法通常在指令中会设置transclude:true，然后在模版中使用ng-transclude,这样的结果就是指令原生代码会被保存下来，并是指令初始化完毕后，再将原始代码回填到标记有ng-transclude的标签内部中去。这个搬运发生再编译过程中，指令原代码内部如果存在需要编译的内容，在这个过程中也会被编译。整体就是一个活生生的angular编译后的模版。', '//==========================demo1\n\ntestapp.directive(\'buttonBar\', function() {\n    return {\n        restrict: \'EA\',\n        template: \'<div class=\"span4 well clearfix\"><div class=\"pull-right\" ng-transclude></div></div>\',\n        replace: true,\n        transclude: true\n    };\n});\n\n//==========================demo1\n//注意\n//1.一旦向controller中注入了$attr,ng-consclude将无效.\n//2.ng-consclude是一个html()式的操作，请确保带有这个指令的元素只是一个占位符设置多份ng-consclude的时候，每一份都会被填充.\n//这是一个简单的搬运把原始的代码搬运到了模版的指定位置，但是更加复杂的需求就不够用了，比如原生代码中很多离散的数据，需要搬运到编译后的模版的不同位置，显然就不够用了！\n\n//==========================demo2\n\ntestapp.directive(\'buttonBar\', function() {\n    return {\n        restrict: \'EA\',\n        template: \'<div class=\"span4 well clearfix\"><div class=\"primary-block pull-right\"></div><div class=\"secondary-block\"></div></div>\',\n        replace: true,\n        transclude: true,\n        compile: function(elem, attrs, transcludeFn) {//elem为当前指令的原始dom结构，未经过指令的编译器编译，但是可以正常进行dom操作，attr为当前指令的属性！\n            return function (scope, element, attrs) {\n                transcludeFn(scope, function(clone) {//clone代码是原代码编译后的引用，从其中拿一些数据到新的模版中去使用\n                    var primaryBlock = elem.find(\'div.primary-block\');//原生代码拿到一些dom\n                    var secondaryBlock = elem.find(\'div.secondary-block\');\n                    var transcludedButtons = clone.filter(\':button\');//clone作为入口，拿到了各种本指令编译后的一些button\n                    angular.forEach(transcludedButtons, function(e) {\n                        if (angular.element(e).hasClass(\'primary\')) {\n                            primaryBlock.append(e);//把button放入编译后的对应模版中！\n                        } else if (angular.element(e).hasClass(\'secondary\')) {\n                            secondaryBlock.append(e);\n                        }\n                    });\n                });\n            };\n        }\n    };\n});\n//==========================demo2\n//评论：transclude第二个用处是一个函数，这个函数作为参数传入到指令中的compile(编译函数)中去，参与编译，做一次编译后的二次调整的事情。\n//======================================demo3\n\ntestapp.directive(\'buttonBar\', function() {\n    return {\n        restrict: \'EA\',\n        template: \'<div class=\"span4 well clearfix\"><div class=\"primary-block pull-right\"></div><div class=\"secondary-block\"></div></div>\',\n        replace: true,\n        transclude: true,\n        scope: {},\n        controller: [\'$scope\', \'$element\', \'$transclude\', function ($scope, $element, $transclude) {//$element为模版\n            $transclude(function(clone) {//服务接收一个处理函数，函数的参数就是clone\n                var primaryBlock = $element.find(\'div.primary-block\');\n                var secondaryBlock = $element.find(\'div.secondary-block\');\n                var transcludedButtons = clone.filter(\':button\');//clone为编译后的标记了consclude元素\n                angular.forEach(transcludedButtons, function(e) {\n                    if (angular.element(e).hasClass(\'primary\')) {\n                        primaryBlock.append(e);//然后放入模版中对应的位置\n                    } else if (angular.element(e).hasClass(\'secondary\')) {\n                        secondaryBlock.append(e);\n                    }\n                });\n            });\n        }],\n    };\n})\n\n//======================================demo3\n//评论： 这个是作为一个服务注入到指令的controller中去，而其中服务将接受一个处理函数作为参数，处理函数将接受clone参数，之后对模版进行一下数据搬运的操作。\n', NULL, '2016-3-19 09:46:32', '2016-3-19 15:53:33', 0, 0);
INSERT INTO `demo` VALUES (384, 00000000370, 1, 0, 'js', '指令的执行流程', '关键词', '', '指令内部的执行流程为，编译compile-->controller-->pre-link-->post-link\n其中如果设置了compile，那么单独设置link将被无视，如果不设置compile，将会是controller-->link的过程', NULL, '2016-3-19 11:26:08', '2016-3-19 11:27:13', 0, 0);
INSERT INTO `demo` VALUES (385, 00000000234, 1, 0, 'js', 'JSON对象', '关键词', '', 'JSON.parse(text,reviver);\n// text\n// 必需。 一个有效的 JSON 字符串。\n// reviver\n// 可选。 一个转换结果的函数。 将为对象的每个成员调用此函数。 如果成员包含嵌套对象，则先于父对象转换嵌套对象。 对于每个成员，会发生以下情况：\n// 如果 reviver 返回一个有效值，则成员值将替换为转换后的值。\n// 如果 reviver 返回它接收的相同值，则不修改成员值。\n// 如果 reviver 返回 null 或 undefined，则删除成员。\nJSON.stringify(value,replacer,space);\n// value\n// 必需。 要转换的 JavaScript 值（通常为对象或数组）。\n// replacer\n// 可选。 用于转换结果的函数或数组。\n// 如果 replacer 为函数，则 JSON.stringify 将调用该函数，并传入每个成员的键和值。 使用返回值而不是原始值。 如果此函数返回 undefined，则排除成员。 根对象的键是一个空字符串：\"\"。\n// 如果 replacer 是一个数组，则仅转换该数组中具有键值的成员。 成员的转换顺序与键在数组中的顺序一样。 当 value 参数也为数组时，将忽略 replacer 数组。\n// space\n// 可选。 向返回值 JSON 文本添加缩进、空格和换行符以使其更易于读取。\n// 如果省略 space，则将生成返回值文本，而没有任何额外空格。\n// 如果 space 是一个数字，则返回值文本在每个级别缩进指定数目的空格。 如果 space 大于 10，则文本缩进 10 个空格。\n// 如果 space 是一个非空字符串（例如“\\t”），则返回值文本在每个级别中缩进字符串中的字符。\n// 如果 space 是长度大于 10 个字符的字符串，则使用前 10 个字符。\n', NULL, '2016-3-19 11:40:19', '2016-3-19 11:43:04', 0, 0);
INSERT INTO `demo` VALUES (386, 00000000292, 1, 0, 'js', '@=&', '关键词', 'scope: 创建指令的作用范围，scope在指令中作为属性标签传递。Scope 是创建可以复用指令的必要条件，每个指令（不论是处于嵌套指令的哪一级）都有其唯一的作用域，它不依赖于父scope。scope 对象定义names 和types 变量。上面的例子即创建了3个scope变量。', '//================================demo1\nmyApp.directive(\"myDir\", function() { \n  return { \n    restrict: \"E\",        // 指令是一个元素 (并非属性) \n    scope: {              // 设置指令对于的scope \n      name: \"@\",          // name 值传递 （字符串，单向绑定） \n      amount: \"=\",        // amount 引用传递（双向绑定） \n      save: \"&\"           // 保存操作 \n    }, \n    template:             // 替换HTML (使用scope中的变量) \n      \"<div>\" + \n      \"  {{name}}: <input ng-model=\'amount\' />\" + \n      \"  <button ng-click=\'save()\'>Save</button>\" + \n      \"</div>\", \n    replace: true,        // 使用模板替换原始标记 \n    transclude: false,    // 不复制原始HTML内容 \n    controller: [ \"$scope\", function ($scope) { …  }], \n    link: function (scope, element, attrs, controller) {…} \n  } \n}); \n//================================demo2\n// 1.name: \"@\" （值传递，单向绑定）：\n// \"@\"符号表示变量是值传递。指令会检索从父级scope中传递而来字符串中的值。指令可以使用该值但无法修改，是最常用的变量。\n// 2.amount: \"=\" （引用,双向绑定）\n// \"=\"符号表示变量是引用传递。指令检索主Scope中的引用取值。值可以是任意类型的，包括复合对象和数组。指令可以更改父级Scope中的值，所以当指令需要修改父级Scope中的值时我们就需要使用这种类型。\n// 3.save: \"&\" (表达式)\n// “&”符号表示变量是在父级Scope中启作用的表达式。它允许指令实现比修改值更高级的操作。\n//================================demo2\nm1.directive(\'myTab\',function(){\n    return {\n        restrict : \'ECMA\',\n        replace : true,    //替换的方式插入内容//绑定策略\n        scope : {\n            myId : \'@\',        //解析普通字符串\n            myName : \'=\',    //解析数据\n            myFn : \'&\'        //函数\n        },\n        controller : [\'$scope\',function($scope){\n            //共享数据存放在这里\n            $scope.name = \'this is a xiecg\';\n        }],\n        template : \'<div id=\"{{myId}}\">\\\n                    <input type=\"button\" value=\"1\" class=\"active\" ng-click=\"myFn({num:456})\">\\\n                    <input type=\"button\" value=\"2\">\\\n                    <input type=\"button\" value=\"3\">\\\n                    <div style=\"display:block;\">{{myName}}</div>\\\n                    <div>2222</div>\\\n                    <div>3333</div>\\\n                </div>\'\n    };\n});\n//================================demo2\n// 1：scope默认是false，为true表示独立作用域。\n// 2：scope给予一个对象时，表示执行绑定策略，在template上调用这些数据。\n// 　　a)：我们在DOM元素上my-id，我们使用@符号，表示解析普通字符串，说白了就是你写什麽就是什麽。\n// 　　b)：使用=符号，表示解析数据。\n// 　　c)：使用&符号，表示这绑定一个函数。\n// 3：controller，表示绑定指令内部使用的数据。', NULL, '2016-3-19 13:10:33', '2016-3-19 13:34:47', 0, 0);
INSERT INTO `demo` VALUES (387, 00000000292, 1, 0, 'js', 'link/pre-link/post-link', '关键词', '', 'compile: function compile( tElement, tAttributes, transcludeFn ) {\n    // Compile code goes here.\n    return {\n        pre: function preLink( scope, element, attributes, controller, transcludeFn ) {\n            // Pre-link code goes here\n        },\n        post: function postLink( scope, element, attributes, controller, transcludeFn ) {\n            // Post-link code goes here\n        }\n    };\n}\nlink: function( scope, element, attributes, controller, transcludeFn ) {\n    // Post-link code goes here\n}\n// scope: 指令Scope的引用。scope 变量在初始化时是不被定义的，link 方法会注册监视器监视值变化事件。\n// element: 包含指令的DOM元素的引用， link 方法一般通过jQuery 操作实例（如果没有加载jQuery，还可以使用Angular\'s jqLite ）。\n//controller: 在有嵌套指令的情况下使用。这个参数作用在于把子指令的引用提供给父指令，允许指令之间进行交互， tab 指令就是使用该参数较典型的例子', NULL, '2016-3-19 13:20:29', '2016-3-19 13:25:31', 0, 0);
INSERT INTO `demo` VALUES (388, 00000000293, 1, 0, 'html', 'directive嵌套', '关键词', '', '<!DOCTYPE HTML>\n<html ng-app=\"myApp\">\n<head>\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n<title>自定义指令间的互相交互</title>\n<script type=\"text/javascript\" src=\"js/angular.min.js\"></script>\n</head>\n<body>\n<div>\n    <hello>\n        <hi></hi>\n    </hello>\n</div>\n<script type=\"text/javascript\">\nvar m1 = angular.module(\'myApp\',[]);\nm1.directive(\'hello\',function(){\n    return {\n        restrict : \'E\',\n        replace : true,\n        transclude : true,   //允许自定义指令的嵌套，通过ng-transclude指定嵌套的范围\n        controller : function($scope){\n            $scope.name = \'xiecg\';\n            this.name = \'xiecg\';    //使用this共享给其他指令\n        },\n        template : \'<div>hello angular <h1 ng-transclude></h1></div>\'\n    };\n});\nm1.directive(\'hi\',function(){\n    return {\n        restrict : \'E\',\n        replace : true,\n        require : \'^hello\',//hello指令属性hi指令的父级，需要用^符号指定。如果无法指定，使用?容错处理。\n        template : \'<span>hi angular {{name}}</span>\',\n        link : function(scope,element,attr,reController){\n            console.log(reController);    //得到父级hello指令中共享出来的数据\n        }\n    };\n});\n</script>\n</body>\n</html>', NULL, '2016-3-19 13:39:22', '2016-3-19 13:40:23', 0, 0);
INSERT INTO `demo` VALUES (393, 00000000391, 1, 0, 'js', '根据标签选择', '关键词', 'angular.element的参数要求是HTML string or DOMElement;\nangular.element 虽然很接近 jQuery，但是直接通过 HTML tag 去获取元素还是不行的，最简单的办法是这样：', 'angular.element(document.querySelector(\'p\'));', NULL, '2016-3-19 15:07:21', '2016-3-19 15:08:34', 0, 0);
INSERT INTO `demo` VALUES (394, 00000000293, 1, 0, 'js', '自定义指令套以jquery的扩展插件', '关键词', '这么做的主要目的是，有了指令的环境，可以写指令的一些语句，对数据模型进行了修改！', 'var directives = angular.module(\'directives\', []);\n  \ndirectives.directive(\'datepicker\', function() {\n   return function(scope, element, attrs) {\n       element.datepicker({\n           inline: true,\n           dateFormat: \'dd.mm.yy\',\n           onSelect: function(dateText) {\n               var modelPath = $(this).attr(\'ng-model\');\n               putObject(modelPath, scope, dateText);\n               scope.$apply();\n           }\n       });\n   }\n});', NULL, '2016-3-19 15:14:26', '2016-3-19 15:15:22', 0, 0);
INSERT INTO `demo` VALUES (395, 00000000292, 1, 0, 'js', '$http', '关键词', '234', 'var promise = $http({});\nvar promise = $http({\n    url:\"url\",\n    method:\"post\",//GET/DELETE/HEAD/JSONP/POST/PUT\n    data:blob//通常配合post\n});\nvar promise = $http({\n    url:\"url\",\n    method:\"get\",//GET/DELETE/HEAD/JSONP/POST/PUT\n    params:{\n    \"username\":\"tan\";\n    })\n});\n\nvar promise = $http.get(url,{cache:true});\nvar promise = $http.jsonp(url,config);\npromise.success().error().then();\n\nvar promise = $http({\n    url:\"url\",\n    method:\"get\",//GET/DELETE/HEAD/JSONP/POST/PUT\n    data:new Blob([\"Hello world\"],{type:\"text/plain\"})//通常配合post\n}).success(function(data,header,config,status){\n//响应成功\n}).error(function(data,header,config,status){\n//处理响应失败\n}).then(function(resp){\n    //resp是一个响应对象\n    resp.data;\n    resp.status;\n    resp.headers;\n    resp.config;\n    resp.statusText;\n},function(resp){\n    //resp是一个响应对象\n    resp.data;\n    resp.status;\n    resp.headers;\n    resp.config;\n    resp.statusText;\n});\n//=====================post请求中request payload转form data问题方案\n//1.再config中修改$httpprovider配置\napp.config(fucntion($httpProvider){\n    $httpProvider.default.transformRequest = function(obj){\n        var str = [];\n        for(var p in obj){\n            str.push(encodeURIComponent(p)+\"=\"+encodeURIComponent(obj[p]));\n        }\n        return str.join(\"&\");\n    }\n    $httpProvider.default.headers.post{\n        \"Content-Type\":\"application/x-www-form-urllencoded\"\n    }\n});\n//2.单独设置\n$http({\n    method:\"post\",\n    url:\"XXX.php\",\n    data:{name:\"aaa\",id:1,age:20},\n    header:{\"Content-Type\":\"app/x-www-form-urllencoded\"},\n    transformRequest:fucntion(obj){\n        var str = [];\n        for(var p in obj){\n            str.push(encodeURIComponent(p)+\"=\"+encodeURIComponent(obj[p]));\n        }\n        return str.join(\"&\");\n    }\n})', NULL, '2016-3-19 15:18:26', '2016-5-9 09:48:26', 0, 0);
INSERT INTO `demo` VALUES (396, 00000000291, 1, 0, 'js', '后台语言的支持', '关键词', '描述', '新代码', NULL, '2016-3-19 15:19:12', '2016-3-19 15:19:12', 0, 0);
INSERT INTO `demo` VALUES (397, 00000000396, 1, 0, 'js', '后台语言如何接收数据模型', '关键词', 'file_get_contents() 函数把整个文件读入一个字符串中。和 file() 一样，不同的是 file_get_contents() 把文件读入一个字符串。file_get_contents() 函数是用于将文件的内容读入到一个字符串中的首选方法。如果操作系统支持，还会使用内存映射技术来增强性能。', ' ', NULL, '2016-3-19 15:19:48', '2016-3-19 15:20:16', 0, 0);
INSERT INTO `demo` VALUES (398, 00000000291, 1, 0, 'js', '知识点', '关键词', '描述', '新代码', NULL, '2016-3-19 15:23:23', '2016-3-19 15:23:23', 0, 0);
INSERT INTO `demo` VALUES (399, 00000000398, 1, 0, 'js', '样式控制', '关键词', 'angular不建议直接操作DOM，所以如果你希望addclass，新建一个变量与样式对应，参与逻辑！', '<button ng-click=\"showActive()\"></button>\n<p ng-class=\"{\'active\':show===1}\"></p>\n', NULL, '2016-3-19 15:23:37', '2016-3-19 15:24:50', 0, 0);
INSERT INTO `demo` VALUES (400, 00000000291, 1, 0, 'js', '作品', '关键词', '描述', '新代码', NULL, '2016-3-19 15:59:27', '2016-3-19 15:59:27', 0, 0);
INSERT INTO `demo` VALUES (401, 00000000400, 1, 0, 'html', 'star指令', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n    <script src=\"jquery.js\"></script>\n</head>\n<body ng-app=\"mystar\">\n    <star>4.9</star>\n    <star>3.2</star>\n    <star>2.2</star>\n    <star>1.1</star>\n    <star>4</star>\n    <script>\n        var mystar = angular.module(\"mystar\",[]);\n        mystar.directive(\"star\",function(){\n            var $tpl =\'\';\n            $tpl += \'<p class=\"tbm-2\">\';\n            $tpl += \'    <span class=\"tbm-star\"></span>\';\n            $tpl += \'    <span class=\"tbm-starcount\" ng-transclude></span>\';\n            $tpl += \'</p>\';\n            return{\n                restrict:\"E\",\n                template:$tpl,\n                controller:function($scope,$element,$transclude){\n                    var starNum = 0;\n                    $transclude(function(clone) {\n                        starNum = $(clone).text();\n                    });\n                    $element = $($element);\n                    $element.find(\".tbm-star\").html(getstar(starNum,100,16));\n                    function getstar(str,width,height){\n                        var x = document.createElement(\"CANVAS\");\n                        x.width=width;\n                        x.height=height;\n                        var ctx=x.getContext(\"2d\");\n                        var img = new Image();\n                        img.onload=function(){\n                            ctx.drawImage(img,0,0,200,32,0,0,width,height);\n                            ctx.fillStyle=\"#FFD800\";\n                            ctx.globalCompositeOperation=\"source-atop\";\n                            var float = parseFloat(str);\n                            var widthRate = float/5;\n                            if(widthRate<0||widthRate>1){\n                                widthRate =0;\n                            }\n                            var wid = 100*widthRate;\n                            ctx.fillRect(0,0,wid,height);\n                        }\n                        img.src=\"data:image/png;base64,\";\n                        return x;\n                    }\n                },\n                replace: true,\n                transclude: true\n            }\n        });\n    </script>\n</body>\n</html>', NULL, '2016-3-19 15:59:44', '2016-3-19 15:59:51', 0, 0);
INSERT INTO `demo` VALUES (402, 00000000398, 1, 0, 'js', '{{ }} 的问题', '关键词', '解决办法：\n使用 ng-cloak directive 来隐藏它\n使用 ng-bind 替代 {{ }}', '', NULL, '2016-3-19 17:03:18', '2016-3-19 17:03:54', 0, 0);
INSERT INTO `demo` VALUES (403, 00000000292, 1, 0, 'html', 'ng-options', '关键词', 'for a in b, /a...../a.XX as a.XXX', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n    <script src=\"jquery.js\"></script>\n</head>\n<body  ng-app=\"OptionApp\" ng-controller=\"OptionCtrl\">\n<!--  -->\n<select ng-model=\"seleted\" ng-options=\"a.name for a in animals\">\n<option value=\"\">请选择你的萌宠</option>\n</select>\n<!--  -->\n<select ng-model=\"seleted\" ng-options=\"(a.name + \'爱吃\' + a.food) for a in animals\">\n<option value=\"\">请选择你的萌宠</option>\n</select>\n<!--  -->\n<select ng-model=\"seleted\" ng-options=\"(a.name + \'的爱好是\' + a.favor) group by a.sex for a in animals\">\n<option value=\"\">请选择你的萌宠</option>\n</select>\n<!--  -->\n<select ng-model=\"seletedId\" ng-options=\"a.id as a.name for a in animals\">\n<option value=\"\">请选择你的萌宠</option>\n</select>\n<script>\n    var app = angular.module(\'OptionApp\', []);\n  app.controller(\'OptionCtrl\', [\'$scope\', function($scope){\n    $scope.seleted = \'\';\n    $scope.animals = [\n      {\n        id: \'00001\',\n        name: \'猫\',\n        sex: \'雌\',\n        food: \'鱼\',\n        favor: \'玩球\'\n      },\n      {\n        id: \'00002\',\n        name: \'狗\',\n        sex: \'雄\',\n        food: \'骨头\',\n        favor: \'接盘子\'\n      },\n      {\n        id: \'00003\',\n        name: \'兔\',\n        sex: \'雌\',\n        food: \'胡萝卜\',\n        favor: \'刨洞\'\n      },\n      {\n        id: \'00004\',\n        name: \'狮\',\n        sex: \'雄\',\n        food: \'肉\',\n        favor: \'猎物\'\n      }\n    ];\n  }]);\n</script>\n</body>\n</html>', NULL, '2016-3-19 17:15:07', '2016-3-19 17:57:23', 0, 0);
INSERT INTO `demo` VALUES (404, 00000000292, 1, 0, 'html', 'bootstrap手动初始化', '关键词', '在高级开发中，例如使用脚本装载应用，您也可以使用bootstrap手动引导AngularJS应用。', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<div ng-controller=\"mycontroller\">\n    Hello {{world}}!\n</div>\n    <button onclick=\"play()\">play</button>\n    <script>\n        function play(){\n            angular.bootstrap(document,[\"myapp\"]);//第一个参数是期望root的元素，第二个参数是一个应用名称组成的数组，第三个参数是一些配置文件，是一个对象格式\n        }\n        var  app = angular.module(\"myapp\",[]);\n        app.controller(\"mycontroller\",function($scope){\n            $scope.world = \"china\";\n        });\n        // angular.element(document).ready(function() {\n        //     console.log(\"mk\");\n        //     angular.bootstrap(document,[\"myapp\"]);\n        // });\n    </script>\n</body>\n</html>\n<!----------------- demo2 ------------------>\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<div>\n<input ng-model=\"world\" value=\"test\" type=\"text\"/>\n    Hello {{world}}!\n</div>\n    <script>\n        angular.element(document).ready(function() {\n            console.log(\"mk\");\n            angular.bootstrap(document);\n        });\n    </script>\n</body>\n</html>', NULL, '2016-3-20 22:19:08', '2016-3-22 10:20:31', 0, 0);
INSERT INTO `demo` VALUES (405, 00000000291, 1, 0, 'js', 'jasmine', '关键词', '描述', '新代码', NULL, '2016-3-20 22:40:09', '2016-3-20 22:40:09', 0, 0);
INSERT INTO `demo` VALUES (406, 00000000405, 1, 0, 'js', 'describe/it/expect/toEqual', '关键词', '', '    新数据  //=========================demo\n    //建立个describe块\n    describe(\'JavaScript addition operator\',function(){ \n        //建立it块\n        it(\'adds two numbers together\',function(){ \n            //测试1+2是否等于3\n            expect(1 +2).toEqual(3); \n        }); \n    });\n\n//===============================demo\n//1.describe和it函数都有二个参数：\n//第一个参数：测试描述（一般使用英文，当然你使用中文也是完全没问题的）；\n//第二个参数：测试逻辑函数（具体干活的主）\n//2.expect方法用于表明你测试的预期，toEqual是它的子方法，表示是否等于你的预期。所以这句代码可以翻译为，1 + 2等于3，如果等于3，那么it函数块测试通过，it测试通过，那么describe也就测试通过。\n//3.it函数块可以包含多个expect过程，只要有其中的expect不符合期望，it就会测试不通过；而describe也可以包含多个it，只要有中有一个it报错，那么describe就会测试不通过。  新数据    新数据  //=========================demo\n    //建立个describe块\n    describe(\'JavaScript addition operator\',function(){ \n        //建立it块\n        it(\'adds two numbers together\',function(){ \n            //测试1+2是否等于3\n            expect(1 +2).toEqual(3); \n        }); \n    });\n\n//===============================demo\n//1.describe和it函数都有二个参数：\n//第一个参数：测试描述（一般使用英文，当然你使用中文也是完全没问题的）；\n//第二个参数：测试逻辑函数（具体干活的主）\n//2.expect方法用于表明你测试的预期，toEqual是它的子方法，表示是否等于你的预期。所以这句代码可以翻译为，1 + 2等于3，如果等于3，那么it函数块测试通过，it测试通过，那么describe也就测试通过。\n//3.it函数块可以包含多个expect过程，只要有其中的expect不符合期望，it就会测试不通过；而describe也可以包含多个it，只要有中有一个it报错，那么describe就会测试不通过。  新数据    新数据  //=========================demo\n    //建立个describe块\n    describe(\'JavaScript addition operator\',function(){ \n        //建立it块\n        it(\'adds two numbers together\',function(){ \n            //测试1+2是否等于3\n            expect(1 +2).toEqual(3); \n        }); \n    });\n\n//===============================demo\n//1.describe和it函数都有二个参数：describe是可以嵌套的\n//第一个参数：测试描述（一般使用英文，当然你使用中文也是完全没问题的）；\n//第二个参数：测试逻辑函数（具体干活的主）\n//2.expect方法用于表明你测试的预期，toEqual是它的子方法，表示是否等于你的预期。所以这句代码可以翻译为，1 + 2等于3，如果等于3，那么it函数块测试通过，it测试通过，那么describe也就测试通过。\n//3.it函数块可以包含多个expect过程，只要有其中的expect不符合期望，it就会测试不通过；而describe也可以包含多个it，只要有中有一个it报错，那么describe就会测试不通过。  新数据\n//==========================demo2\n\n    describe(\"Convert library\",function(){ \n        describe(\"distance converter\",function(){\n            });      \n        describe(\"volume converter\",function(){      \n        }); \n    });\n//=======================demo2', NULL, '2016-3-20 22:42:12', '2016-3-20 23:01:09', 0, 0);
INSERT INTO `demo` VALUES (407, 00000000405, 1, 0, 'js', '案列2', '关键词', '', '    varSelect =function(){\n    };\n    Select.prototype ={\n        show :function(){},//show、hide方法执行正确时返回true\n        hide :function(){},\n        change :function(){},\n        width :function(){}\n    }\n//单元测试写法：\n    describe(\'模拟选择框测试\',function(){\n        varselect =newSelect();\n        it(\'显示方法无误\',function(){ \n             expect(select.show()).toEqual(true); \n        });\n        it(\'隐藏方法无误\',function(){ \n             expect(select.hide()).toEqual(true); \n        });   \n    });\n\n', NULL, '2016-3-20 22:49:10', '2016-3-20 22:50:26', 0, 0);
INSERT INTO `demo` VALUES (408, 00000000405, 1, 0, 'html', '环境的配置', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <!-- 库文件 -->\n    <linkrel=\"stylesheet\"type=\"text/css\"href=\"spec/jasmine/jasmine.css\">\n    <script type=\"text/javascript\"src=\"spec/jasmine/jasmine.js\"></script>\n    <script type=\"text/javascript\"src=\"spec/jasmine/jasmine-html.js\"></script>\n    <!-- 待测试目标js文件 -->\n    <script type=\"text/javascript\"src=\"src/convert.js\"></script>\n    <!-- 单元测试文件 -->\n    <script type=\"text/javascript\"src=\"spec/convertSpec.js\"></script>\n</head>\n<body>\n    <script type=\"text/javascript\">\n    (function(){//环境初始化固定写法\n          varjasmineEnv =jasmine.getEnv();\n          jasmineEnv.updateInterval =1000;\n          vartrivialReporter =newjasmine.TrivialReporter();\n          jasmineEnv.addReporter(trivialReporter);\n          jasmineEnv.specFilter =function(spec){\n            returntrivialReporter.specFilter(spec);\n          };\n          varcurrentWindowOnload =window.onload;\n          window.onload =function(){\n            if(currentWindowOnload){\n              currentWindowOnload();\n            }\n            execJasmine();\n          };\n          functionexecJasmine(){\n            jasmineEnv.execute();\n          }\n        })();\n        //接下来你就可以自由的在convertSpec.js中书写单元测试代码。\n    </script>\n</body>\n</html>', NULL, '2016-3-20 22:52:37', '2016-3-20 22:58:52', 0, 0);
INSERT INTO `demo` VALUES (409, 00000000405, 1, 0, 'js', 'toThrow', '关键词', 'toThrow', '    it(\"throws an error when passed an unknown to-unit\",function(){\n        var testFn =function(){\n            Convert(1,\"cm\").to(\"furlongs\");\n        }\n        expect(testFn).toThrow(newError(\"unrecognized to-unit\"));\n    });', NULL, '2016-3-20 23:04:47', '2016-3-20 23:06:00', 0, 0);
INSERT INTO `demo` VALUES (410, 00000000405, 1, 0, 'js', 'toBe', '关键词', '', 'describe(\'PhoneCat controllers\', function() {\n  describe(\'PhoneListCtrl\', function(){\n    it(\'should create \"phones\" model with 3 phones\', function() {      var scope = {},\n      ctrl = new PhoneListCtrl(scope);\n      expect(scope.phones.length).toBe(3);\n    });\n  });\n});', NULL, '2016-3-20 23:06:09', '2016-3-20 23:06:27', 0, 0);
INSERT INTO `demo` VALUES (411, 00000000405, 1, 1, 'js', 'toBe', '关键词', '描述', '新代码', NULL, '2016-3-20 23:06:10', '2016-5-9 09:50:24', 0, 0);
INSERT INTO `demo` VALUES (412, 00000000174, 1, 0, 'js', '基本语法', '关键词', ' 新增不支持ie678', 'Array.forEach();\nArray.map();\nArray.filter();\nArray.some();\nArray.every();\nArray.indexOf();\nArray.lastIndexOf();\nArray.reduce();\nArray.reduceRight();\n---------------------------\nconcat();//     连接两个或更多的数组，并返回结果。\njoin();//     把数组的所有元素放入一个字符串。元素通过指定的分隔符进行分隔。\npop();//     删除并返回数组的最后一个元素\npush();//     向数组的末尾添加一个或更多元素，并返回新的长度。\nreverse();//     颠倒数组中元素的顺序。\nshift();//     删除并返回数组的第一个元素\nslice();//     从某个已有的数组返回选定的元素\nsort();//     对数组的元素进行排序\nsplice();//     删除元素，并向数组添加新元素。\ntoSource();//     返回该对象的源代码。\ntoString();//     把数组转换为字符串，并返回结果。\ntoLocaleString();//     把数组转换为本地数组，并返回结果。\nunshift();//     向数组的开头添加一个或更多元素，并返回新的长度。\nvalueOf();//     返回数组对象的原始值\n\nvar arr = new Array();  \narr[0] = \"aaa\";  \narr[1] = \"bbb\";  \narr[2] = \"ccc\";  \nalert(arr.length);      //3  \n\narr.pop();  \nalert(arr.length);      //2  \nalert(arr[arr.length-1]);   //bbb  \n\narr.pop();  \nalert(arr[arr.length-1]);   //aaa  \nalert(arr.length);      //1  \n\nvar arr2 = new Array();  \nalert(arr2.length);     //0  \n\narr2[0] = \"aaa\";  \narr2[1] = \"bbb\";  \nalert(arr2.length);     //2  \n\narr2.pop();  \nalert(arr2.length);     //1  \nalert(arr2[arr2.length-1]);     //aaa  \n\n/* \narrayObj.slice(start, [end])   \nslice 方法返回一个 Array 对象，其中包含了 arrayObj 的指定部分。  \nslice 方法一直复制到 end 所指定的元素，但是不包括该元素。如果 start 为负，将它作为 length + start处理，此处 length 为数组的长度。如果 end 为负，就将它作为 length + end 处理，此处 length 为数组的长度。如果省略 end ，那么 slice 方法将一直复制到 arrayObj 的结尾。 如果 end 出现在 start 之前，不复制任何元素到新数组中。  \n*/  \narr2 = arr2.slice(0, arr2.length-1);      \nalert(arr2.length);     //0  \narr2[0] = \"aaa\";  \narr2[1] = \"bbb\";  \narr2[2] = \"ccc\";  \narr2 = arr2.slice(0, 1);  \nalert(arr2.length);     //1  \nalert(arr2[0]);         //aaa  \nalert(arr2[1]);         //undefined  \n\n//shift：删除原数组第一项，并返回删除元素的值；如果数组为空则返回undefined  \nvar a = [1,2,3,4,5];  \nvar b = a.shift();  \nalert(a + \"; \" + b);    //a：[2,3,4,5]   b：1  \n\n//unshift：将参数添加到原数组开头，并返回数组的长度.注：在IE6.0下测试返回值总为undefined，FF2.0下测试返回值为7，所以这个方法的返回值不可靠，需要用返回值时可用splice代替本方法来使用。  \nvar a = [1,2,3,4,5];  \nvar b = a.unshift(-2,-1);  \nalert(a + \"; \" + b);    //a：[-2,-1,1,2,3,4,5]   b：7  \n\n//pop：删除原数组最后一项，并返回删除元素的值；如果数组为空则返回undefined  \nvar a = [1,2,3,4,5];  \nvar b = a.pop();   \nalert(a + \"; \" + b);    //a：[1,2,3,4]   b：5  \n\n//push：将参数添加到原数组末尾，并返回数组的长度  \nvar a = [1,2,3,4,5];  \nvar b = a.push(6,7);   \nalert(a + \"; \" + b);    //a：[1,2,3,4,5,6,7]   b：7  \n\n//concat：返回一个新数组，是将参数添加到原数组中构成的  \nvar a = [1,2,3,4,5];  \nvar b = a.concat(6,7);   \nalert(a + \"; \" + b);    //a：[1,2,3,4,5]   b：[1,2,3,4,5,6,7]  \n\n//splice(start,deleteCount,val1,val2,...)：从start位置开始删除deleteCount项，并从该位置起插入val1,val2,..., 返回的是删除项数组  \n//在清空数组时，只需传递startIndex; 如果不删除所有元素，再传递deleteCount参数。  \n//splice还具有先删除后添加的功能，即先删除几个元素，然后在删除的位置再添加若干元素，删除与添加的元素的个数没有必须相等，这时侯deleteCount也是要用到的。  \nvar a = [1,2,3,4,5];  \nvar b = a.splice(2,2,7,8,9);    // 从下标2处开始，删除2量，并从2位置增加三项（7，8，9）  \nalert(a + \"; \" + b);    //a：[1,2,7,8,9,5]   b：[3,4]  \n\nvar b = a.splice(0,1); //同shift  \nalert(a + \"; \" + b);    //a：[2,7,8,9,5]   b：[1]  \n\nvar a = [1,2,3,4,5];  \na.splice(0,0,-2,-1);   \nvar b = a.length;   //同unshift  \nalert(a + \"; \" + b);    //a：[-2,-1,1,2,3,4,5]   b：[7]  \n\nvar b = a.splice(a.length-1,1);//同pop  \nalert(a + \"; \" + b);    //a：[-2,-1,1,2,3,4]   b：[5]  \n\na.splice(a.length,0,6,7);   \nvar b = a.length; //同push  \nalert(a + \"; \" + b);    //a：[-2,-1,1,2,3,4,6,7]   b：[8]  \n\n//reverse：将数组反序  \nvar a = [1,2,3,4,5];  \nvar b = a.reverse();   \nalert(a + \"; \" + b);    //a：[5,4,3,2,1]   b：[5,4,3,2,1]  \n\n//sort(orderfunction)：按指定的参数对数组进行排序  \nvar a = [1,4,3,2,5];  \nvar b = a.sort();   \nalert(a + \"; \" + b);    //a：[1,2,3,4,5]   b：[1,2,3,4,5]  \n\n//slice(start,end)：返回从原数组中指定开始下标到结束下标之间的项组成的新数组  \nvar a = [1,2,3,4,5];  \nvar b = a.slice(2,5);   \nalert(a + \"; \" + b);    //a：[1,2,3,4,5]   b：[3,4,5]  \n\n//join(separator)：将数组的元素组起一个字符串，以separator为分隔符，省略的话则用默认用逗号为分隔符  \nvar a = [1,2,3,4,5];  \nvar b = a.join(\"|\");   \nalert(a + \"; \" + b);    //a：[1,2,3,4,5]   b：\"1|2|3|4|5\"  \nvar b2 = a.join();   \nalert(a + \"; \" + b2);   //a：[1,2,3,4,5]   b：\"1,2,3,4,5\"  \n\n// 字符串处理函数  \nfunction StringBuffer() {  \n    var arr = new Array;  \n    this.append = function(str) {  \n        arr[arr.length] = str;  \n        return this;  \n    };  \n\n    this.toString = function() {  \n        return arr.join(\"|\");   //把append进来的数组ping成一个字符串  \n    };  \n}  \n\nvar strBuf = new StringBuffer();  \nstrBuf.append(\"1\").append(\"2\").append(\"3\"); // strBuf.append(arg)  \nstrBuf.append(\"4\");   \nstrBuf.append(\"5\");   \nalert(strBuf.append(\"6\").append(\"7\").append(\"8\").toString());           // 1|2|3|4|5|6|7|8  \n\n// 把数组转换成特定符号分割的字符串  \nfunction arrayToString(arr, separator) {  \n    if(!separator)   \n        separator = \"\";     //separator为null则默认为空  \n    return arr.join(separator);  \n}  \nvar arr = new Array(1, 3, 5);  \nalert(arrayToString(arr, \"=\"));     // 1=3=5  \n\n// 查找数组包含的字符串  \nfunction arrayFindString(arr, string) {  \n    var str = arr.join(\"\");  \n    return str.indexOf(string);  \n}  \nvar arr = new Array(1, 3, 5);  \nalert(arrayFindString(arr, 3));     // 1  ', NULL, '2016-3-20 23:30:49', '2016-5-1 23:57:49', 0, 0);
INSERT INTO `demo` VALUES (413, 00000000163, 1, 0, 'js', 'js所有数据类型', '关键词', 'unfined, null, bool, number, string, object 和 function', '新数据', NULL, '2016-3-20 23:38:43', '2016-3-20 23:38:50', 0, 0);
INSERT INTO `demo` VALUES (414, 00000000349, 1, 0, 'js', 'path', '关键词', '', 'M = moveto(M X,Y) ：将画笔移动到指定的坐标位置\nL = lineto(L X,Y) ：画直线到指定的坐标位置\nH = horizontal lineto(H X)：画水平线到指定的X坐标位置\nV = vertical lineto(V Y)：画垂直线到指定的Y坐标位置\nA = elliptical Arc(A RX,RY,XROTATION,FLAG1,FLAG2,X,Y)：弧线\nZ = closepath()：关闭路径\n不常用：\nC = curveto(C X1,Y1,X2,Y2,ENDX,ENDY)：三次贝赛曲线\nS = smooth curveto(S X2,Y2,ENDX,ENDY)\nQ = quadratic Belzier curve(Q X,Y,ENDX,ENDY)：二次贝赛曲线\nT = smooth quadratic Belzier curveto(T ENDX,ENDY)：映射\n\n1.弧线：画一段弧线，再画一个直线，然后使用z来闭合路径回到远点，使用class来填充颜色，ok扇形出来了\n<path d=\"M143.93398282201787 356.0660171779821 A150.0 150.0 , 0, 0,\n1,101.84674891072936 226.53483024396536 L250 250, Z\" class=\"fill1\"/>', NULL, '2016-3-20 23:52:21', '2016-3-20 23:58:49', 0, 0);
INSERT INTO `demo` VALUES (415, 00000000240, 1, 0, 'js', '常用js语法', '关键词', '', '1.输出语句：document.write(\"\");\n2.JS中的注释为//\n3.传统的HTML文档顺序是:document->html->(head,body)\n4.一个浏览器窗口中的DOM顺序是:window->(navigator,screen,history,location,document)\n5.得到表单中元素的名称和值:document.getElementById(\"表单中元素的ID号\").name(或value)\n6.一个小写转大写的JS: document.getElementById(\"output\").value = document.getElementById(\"input\").value.toUpperCase();\n7.JS中的值类型:String,Number,Boolean,Null,Object,Function\n8.JS中的字符型转换成数值型:parseInt(),parseFloat()\n9.JS中的数字转换成字符型:(\"\"+变量)\n10.JS中的取字符串长度是:(length)\n11.JS中的字符与字符相连接使用+号.\n12.JS中的比较操作符有:==等于,!=不等于,>,>=,<.<=\n13.JS中声明变量使用:var来进行声明\n14.JS中的判断语句结构:if(condition){}else{}\n15.JS中的循环结构:for([initial e­xPRession];[condition];[upadte e­xpression]) {inside loop}\n16.循环中止的命令是:break\n17.JS中的函数定义:function functionName([parameter],...){statement[s]}\n18.当文件中出现多个form表单时.可以用document.forms[0],document.forms[1]来代替.\n19.窗口:打开窗口window.open(), 关闭一个窗口:window.close(), 窗口本身:self\n20.状态栏的设置:window.status=\"字符\";\n21.弹出提示信息:window.alert(\"字符\");\n22.弹出确认框:window.confirm();\n23.弹出输入提示框:window.prompt();\n24.指定当前显示链接的位置:window.location.href=\"URL\"\n25.取出窗体中的所有表单的数量:document.forms.length\n26.关闭文档的输出流:document.close();\n27.字符串追加连接符:+=\n28.创建一个文档元素:document.createElement(),document.createTextNode()\n29.得到元素的方法:document.getElementById()\n30.设置表单中所有文本型的成员的值为空:\n\nvar form = window.document.forms[0]\nfor (var i = 0; i<form.elements.length;i++){\n     if (form.elements[i].type == \"text\"){\n         form.elements[i].value = \"\";\n     }\n}\n\n\n31.复选按钮在JS中判断是否选中:document.forms[0].checkThis.checked (checked属性代表为是否选中返回TRUE或FALSE)\n32.单选按钮组(单选按钮的名称必须相同):取单选按钮组的长度document.forms[0].groupName.length\n33.单选按钮组判断是否被选中也是用checked.\n34.下拉列表框的值:document.forms[0].selectName.options[n].value (n有时用下拉列表框名称加上.selectedIndex来确定被选中的值)\n35.字符串的定义:var myString = new String(\"This is lightsWord\");\n36.字符串转成大写:string.toUpperCase(); 字符串转成小写:string.toLowerCase();\n37.返回字符串2在字符串1中出现的位置:String1.indexOf(\"String2\")!=-1则说明没找到.\n38.取字符串中指定位置的一个字符:StringA.charAt(9);\n39.取出字符串中指定起点和终点的子字符串:stringA.substring(2,6);\n40.数学函数:Math.PI(返回圆周率),Math.SQRT2(返回开方),Math.max(value1,value2)返回两个数中的最在值,Math.pow(value1,10)返回value1的十次方,Math.round(value1)四舍五入函数,Math.floor(Math.random()*(n+1))返回随机数\n41.定义日期型变量:var today = new Date();\n42.日期函数列表:\ndateObj.getTime()得到时间,\ndateObj.getYear()得到年份,\ndateObj.getFullYear()得到四位的年份,\ndateObj.getMonth()得到月份,\ndateObj.getDate()得到日,\ndateObj.getDay()得到日期几,\ndateObj.getHours()得到小时,\ndateObj.getMinutes()得到分,\ndateObj.getSeconds()得到秒,\ndateObj.setTime(value)设置时间,\ndateObj.setYear(val)设置年,\ndateObj.setMonth(val)设置月,\ndateObj.setDate(val)设置日,\ndateObj.setDay(val)设置星期几,\ndateObj.setHours设置小时,\ndateObj.setMinutes(val)设置分,\ndateObj.setSeconds(val)设置秒 [注意:此日期时间从0开始计]\n43.FRAME的表示方式:\n[window.]frames[n].ObjFuncVarName,frames[\"frameName\"].ObjFuncVarName,frameName.ObjFuncVarName\n44.parent代表父亲对象,top代表最顶端对象\n45.打开子窗口的父窗口为:opener\n46.表示当前所属的位置:this\n47.当在超链接中调用JS函数时用:(javascript:)来开头后面加函数名\n48.在老的浏览器中不执行此JS:<!--      //-->\n49.引用一个文件式的JS:<script type=\"text/Javascript\" src=\"aaa.js\"></script>\n50.指定在不支持脚本的浏览器显示的HTML:<noscript></noscript>\n51.当超链和ONCLICK事件都有时,则老版本的浏览器转向a.html,否则转向b.html.例:<a href=\"a.html\" onclick=\"location.href=\'b.html\';return false\">dfsadf</a>\n52.JS的内建对象有:Array,Boolean,Date,Error,EvalError,Function,Math,Number,Object,RangeError,ReferenceError,RegExp,String,SyntaxError,TypeError,URIError\n53.JS中的换行:\\n\n54.窗口全屏大小:\n<script>function fullScreen(){ this.moveTo(0,0);this.outerWidth=screen.availWidth;this.outerHeight=screen.availHeight;}window.maximize=fullScreen;</script>\n55.JS中的all代表其下层的全部元素http://bizhi.knowsky.com/\n56.JS中的焦点顺序:document.getElementByid(\"表单元素\").tabIndex = 1\n57.innerHTML的值是表单元素的值:如<p id=\"para\">\"how are <em>you</em>\"</p>,则innerHTML的值就是:how are <em>you</em>\n58.innerTEXT的值和上面的一样,只不过不会把<em>这种标记显示出来.\n59.contentEditable可设置元素是否可被修改,isContentEditable返回是否可修改的状态.\n60.isDisabled判断是否为禁止状态.disabled设置禁止状态\n61.length取得长度,返回整型数值\n62.addBehavior()是一种JS调用的外部函数文件其扩展名为.htc\n63.window.focus()使当前的窗口在所有窗口之前.\n64.blur()指失去焦点.与FOCUS()相反.\n65.select()指元素为选中状态.\n66.防止用户对文本框中输入文本:onfocus=\"this.blur()\"\n67.取出该元素在页面中出现的数量:document.all.tags(\"div(或其它HTML标记符)\").length\n68.JS中分为两种窗体输出:模态和非模态.window.showModaldialog(),window.showModeless()\n69.状态栏文字的设置:window.status=\'文字\',默认的状态栏文字设置:window.defaultStatus = \'文字.\';\n70.添加到收藏夹:external.AddFavorite(\"http://www.xrss.cn\",\"jaskdlf\");\n71.JS中遇到脚本错误时不做任何操作:window.onerror = doNothing; 指定错误句柄的语法为:window.onerror = handleError;\n72.JS中指定当前打开窗口的父窗口:window.opener,支持opener.opener...的多重继续.\n73.JS中的self指的是当前的窗口\n74.JS中状态栏显示内容:window.status=\"内容\"\n75.JS中的top指的是框架集中最顶层的框架\n76.JS中关闭当前的窗口:window.close();\n77.JS中提出是否确认的框:if(confirm(\"Are you sure?\")){alert(\"ok\");}else{alert(\"Not Ok\");}\n78.JS中的窗口重定向:window.navigate(\"http://www.sina.com.cn\");\n79.JS中的打印:window.print()\n80.JS中的提示输入框:window.prompt(\"message\",\"defaultReply\");\n81.JS中的窗口滚动条:window.scroll(x,y)\n82.JS中的窗口滚动到位置:window.scrollby\n83.JS中设置时间间隔:setInterval(\"expr\",msecDelay)或setInterval(funcRef,msecDelay)或setTimeout\n84.JS中的模态显示在IE4+行,在NN中不行:showModalDialog(\"URL\"[,arguments][,features]);\n85.JS中的退出之前使用的句柄:function verifyClose(){event.returnValue=\"we really like you and hope you will stay longer.\";}} window.onbeforeunload=verifyClose;\n86.当窗体第一次调用时使用的文件句柄:onload()\n87.当窗体关闭时调用的文件句柄:onunload()\n88.window.location的属性: protocol(http:),hostname(www.example.com),port(80),host(www.example.com:80),pathname(\"/a/a.html\"),hash(\"#giantGizmo\",指跳转到相应的锚记),href(全部的信息)\n89.window.location.reload()刷新当前页面.\n89-1.parent.location.reload()刷新父亲对象（用于框架）\n89-2.opener.location.reload()刷新父窗口对象（用于单开窗口）\n89-3.top.location.reload()刷新最顶端对象（用于多开窗口）\n90.window.history.back()返回上一页,window.history.forward()返回下一页,window.history.go(返回第几页,也可以使用访问过的URL)\n91.document.write()不换行的输出,document.writeln()换行输出\n92.document.body.noWrap=true;防止链接文字折行.\n93.变量名.charAt(第几位),取该变量的第几位的字符.\n94.\"abc\".charCodeAt(第几个),返回第几个字符的ASCii码值.\n95.字符串连接:string.concat(string2),或用+=进行连接\n96.变量.indexOf(\"字符\",起始位置),返回第一个出现的位置(从0开始计算)\n97.string.lastIndexOf(searchString[,startIndex])最后一次出现的位置.\n98.string.match(regExpression),判断字符是否匹配.\n99.string.replace(regExpression,replaceString)替换现有字符串.\n100.string.split(分隔符)返回一个数组存储值.\n101.string.substr(start[,length])取从第几位到指定长度的字符串.\n102.string.toLowerCase()使字符串全部变为小写.\n103.string.toUpperCase()使全部字符变为大写.\n104.parseInt(string[,radix(代表进制)])强制转换成整型.\n105.parseFloat(string[,radix])强制转换成浮点型.\n106.isNaN(变量):测试是否为数值型.\n107.定义常量的关键字:const,定义变量的关键字:var', NULL, '2016-3-21 00:13:47', '2016-3-21 00:14:00', 0, 0);
INSERT INTO `demo` VALUES (416, 00000000292, 1, 0, 'js', '$timeout', '关键词', 'timeout的用法是会自动触发$digest，如果不用这个服务需要自己写$scope.apply()函数来触发,同时这个函数的第三个参数如果设置false，可以不触发$digest循环', '$http.get(\'http://path/to/url\').success(function(data){\n  $scope.name = data.name;\n  $timeout(function(){\n    //do sth later, such as log\n  }, 0, false);\n});', NULL, '2016-3-21 16:56:44', '2016-3-21 16:58:55', 0, 0);
INSERT INTO `demo` VALUES (417, 00000000292, 1, 0, 'html', '$compile服务', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myapp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body ng-controller=\"mycontroller\" id=\"mybody\" >\n<div id=\"innerdiv\">\n    <input type=\"button\" ng-click=\"refreshDom()\" value=\"执行动态编译\" id=\"mybtn\"/>\n    <input type=\"button\"  value=\"生成动态标签\" ng-click=\"addDirective()\">\n    <mydiv>队长，是我</mydiv>{{name}}\n</div>\n<script>\n    var app = angular.module(\"myapp\",[]);\n    app.controller(\'mycontroller\', function($scope,$compile){\n        $scope.name=\"小王\";//定义一个变量，动态解析这个变量\n        $scope.refreshDom=function(){\n            $compile(document.getElementById(\"mybody\"))($scope);\n            //测试通过，而且任何元素不要用firebug动态碰触，碰触后拾取其angular链接，造成无法测试\n        };\n        $scope.addDirective=function(){\n            angular.element(document.getElementById(\"mybtn\")).after(\"{{name}}\");\n\n        }\n    }).directive(\"mydiv\",function(){//定义一个指令，动态解析指令\n        return {\n            restrict:\"E\",\n            template:\"<div>okok:<span></span></div>\",\n            replace:true\n        }\n    });\n</script>\n<!-- 动态添加这些未解析的元素到容器<mydiv>霍元甲</mydiv>{{name}} -->\n</body>\n</html>\n例2\n<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myapp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"jquery.js\"></script>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body ng-controller =\"mycontroller as ctrl\">\n<div ng-click=\"ctrl.btn_click($event)\">123456</div>\n<testdiv></testdiv>\n<script>\nvar app = angular.module(\"myapp\",[]);\n    app.directive(\"testdiv\",function(){\n        return {\n            restrict:\"EA\",\n            template:\"<span>hi</span><span>hi</span><span>hi</span><span>hi</span>\"\n        }\n    });\n    app.controller(\"mycontroller\",function($scope,$compile,testcompile){\n        console.log(\"76543\");\n        // this.btn_click = function(e){\n        //     console.log($(e.currentTarget).html($compile(\"<testdiv></testdiv>\")($scope)));\n        // }\n        this.btn_click = testcompile.btn_click;\n    });\n    app.service(\'testcompile\', [\'$compile\', function($compile){\n        this.btn_click=function(e){\n            $(e.currentTarget).html($compile(\"<testdiv></testdiv>\")(this))\n        }\n    }])\n</script>\n</body>\n</html>\n', NULL, '2016-3-21 18:42:49', '2016-4-28 10:07:35', 0, 0);
INSERT INTO `demo` VALUES (418, 00000000398, 1, 0, 'html', '同级指令之间的通讯', '关键词', '指令写在dom中的同一个controller下面，同事指令声明的时候，双向绑定一个变量，此变量作为属性写入dom中指令中去，之后就可以一起共享controller中的同名变量，互相控制了！', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body ng-controller=\"demo\">\n  <h3>同级指令间通信</h3>\n  <button ng-click=\"clickFn()\">点我</button>\n  {{isSelect}}\n  <sibling-a is-select=\"isSelect\"></sibling-a>\n  <sibling-b is-select=\"isSelect\"></sibling-b>\n  <script>\nvar app = angular.module(\'app\', []);\n\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n\napp.controller(\'demo\', function($scope){\n  $scope.isSelect = false;\n  $scope.clickFn = function(){\n    $scope.isSelect = !$scope.isSelect;\n  };\n});\n\napp.directive(\'siblingA\', function() {\n  return {\n    restrict: \'EA\',\n    replace: true,\n    scope : {\n      isSelect: \'=\'  \n    },\n//     scope: true,\n    template: \'<p><button ng-click=\"clickFn()\">点我</button>{{isSelect}}</p></div>\',\n    link: function($scope){\n//       $scope.isSelect = true;\n      $scope.clickFn = function(){\n        $scope.isSelect = !$scope.isSelect;\n      };\n    }\n  };\n});\n\napp.directive(\'siblingB\', function() {\n  return {\n    restrict: \'EA\',\n    replace: true,\n    scope : {\n      isSelect: \'=\'  \n    },\n//     scope: true,\n    template: \'<p><button ng-click=\"clickFn()\">点我</button>{{isSelect}}</p></div>\',\n    link: function($scope){\n//       $scope.isSelect = false;\n      $scope.clickFn = function(){\n        $scope.isSelect = !$scope.isSelect;\n      };\n    }\n  };\n});\n  </script>\n</body>\n</html>', NULL, '2016-3-22 17:27:39', '2016-3-22 17:30:56', 0, 0);
INSERT INTO `demo` VALUES (419, 00000000398, 1, 0, 'html', '父子指令通讯', '关键词', '在设置scope为true，并且设置玩require之后，link的第四的属性将会变成父指令的controller', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n  <div>\n     <h3>require实现父子级指令间通信</h3>\n    <p>指令外isSelect{{isSelect}}是不存在的</p>\n    <superset>\n      <p>指令内：{{isSelect}}</p>\n      <subset-a></subset-a>\n      <subset-b></subset-b>\n    </superset> \n  </div>\n  <script>\n  var app = angular.module(\'app\', []);\n\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n\napp.directive(\'superset\', function() {\n  return {\n    restrict: \'EA\',\n    replace: true,\n    scope: true,\n    controller: function($scope){\n      $scope.isSelect = true;\n      var ctrl = this;\n      ctrl.clickFnA = function(){\n          $scope.isSelect = !$scope.isSelect;\n      }; \n      ctrl.clickFnB = function(){\n          $scope.isSelect = !$scope.isSelect;\n      }; \n    }\n  };\n});\n\napp.directive(\'subsetA\', function() {\n  return {\n    restrict: \'EA\',\n    replace: true,\n    require: \'^?superset\',\n    scope: true,\n    template: \'<p><button ng-click=\"clickFnA()\">点我</button>  {{isSelect}}</p></div>\',\n    link: function($scope, tElement, tAttrs, ctrl){\n      $scope.clickFnA = ctrl.clickFnA;\n    }\n  };\n});\n\napp.directive(\'subsetB\', function() {\n  return {\n    restrict: \'EA\',\n    replace: true,\n    require: \'^?superset\',\n    scope: true,\n    template: \'<p><button ng-click=\"clickFnB()\">点我 </button> {{isSelect}}</p>\',\n    link: function($scope, tElement, tAttrs, ctrl){\n      $scope.clickFnB = ctrl.clickFnB;\n    }\n  };\n});\n  </script>\n</body>\n</html>', NULL, '2016-3-22 17:31:15', '2016-3-22 17:35:57', 0, 0);
INSERT INTO `demo` VALUES (420, 00000000291, 1, 0, 'js', '通讯', '关键词', '描述', '新代码', NULL, '2016-3-22 17:42:10', '2016-3-22 17:42:10', 0, 0);
INSERT INTO `demo` VALUES (421, 00000000420, 1, 0, 'html', 'controller的父子继承通讯', '关键词', '1.只要设置变量为引用传递就完全link了\n2.如果设置了值传递，父亲改变的时候，如果子没有值，子的值将会变动，但是如果已经赋值，将不受影响\n3.值传递，任何时候都不会影响到父变量的变化，', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<div ng-controller=\"parent\">\n    <p>引用类型:{{obj._value}} </p>\n    <p>基本类型:{{_value}} </p>\n    <button ng-click=\"change_a(\'parent\')\">点我</button>\n    <div ng-controller=\"child\">\n        <p>引用类型:{{obj._value}} </p>\n        <p>基本类型:{{_value}} </p>\n        <button ng-click=\"change_b(\'child\')\">点我</button>\n    </div>\n</div>\n<script>\nvar app = angular.module(\'app\', []);\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n\napp.controller(\"parent\",function($scope){\n  $scope._value = \'default\';\n  $scope.obj = {};\n  $scope.obj._value = \'default\';\n    $scope.change_a = function(newValue) {\n        $scope.obj._value = newValue;\n        $scope._value = newValue;\n    };\n});\n\napp.controller(\"child\",function($scope){\n  $scope.change_b = function(newValue) {\n        $scope.obj._value = newValue;\n        $scope._value = newValue;\n    };\n});\n</script>\n</body>\n</html>', NULL, '2016-3-22 17:42:19', '2016-3-22 18:08:33', 0, 0);
INSERT INTO `demo` VALUES (422, 00000000420, 1, 0, 'html', 'controller的父子emit通讯', '关键词', '两个controller都要写接口，注意接收方的第一个参数是event，不是实际传递的内容', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<div ng-controller=\"parent\">\n    <p>parent: {{sports}}</p>\n    <div ng-controller=\"child\">\n        <p>child: <button ng-click=\"pass()\">老爹接住</button></p>\n    </div>\n    <script>\nvar app = angular.module(\'app\', []);\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n// 父scope上的控制器\napp.controller(\"parent\",function($scope) {\n    $scope.sports = \'Pass me\';\n    $scope.$on(\'pass\', function(e, newLocation) {\n        $scope.sports = newLocation;\n    });\n});\n// 子scope上的控制器\napp.controller(\"child\",function($scope) {\n    $scope.sports = \'well done\';\n    $scope.pass = function() {\n        $scope.$emit(\'pass\', $scope.sports);\n    };\n});\n    </script>\n</div>\n</body>\n</html>', NULL, '2016-3-22 17:59:20', '2016-3-22 18:01:03', 0, 0);
INSERT INTO `demo` VALUES (423, 00000000420, 1, 0, 'html', 'controller的父子broadcast通讯', '关键词', '父子都要写接口，同样第一个参数不是实际内容，他们传递的消息都有一个命名，做什么的尚不得而知。', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<div ng-controller=\"Sandcrawler\">\n    <p>parent: {{sports}}</p>\n    <button ng-click=\"recall()\">儿子接球</button>\n    <div ng-controller=\"Droid\">\n        <p>child: {{sports}}</p>\n    </div>\n</div>\n<script>\nvar app = angular.module(\'app\', []);\n\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n// 父scope上的控制器\napp.controller(\"Sandcrawler\",function($scope) {\n    $scope.recall = function() {\n      $scope.sports = \'good！！！\';\n      $scope.$broadcast(\'recall\', $scope.sports);\n    };\n});\n// 子scope上的控制器\napp.controller(\"Droid\",function($scope) {\n    $scope.$on(\'bus\', function(e, newLocation) {\n        $scope.sports = newLocation;\n    });\n});\n</script>\n</body>\n</html>', NULL, '2016-3-22 18:01:25', '2016-3-22 18:05:01', 0, 0);
INSERT INTO `demo` VALUES (424, 00000000420, 1, 0, 'html', 'controller通过服务通讯', '关键词', '首先写一个服务，返回一个空对象即可，然后分别注入controller中去，大家一起操作这个服务就可以了！服务是公用的对象了！', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n<h3>通过 angular 服务实现控制器通信</h3>\n<div ng-controller=\"MainCtrl\">\n     <input type=\"text\" ng-model=\"text\" />\n     <button ng-click=\"change()\">先点我</button>\n</div>\n<div ng-controller=\"sideCtrl\">\n    <button ng-click=\"add()\">点过上面的再点我</button>\n    <p>{{name}}</p>\n    <script>\nvar app = angular.module(\'app\', []);\nangular.element(document).ready(function readyHandler() {\n    angular.bootstrap(document, [\'app\']);\n});\n\napp.factory(\'instance\', function(){\n    return {};\n});\n\napp.controller(\'MainCtrl\', function($scope, instance) {\n  $scope.change = function() {\n       instance.name = $scope.text;\n  };\n});\napp.controller(\'sideCtrl\', function($scope, instance) {\n    $scope.add = function() {\n        $scope.name = instance.name;\n    };\n});\n    </script>\n</div>\n</body>\n</html>', NULL, '2016-3-22 18:08:50', '2016-3-22 18:09:51', 0, 0);
INSERT INTO `demo` VALUES (425, 00000000365, 1, 0, 'js', 'history新增方法', '关键词', '', '// 一直以来对 window.history 不是很了解，直到听说 pjax 。此技术利用 history 新增的几个方法，实现了ajax长久以来的一直存在的问题，刷新页面就不是之前看到的页面了和不能使用浏览器的前进后退功能。所以搜索+摘抄window.history相关知识点。\n// HTML5之前的 window.history\n\n// 在HTML5之前的 window.history之前，window.history 有一个属性，三个对象，如下列表：\n\n    length//浏览器当前标签页浏览页面的数量，载入页面后 length==1\n    back() //相当于浏览器 后退 键\n    forward()//相当于浏览器 前进 键\n    go(num)//num < 0，则后退 num 个地址；num > 0，则前进 num 个地址；num == 0，则刷新当前页。\n\n// ps：可以使用history.go(0)来刷新页面，跟 location.reload()效果类似，相当于按下 F5;而location.replace(location.href) 则是替换当前访问的页面，相当于 ctrl + F5。\n// HTML5 中 window.history 新增的方法\n\n// HTML5 扩展了window.history，我们可以存储当前和替换当前历史记录点、监听历史记录变换。如下：\n\n//     ：往历史记录堆栈顶部添加一条记录；data会在onpopstate事件触发时作为参数传递过去；title为页面标题，当前所有浏览器都会忽略此参数；url为页面地址，可选，缺省为当前页地址。\n//     ：更改当前的历史记录，参数同上。\n//     ：用于存储以上方法的data数据，不同浏览器的读写权限不一样。\n\n    history.pushState(data, title [, url])：操作跟数组的push()方法（入栈），往window.history里推入一个历史记录点\n    window.history.pushState({time:new Date().getTime()},\"not work\",url);\n    // 第一个参数：存放当前历史记录的对象，如果为空，则在监听历史记录， onpopstate 事件下无访问的数据；\n\n    // 第二个参数：页面标题，目前貌似浏览器都不支持\n\n    // 第三个参数：url为页面地址，默认是当前页地址，必须同域。\n    history.replaceState(data, title [, url])：参数跟pushState()一样，不同的是此方法 替换了当前的历史记录。\n    history.state：用于存储以上方法的存入的数据对象。\n    // 利用以上知识点，做了简易pjax页面。注意点如下几点：\n    // 除了刷新行为使用 replaceState 操作历史记录，其他用户行为都该使用 pushState 。不理解的，自己去打开其他页面，返回、前进、刷新，体会一下。\n    // 现在这两个方法的第二参数浏览器都不支持，参数为空但不能不要次参数。暂且使用 document.title 操作标题。\n    // 存放当前历史记录的对象不能为空，否则操作历史记录前进、返回，history.state 则没有数据。页面可能无变化', NULL, '2016-3-22 18:17:31', '2016-3-22 18:19:09', 0, 0);
INSERT INTO `demo` VALUES (426, 00000000292, 1, 0, 'js', 'ngModelController详解', '关键词', '后面一个案例，require:ngModel实现了一个双向绑定的指令，其中主要用到了ngModel.viewValue和ngMedel.setViewValue这个属性方法，其中取值后自己封装成了render函数来向表现层view输出，而setviewvalue封装成read方法来向数据model输出。', '//1.方法\n$render();//当视图需要更新的时候会被调用。使用ng-model的指令应该自行实现这个方法。\n$isEmpty(value);//该方法用于判断输入值是否为空。可用来判断值是否为undefined,\'\',null或者NaN,你可以根据自己的需要重载该方法。\n$setValidity(validationErrorKey, isValid);//该方法用于改变验证状态，以及在控制变化的验证标准时通知表格。这个方法应该由一个验证器来调用。例如，一个解析器或者格式化函数。\n$setPristine();//该方法用于设置控制到原始状态。该方法可以移除\'ng-dirty\'类并将控制恢复到原始状态(\'ng-pristine\'类)。\n$cancelUpdate();//该方法用于取消一次更新并重置输入元素的值以防止$viewCalue发生更新\n$setViewValue(value, trigger)//该方法用来更新视图值。这个方法应该在一个视图值发生变化时被调用，一般来说是在一个DOM事件处理函数中。例如，input和select指令就调用了这个函数。这个方法将会更新$viewValue属性，然后在$pasers中通将这个值传递给每一个函数，其中包括了验证器。这个值从$parsers输出后，将会被用于$modelValue以及ng-model属性中的表达式。最后，所有位于$viewChangeListeners列表中注册的监听器将会被调用。\n//2.属性\n$viewValue//视图中的实际值\n$modelValue//model中的值，它金额控制器绑定在一起\n$parsers//将要执行的函数的数组，无论什么时候控制器从DOM中读取了一个值，它都将作为一个管道。其中的函数依次被调用，并将结果传递给下一个。最后出来的值将会被传递到model中。其中将包括验证和转换值的过程。对于验证步骤，这个解析器将会使用$setValidity方法，对于不合格的值将返回undefined。\n$formatters//一个包含即将执行函数的数组，无论什么时候model的值发生了变化，它都会作为一个管道。其中的每一个函数都被依次调用，并将结果传递给下一个函数。该函数用于将模型传递给视图的值进行格式化。\n$viewChangeListeners//只要视图的值发生变化，其中的函数就会被执行。其中的函数执行并不带参数，它的返回值也会被忽略。它可以被用在额外的#watches中。\n$error//一个包含所有error的对象\n$pristine//如果用户还没有进行过交互,值是true。\n$dirty//如果用户已经进行过交互，值是true。\n$valid//如果没有错误，值是true。\n$invalid//如果有错误，值是true。\n//======================demo \n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body>\n    <form name=\"myForm\">\n     <div contenteditable\n      name=\"myWidget\" ng-model=\"userContent\"\n      strip-br=\"true\"\n      required>Change me!</div>\n      <span ng-show=\"myForm.myWidget.$error.required\">Required!</span>\n     <hr>\n     <textarea ng-model=\"userContent\"></textarea>\n    </form>\n    <script>\n        angular.element(document).ready(function(){\n            angular.bootstrap(document,[\"customControl\"]);\n        });\n        angular.module(\'customControl\', []). directive(\'contenteditable\', function() {\n            return {\n                restrict: \'A\', // 作为元素属性\n                require: \'?ngModel\', // 获取ngModelController\n                link: function(scope, element, attrs, ngModel) {//ng.model是数据模型\n                    if(!ngModel) return;\n                    ngModel.$render = function() {\n                        element.html(ngModel.$viewValue || \'\');//直接把html设置为模型的值\n                    };\n                    // 监听change事件来开启绑定\n                    element.on(\'blur keyup change\', function() {\n                        scope.$apply(read);\n                    });\n                    read(); // 初始化\n                    // 将数据写入model\n                    function read() {\n                        var html = element.html();//1.获取元素的值\n                        // 当我们清空div时浏览器会留下一个<br>标签\n                        // 如果制定了strip-br属性，那么<br>标签会被清空\n                        if( attrs.stripBr && html == \'<br>\' ) {\n                        html = \'\';\n                        }\n                        ngModel.$setViewValue(html);//2.复制到数据模型中去\n                    }\n                }\n            };\n        });\n    </script>\n</body>\n</html>\n', NULL, '2016-3-23 11:18:23', '2016-3-23 15:35:49', 0, 0);
INSERT INTO `demo` VALUES (427, 00000000292, 1, 0, 'js', 'directive中require的用法', '关键词', '重复的方法写在第三个指令的controller中，然后在另外两个需要的指令中require这个拥有controller字段的指令，最后通过linking函数的第四个参数就可以引用这些重合的方法。', 'var app = angular.modeule(\'myapp\',[]);\napp.directive(\'common\',function(){\n    return {\n    // ...\n    controller: function($scope){\n        this.method1 = function(){\n        };\n        this.method2 = function(){\n        };\n    },\n    // ...\n    }\n});\napp.directive(\'d1\',function(){\n    return {\n    // ...\n    require: \'?^common\',\n    link: function(scope,elem,attrs,common){\n        scope.method1 = common.method1;\n        //..\n        },\n    // ...\n    }\n});\napp.directive(\'d2\',function(){\n    return {\n    // ...\n    require: \'?^common\',\n    link: function(scope,elem,attrs,common){\n        scope.method1 = common.method1;\n        //..\n        },\n    // ...\n    }\n});', NULL, '2016-3-23 11:36:26', '2016-3-23 11:37:48', 0, 0);
