INSERT INTO `demo` VALUES (430, 00000000429, 1, 0, 'js', 'Git', '关键词', '描述', '新代码', NULL, '2016-3-25 09:47:13', '2016-3-25 09:47:13', 0, 0);
INSERT INTO `demo` VALUES (431, 00000000430, 1, 0, 'js', '基本命令', '关键词', '', '    \n$git remote -v # //查看远程服务器地址和仓库名称\n-------------------------------\n$ git checkout .//放弃本地所有未提交的修改\n$ git checkout index.html  //放弃某个文件的修改！\n-------------------------------分支的切换\n$ git br//列出本地分支(完整$ git branch -a )\n$ git br -a //列出本地分支和服务器的全部分支（$ git branch -a ）\n\n$ git co //分支名 切换本地分支（完整$ git checkout 分支名）\n$ git co -b //分支名字 远程分支全名 //本地新建分支并切换上去\n例如:$ git co -b 20160330-gengbo-b2btest remotes/origin/20160330-gengbo-b2btest\n-------------------------------文件夹的切换\n$  ls 列出文件和文件夹\n$ cd ..切换上层\n$ cd 文件夹名称\n----------------------------------clone克隆:\n$ git clone git://github.com/schacon/grit.git\n$ git clone git://github.com/schacon/grit.git mygrit\n----------------------------------常用\n$ git pull\n$ git push\n$ git add file.txt 空格分隔多个文件\n$ git commit -m \"zhugefeiying\"\n-----------------------------------查看状态\n$ git st/$ git status -s\n-----------------------------------取消更改某文件：$ git reset HEAD -- hello.php \n$ git status -s\n M README\n M hello.php\n$ git add .\n$ git status -s\nM  README\nM  hello.pp\n$ git reset HEAD -- hello.php \nUnstaged changes after reset:\nM    hello.php\n$ git status -s\nM  README\n M hello.php\n----------------------------------删除文件：$ git rm hello.php \n$ git rm hello.php \nrm \'hello.php\'\n$ ls\nREADME\n-------只删除缓存文件\n$ git rm --cached README \nrm \'README\'\n$ ls\nREADME\n----------------------------------列出所有文件：$ ls\n----------------------------------查看日志$ git log  ', NULL, '2016-3-25 09:47:25', '2016-5-25 00:47:13', 0, 0);
INSERT INTO `demo` VALUES (432, 00000000272, 1, 0, 'js', '页码生成策略', '关键词', '使用了数组，本来向使用数组的排序等方法，其实可以完全拼字符串！', '    function makePage(pageCount,curIndex,pageLimit){//总页，当前页\n        var pageCount =parseInt(pageCount);\n      var curIndex = parseInt(curIndex)||1;\n      var pageLimit = parseInt(pageLimit)||10;//默认10;\n      var pageArr =[];\n      var pagePlaceHolder = \'<span class=\\\"page-placeholder\\\">…</span>\';\n      if(pageCount>pageLimit){\n        if(pageCount-curIndex<pageLimit-4){//缩头 1。。 34567891011\n          console.log(\"缩头路线\");\n            for(var i = 0;i<pageLimit-2;i++){//倒数\n                pageArr.push(getPageNumHtml(pageCount-i));\n            }\n            pageArr.reverse();\n            pageArr.unshift(pagePlaceHolder);\n            pageArr.unshift(getPageNumHtml(1));\n        }else if(curIndex<pageLimit-4){//缩尾     123456789  。。100\n          console.log(\"缩尾路线\");\n            for(var i = 1;i<pageLimit-2;i++){//倒数\n                pageArr.push(getPageNumHtml(i));\n            }\n            pageArr.push(pagePlaceHolder);\n            pageArr.push(getPageNumHtml(pageCount));\n        }else{//双缩1。。     3456789     。。100\n          console.log(\"双缩路线\");\n            pageArr.push(getPageNumHtml(1));\n            pageArr.push(pagePlaceHolder);\n            for(var i = curIndex-(pageLimit-4)/2;i<curIndex+(pageLimit-4)/2+1;i++){\n            pageArr.push(getPageNumHtml(i));\n            }\n            pageArr.push(pagePlaceHolder);\n            pageArr.push(getPageNumHtml(pageCount));\n        }\n        $html = $(pageArr.join(\'\'));\n        $html.filter(function(){\n          return $(this).text()==curIndex;\n        }).addClass(\"cur\");\n        return $html;\n      }\n    }\nfunction getPageNumHtml(n){\n  return \'<a href=\\\"javascript:;\\\">\'+n+\'</a>\';\n}\nrefreshPage(100,5,20);', NULL, '2016-3-25 17:36:25', '2016-4-6 11:15:52', 0, 0);
INSERT INTO `demo` VALUES (433, 00000000152, 1, 0, 'html', 'figure+figcaption', '关键词', '文字裹在p标签里，与img标签各行其道，很难让人联想到这就是标题。HTML5通过采用<figure>元素对此进行了改正。当合<figcaption>元素组合使用时，我们就可以语义化地联想到这就是图片相对应的标题', '<img src=\"path/to/image\" alt=\"About image\" />\n<p>Image of Mars. </p>  \n================================demo\n<figure>\n    <img src=\"path/to/image\" alt=\"About image\" />\n    <figcaption>\n        <p>This is an image of something interesting. </p>\n    </figcaption>\n</figure>', NULL, '2016-3-26 00:34:33', '2016-3-26 00:35:20', 0, 0);
INSERT INTO `demo` VALUES (434, 00000000152, 1, 0, 'html', 'header+footer', '关键词', '', '<div id=\"header\">\n    ...\n</div>\n\n<div id=\"footer\">\n    ...\n</div>\n<!-------------------------demo--------------------->\n<header>\n    ...\n</header>\n\n<footer>\n    ...\n</footer>    ', NULL, '2016-3-26 00:39:41', '2016-4-7 17:56:05', 0, 0);
INSERT INTO `demo` VALUES (435, 00000000213, 1, 0, 'js', 'common', '关键词', '描述', '新代码', NULL, '2016-3-26 00:41:38', '2016-3-26 00:41:38', 0, 0);
INSERT INTO `demo` VALUES (436, 00000000435, 1, 0, 'css', '全部', '关键词', '1.IE和HTML5，', '/*为了确保所有新的HTML5元素能以block水平的元素正确地渲染，有必要对其做如下定义*/\n/*常用*/\n.fl{float:left;}\n.fr{float:right;}\n.text-center{text-align: center}\n.clear:before,.clear:after{content: \" \"; display: table;}\n.clear:after{clear:both;}\n/*====================demo start================*/\nheader, footer, article, section, nav, menu, hgroup {  \n    display: block;  \n}\n.mt10{margin-top:10px;}\n.mr10{margin-right:10px;}\n.mb10{margin-bottom:10px;}\n.ml10{margin-left:10px;}\n.mt20{margin-top:20px;}\n.mr20{margin-right:20px;}\n.mb20{margin-bottom:20px;}\n.ml20{margin-left:20px;}\n.pt10{padding-top:10px;}\n.pr10{padding-right:10px;}\n.pb10{padding-bottom:10px;}\n.pl10{padding-left:10px;}\n.pt20{padding-top:20px;}\n.pr20{padding-right:20px;}\n.pb20{padding-bottom:20px;}\n.pl20{padding-left:20px;}\n/*====================demo end================*/\n而且\ndocument.createElement(\"article\");\ndocument.createElement(\"footer\");\ndocument.createElement(\"header\");\ndocument.createElement(\"hgroup\");\ndocument.createElement(\"nav\");\ndocument.createElement(\"menu\");\n<!--[if IE]>\n<script src=\"http://html5shim.googlecode.com/svn/trunk/html5.js\"></script>\n<![endif]-->\n\n/* baidu.com */\nhtml{font-size:100px;font-family:Helvetica,sans-serif;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}\nbody{font-size:.13rem;line-height:.13rem}\nbody,dl,dd,h1,h2,h3,h4,h5,h6,p,form{margin:0}\nol,ul{margin:0;padding:0;list-style:none}\nimg{border:0}\naudio,canvas,progress,video{vertical-align:baseline}\naudio:not([controls]){display:none;height:0}\na{color:#3a7fde;text-decoration:none}\na:active{outline:0}\nb,strong{font-weight:700}\ni{color:#888}\nbutton,input,select,textarea{color:inherit;font:inherit;margin:0}\nbutton,select{text-transform:none}\nbutton,html input[type=button],input[type=reset],input[type=submit]{-webkit-appearance:button}\nbutton::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0}\ninput{line-height:normal}\ninput[type=number]::-webkit-inner-spin-button,input[type=number]::-webkit-outer-spin-button{height:auto}\ninput[type=search]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box}\ninput[type=search]::-webkit-search-cancel-button,input[type=search]::-webkit-search-decoration{-webkit-appearance:none}\ntable{border-collapse:collapse;border-spacing:0}\ntd,th{padding:0}\n', NULL, '2016-3-26 00:41:49', '2016-6-14 10:21:52', 0, 0);
INSERT INTO `demo` VALUES (437, 00000000381, 1, 0, 'html', 'autofocus', '关键词', 'HTML5的解决方案消除了对JavaScript的需要。如果一个特定的输入应该是“选择”，或有重点的，默认情况下，我们现在可以利用自动获取焦点属性。', '<input type=\"text\" name=\"someInput\" placeholder=\"212121\" required autofocus>', NULL, '2016-3-26 00:48:09', '2016-3-26 00:48:59', 0, 0);
INSERT INTO `demo` VALUES (438, 00000000152, 1, 0, 'html', 'Video', '关键词', '1. 我们技术上不需要来设置type属性，但是，如果我们不这样做，浏览器不得不自己去寻找类型。节省一些带宽，还是你自己声明下吧。\n 2. 不是所有的浏览器理解HTML5视频。在资源元素的下面，我们可以提供一个下载链接，或嵌入视频的Flash版本代替。这取决于你。\n 3controls和preload,<video preload controls>显示控制条!\n 4有方法可以让所有的浏览器支持video标签，具体参见“让所有浏览器支持HTML5 video视频标签”。\n', '<video controls preload>\n    <source src=\"cohagenPhoneCall.ogv\" type=\"video/ogg; codecs=\'vorbis, theora\'\" />\n    <source src=\"cohagenPhoneCall.mp4\" type=\"video/mp4; \'codecs=\'avc1.42E01E, mp4a.40.2\'\" />\n    <p> Your browser is old. <a href=\"cohagenPhoneCall.mp4\">Download this video instead.</a> </p>\n</video>', NULL, '2016-3-26 00:51:16', '2016-3-26 00:54:56', 0, 0);
INSERT INTO `demo` VALUES (439, 00000000084, 1, 0, 'js', '表单新变动', '关键词', '描述', '新代码', NULL, '2016-3-26 00:55:47', '2016-3-26 00:55:47', 0, 0);
INSERT INTO `demo` VALUES (440, 00000000439, 1, 0, 'html', 'pattern', '关键词', '1.如果你熟悉正则表达式，那么应该清楚[A-Za-z]{4,10}表示接受4-10位不区分大小写的英文字母。如果浏览器支持pattern属性，则提交表单时，如果文本框中的内容不符合其正则表达式\n2.事实上，这是一种确定浏览器兼容的常用方法。jQuery库了利用这种伎俩。在上面，我们创建了一个新的input元素，并确定了里面的pattern属性浏览器是否认得。如果是，浏览器则支持此功能。否则，当然就不支持了', '<form action=\"\" method=\"get\">\n    <label for=\"username\">姓名:</label>\n    <input id=\"username\" name=\"username\" type=\"text\" placeholder=\"4-10个英文字母\" pattern=\"[A-Za-z]{4,10}\" required=\"required\" autofocus /> \n    <button type=\"submit\">提交</button>\n</form> \n<script>\nif (!\'pattern\' in document.createElement(\'input\') ) {\n    // do client/server side validation\n}\n</script>', NULL, '2016-3-26 00:56:01', '2016-3-26 00:58:07', 0, 0);
INSERT INTO `demo` VALUES (441, 00000000152, 1, 0, 'html', 'mark', '关键词', '试想<mark>元素作为高亮。此标签包裹的字符串应该与用户当前的行动相关联。例如，我在一些博客上搜索“北川景子”，我就可以使用一些JavaScript将当前的每个结果字符串用mark标签包裹。', '<h3 > 搜索结果 </h3>\n<p> 我很喜欢《零秒出手》里面那个拉小提琴的女孩，原来她叫做 <mark>北川景子</mark>。 </p>', NULL, '2016-3-26 00:58:52', '2016-3-26 00:59:15', 0, 0);
INSERT INTO `demo` VALUES (442, 00000000169, 1, 0, 'js', '不是html5', '关键词', '', '\n    SVG:不是HTML5，至少5岁了。\n    CSS3:不是HTML5，它是…CSS。\n    Geolocation:不是HTML5.//zxx:Geolocation（地理位置）：通过HTML 5，您应该能够使Web应用程序可确定您的位置，并为您提供更多的相关信息。\n    Client Storage(客户端存储):非HTML5，虽说有一点切合，但被排除在规范之外，原因在于，担忧其作为一个整体，会变得过于复杂。它现在有自己的规范。\n    Web Sockets:不是HTML5，同样的，有着自己的一套准则。\n ', NULL, '2016-3-26 01:01:49', '2016-3-26 01:02:13', 0, 0);
INSERT INTO `demo` VALUES (443, 00000000310, 1, 0, 'html', 'css调用html中的文字', '关键词', '注意：当使用attr()获取标签属性名的时候，千万不要添加引号!', '.data_custom { display:inline-block; position: relative; }\n.data_custom:hover { color: transparent; }\n.data_custom:hover:after {\n    content: attr(data-hover-response);\n    color: black;\n    position: absolute;\n    left: 0;\n}\n<a class=\"data_custom\" data-hover-response=\"我说过不要碰我！\" href=\"#\">不要碰我，雅蠛蝶~~</a>\n==================================demo2\ninput[type=range]:before { content: attr(min); padding-right: 5px; }\ninput[type=range]:after { content: attr(max); padding-left: 5px;}\n==========================================demo3\na.content:after {\n   content: attr(href);\n}\n\n<a class=\"content\" href=\"http://www.zhangxinxu.com/\">此标签的href值是：</a>  \n=====================================demo4\ndiv.logo {\n   content:url(logo.png);\n}\n=================================demo5\np a[href $=\".pdf\"]:after {\n    content:url(../image/icon_pdf.png);\n}\np a[rel = \"external\"]:after {\n    content:url(../image/icon_link.png);\n}\n\nHTML代码：\n\n<p>您可以查看此PDF文件：<a href=\"/sample.pdf\">web站点的性能优化.pdf</a>，或是在线查看，<a href=\"http://www.zhangxinxu.com/wordpress/\" rel=\"external\">点击这里</a>。</p>\n=============================demo6\n\n\na:after {\n   content: \"(\" attr(href) \")\";\n}\n\nabbr:after {\n   content: \"(\" attr(title) \")\";\n}\n', NULL, '2016-3-26 01:05:44', '2016-3-26 01:26:17', 0, 0);
INSERT INTO `demo` VALUES (444, 00000000439, 1, 0, 'js', 'input[type=range]', '关键词', '', '<form method=\"post\">\n    <h4>音量控制</h4>\n    <input type=\"range\" name=\"range\" min=\"0\" max=\"10\" step=\"1\" value=\"\" />\n    <output name=\"result\">  </output>\n</form>\n    var o = document.createElement(\'input\');\n    o.type = \'range\';\n    if ( o.type === \'text\' ) alert(\'不好意思，你的浏览器还不够酷，试试最新的Opera浏览器吧。\');', NULL, '2016-3-26 01:09:24', '2016-3-26 01:27:46', 0, 0);
INSERT INTO `demo` VALUES (445, 00000000152, 1, 0, 'html', 'ol+li', '关键词', '有序列表', 'ol {\n   list-style-type:none;        \n   counter-reset:sectioncounter;\n}                      \nol li:before {\n   content:\"美女\" counter(sectioncounter) \"： \"; \n   counter-increment:sectioncounter;\n}\n\nHTML代码：\n\n<ol>\n    <li><img src=\"http://image.zhangxinxu.com/image/study/s/s128/mm1.jpg\" width=\"128\" height=\"96\" /></li>\n    <li><img src=\"http://image.zhangxinxu.com/image/study/s/s128/mm3.jpg\" width=\"128\" height=\"96\" /></li>\n</ol>', NULL, '2016-3-26 01:16:09', '2016-3-26 01:16:39', 0, 0);
