INSERT INTO `demo` VALUES (472, 00000000309, 1, 0, 'js', 'fixed in iframe', '关键词', '', '1.把js代码跳到父页面来执行，存在跨域问题\n2.子页面使用absolute，并通过父框架的滚动条来监听！依赖jQuery、存在跨域问题\n$(parent.window).scroll(function(){\n  $(\'#header_fixed\').css({\n    top : $(parent.window).scrollTop();\n  });\n});', NULL, '2016-3-31 16:10:32', '2016-3-31 16:12:34', 0, 0);
