INSERT INTO `demo` VALUES (482, 00000000211, 1, 0, 'css', 'flex简单案列', '关键词', '', '.fangjia-content{\n    display:-webkit-box;\n    display:-webkit-flex;\n    display:-ms-flexbox;\n    display:flex;\n    padding:0}\n.fangjia-content li{\n    border:0;\n    padding:0;\n    padding-left:1.25rem;\n    margin:1.25rem 0;\n    -webkit-box-flex: 2;\n    -webkit-flex: 2;\n    -ms-flex: 2;\n    flex: 2;\n}.fangjia-content li:first-child{\n    border:0;\n    padding:0;\n    padding-left:1.25rem;\n    margin:1.25rem 0;\n    -webkit-box-flex: 1;\n    -webkit-flex: 1;\n    -ms-flex: 1;\n    flex: 1;\n}\n/*=======tmall.com======*/\n.mui-flex {\n    display: -webkit-box;\n    display: -webkit-flex;\n    display: -ms-flexbox;\n    display: flex;\n    -webkit-flex-wrap: wrap;\n    -ms-flex-wrap: wrap;\n    flex-wrap: wrap;\n}\n.cell{\n    -webkit-box-flex:1;\n    -webkit-flex:1;\n    -ms-flex:1;\n    flex:1;\n    /*-webkit-flex-basis: 0;\n    -ms-flex-preferred-size: 0;\n    flex-basis: 0;*/\n}\n/*手机端头部浮动导航的flex布局，实现了左右小图标，中间自适应*/\n<div style=\"height:40px;line-height:40px;display:flex;flex-flow:wrap;margin-top:40px\">\n  <div style=\"display:block;width:70px;background-color:green\">56789</div>\n  <div style=\"flex:1;background-color:black\">2</div>\n  <div style=\"display:block;width:150px;background-color:red\">7890</div>\n</div>', NULL, '2016-4-6 01:45:13', '2016-4-11 10:41:05', 0, 0);
