INSERT INTO `demo` VALUES (490, 00000000489, 1, 0, 'js', 'demo', '关键词', '', 'var myrange = document.getSelection();\nvar len =myrange.rangeCount;\nfor(var i=0;i<len;i++){\n  console.log(myrange.getRangeAt(i).toString());\n  console.log(myrange.getRangeAt(i).endContainer.length);\n  console.log(myrange.getRangeAt(i).endContainer.nodeValue);\n  console.log(myrange.getRangeAt(i).startOffset);\n  console.log(myrange.getRangeAt(i).endOffset);\n}\n// collapsed:false\n// commonAncestorContainer:<TextNode textContent=\"可以通过..\n// endContainer:<TextNode textContent=\"可以通过..\n// endOffset:32\n// startContainer:<TextNode textContent=\"可以通过..\n// startOffset:29\n// __proto__', NULL, '2016-4-7 15:35:34', '2016-4-7 15:57:45', 0, 0);
INSERT INTO `demo` VALUES (491, 00000000489, 1, 0, 'js', '方法', '关键词', '', 'cloneContents();             //返回新的 DocumentFragment 对象，它包含该范围表示的文档区域的副本。\ncloneRange();                 //创建一个新的 Range 对象，表示与当前的 Range 对象相同的文档区域。\ncollapse();                 //折叠该范围，使它的边界点重合。\ncompareBoundaryPoints();     //比较指定范围的边界点和当前范围的边界点，根据它们的顺序返回 -1、0 和 1。比较哪个边界点由它的第一个参数指定，它的值必须是前面定义的常量之一。\ndeleteContents();             //删除当前 Range 对象表示的文档区域。\ndetach();                     //通知实现不再使用当前的范围，可以停止跟踪。如果调用了范围的这个方法，那么接下来调用的该范围任何方法都会抛出代码为 INVALID_STATE_ERR 的 DOMException 异常。\nextractContents();             //删除当前范围表示的文档区域，并且以 DocumentFragment 对象的形式返回那个区域的内容。该方法和 cloneContents()方法与 deleteContents()方法的组合很相似。\ninsertNode();                 //把指定的节点插入文档范围的开始点。\nselectNode();                 //设置该范围的边界点，使它包含指定的节点和它的所有子孙节点。\nselectNodeContents();         //设置该范围的边界点，使它包含指定节点的子孙节点，但不包含指定的节点本身。\nsetEnd();                     //把该范围的结束点设置为指定的节点和偏移量。\nsetEndAfter();                 //把该范围的结束点设置为紧邻指定节点的节点之后。\nsetEndBefore();             //把该范围的结束点设置为紧邻指定节点之前。\nsetStart();                 //把该范围的开始点设置为指定的节点中的指定偏移量。\nsetStartAfter();             //把该范围的开始点设置为紧邻指定节点的节点之后。\nsetStartBefore();             //把该范围的开始点设置为紧邻指定节点之前。\nsurroundContents();         //把指定的节点插入文档范围的开始点，然后重定范围中的所有节点的父节点，使它们成为新插入的节点的子孙节点。\ntoString();                 //返回该范围表示的文档区域的纯文本内容。', NULL, '2016-4-7 15:58:15', '2016-4-7 16:00:53', 0, 0);
INSERT INTO `demo` VALUES (492, 00000000152, 1, 0, 'html', 'template', '关键词', '1.标签内容默认隐藏.\nwindow.getComputedStyle(template).display;    // 结果是\"none\"\n2使用template.content或者template.innerHTML拿到内容\n例如：var image_first = template.content.querySelector(\"img\");\n3.兼容性不好，ie13才开始支持\n4.和script相比，template是实体dom，script只能是字符串，只能append到页面，template可以克隆：var clone = document.importNode(template.content, true);可以使用appendChild方法到页面。', '<script type=\"text/template\">\n<img src=\"mm1.jpg\">\n</script>\n\n<textarea style=\"display: none;\">\n<img src=\"mm1.jpg\">\n</textarea>\n\n<xmp style=\"display: none;\">\n<img src=\"mm1.jpg\">\n</xmp>\n\n<template>\n<img src=\"mm1.jpg\">\n</template>\n\n', NULL, '2016-4-7 17:50:25', '2016-4-7 17:55:41', 0, 0);
