INSERT INTO `demo` VALUES (495, 00000000494, 1, 0, 'html', '锤子网站源码', '关键词', '{{}}\nng-class\nng-view\nng-click\nng-if\nng-show=loading\nhttp://www.smartisan.com/en/t2/#/overview', '<!doctype html>\n<html class=\"responsive {{lang}}\" lang=zh ng-app=t2App>\n<head>\n<meta charset=utf-8>\n<meta name=keywords content=\"锤子, 锤子科技官网, 锤子手机官网, 锤子科技, Smartisan, SmartisanOS, SmartisanROM, 锤子ROM\">\n<meta name=description content=锤子科技是一家制造移动互联网终端设备的公司，公司的使命是用完美主义的工匠精神，打造用户体验一流的数码消费类产品（智能手机为主），改善人们的生活质量。>\n<meta http-equiv=X-UA-Compatible content=\"IE=Edge\">\n<meta name=renderer content=webkit>\n<meta name=viewport content=\"width=device-width, initial-scale=1, maximum-scale=1\">\n<title>Smartisan T2</title>\n<link href=http://static.smartisanos.cn/common/img/favicon.ico rel=\"shortcut icon\">\n<link href=http://static.smartisanos.cn/common/img/favicon_114.png rel=apple-touch-icon>\n<link href=http://static.smartisanos.cn/common/img/favicon_76.png sizes=76x76 rel=apple-touch-icon>\n<link href=http://static.smartisanos.cn/common/img/favicon_120.png sizes=120x120 rel=apple-touch-icon>\n<link href=http://static.smartisanos.cn/common/img/favicon_152.png sizes=152x152 rel=apple-touch-icon>\n<link rel=stylesheet href=http://static.smartisanos.cn/common/css/base_f376a10b2d.css>\n<link rel=stylesheet href=http://static.smartisanos.cn/t2/css/main_e88396d4af_1493783076.css>\n<!--[if lte IE 7]>\n <script src=\"http://static.smartisanos.cn/common/js/update-browser.js\">\n </script>\n <![endif]-->\n</head>\n<body class=\"t2 blockimages {{osClass}}\" ng-controller=MainCtrl>\n<div class=wrapper>\n        <div class=hide> </div>\n        <div class=header ng-if=\"lang != \'en\' && lang != \'jp\'\" route-change-reset-header mobile-device>\n                <div class=header-main>\n                        <div class=container>\n                                <h1 class=logo><a href=http://www.smartisan.com/#/home>Smartisan </a> </h1>\n                                <div class=nav>\n             