INSERT INTO `demo` VALUES (496, 00000000163, 1, 0, 'js', 'js通过random生成随机字符串', '关键词', 'Math.random().toString(36).substr(2)；', 'function generateRandomAlphaNum(len) {\n    var rdmString = \"\";\n    for (; rdmString.length < len; rdmString += Math.random().toString(36).substr(2));\n    return rdmString.substr(0, len);\n}\ngenerateRandomAlphaNum(3);', NULL, '2016-4-8 18:40:32', '2016-4-8 18:41:16', 0, 0);
INSERT INTO `demo` VALUES (497, 00000000493, 1, 0, 'js', '手机m站分析', '关键词', '描述', '新代码', NULL, '2016-4-11 00:49:05', '2016-4-11 00:49:05', 0, 0);
INSERT INTO `demo` VALUES (498, 00000000497, 1, 0, 'html', '天猫', '关键词', '描述', '<!-- flex的使用 -->\n<ul class=\"mui-flex\">\n    <li class=\"cell\" ></li>\n    <li class=\"cell\" ></li>\n    <li class=\"cell\" ></li>\n    <li class=\"cell\" ></li>\n</div>\n<ul class=\"mui-flex\">\n    <li class=\"cell fixed\" ></li>\n    <li class=\"cell\" ></li>\n    <li class=\"cell fixed\" ></li>\n</div>\n<div class=\"mui-flex\">\n    <div class=\"cell\" ></div>\n    <div class=\"cell mui-flex\" >\n      <div class=\"cell\" ></div>\n      <div class=\"cell\" ></div>\n   </div>\n</div>\n<!-- 绝对定位 -->\n<div style=\"position:relative\">\n<div style=\"position:absolute\"></div>\n<div style=\"position:absolute\"></div>\n<div style=\"display:block;padding:0 50px\"></div> \n</div>\n<!-- 上下左右居中的图片 -->\n.wonderful-rec .card-item .item-pic img {\n    display: block;\n    position: relative;\n    top: 50%;\n    left: 50%;\n    -webkit-transform: translate(-50%,-50%);\n    -moz-transform: translate(-50%,-50%);\n    -ms-transform: translate(-50%,-50%);\n    -o-transform: translate(-50%,-50%);\n    transform: translate(-50%,-50%);\n    width:100%;\n}\n<!--图片的容器尺寸使用了js计算出高度，宽度100%-->', NULL, '2016-4-11 00:49:14', '2016-4-11 02:04:49', 0, 0);
INSERT INTO `demo` VALUES (499, 00000000211, 1, 0, 'html', 'flex的safari支持', '关键词', '-webkit-box-flex:1;', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <style>\n    .multi-flex{\n        display:-webkit-box;\n        display:-webkit-flex;\n        display:-ms-flexbox;\n        display:flex;\n        -webkit-flex-wrap:wrap;\n        -ms-flex-wrap:wrap;\n        flex-wrap:wrap;\n    }\n.cell{\n    -webkit-box-flex:1;\n    -webkit-flex:1;\n    -ms-flex:1;\n    flex:1;\n    /*-webkit-flex-basis: 0;\n    -ms-flex-preferred-size: 0;\n    flex-basis: 0;*/\n}\n    </style>\n</head>\n<body>\n    <div class=\"multi-flex\">\n        <div class=\"cell\">\n        <div style=\"height:100px;background-color:red\">1234</div>\n        </div>\n        <div class=\"cell\">\n        <div style=\"height:100px;background-color:green\">1234</div>\n        </div>\n        <div class=\"cell\">\n        <div style=\"height:100px;background-color:yellow\">1234</div>\n        </div>\n        <div class=\"cell\">\n        <div style=\"height:100px;background-color:blaok\">1234</div>\n        </div>\n        <div class=\"cell\">\n        <div style=\"height:100px;background-color:red\">1234</div>\n        </div>\n    </div>\n</body>\n</html>', NULL, '2016-4-11 12:33:57', '2016-4-11 12:35:14', 0, 0);
INSERT INTO `demo` VALUES (500, 00000000172, 1, 0, 'html', '$.event.fix(e)', '关键词', 'function(e){\n  var e = $.event.fix(e);\n}', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n<title>利用jQuery的$.event.fix函数统一浏览器event处理</title>\n<script type=\"text/javascript\" src=\"http://ok.94007.com:8089/php/edit/js/jquery.js\"></script>\n</head>\n<body>\n<input type=\"button\" value=\"http://blog.csdn.net/webflash\" onclick=\"eventHandler(event)\" />\n<script type=\"text/javascript\">\n//请使用不同浏览器测试本页，你将看到一样的结果\nfunction eventHandler(e)\n{\n    console.log(e);\n    var event = $.event.fix(e);\n    console.log(event);\n    var elem = event.target;\n    alert(\'当前点击对象的标签名是:\' + elem.tagName);\n    alert(\'当前点击对象的标签名是:\' + elem.tagName);\n    alert(\'当前点击按钮文本是:\' + elem.value);\n    alert(\'pageX:\' + event.pageX + \',pageY:\' + event.pageY);\n    //得到按键码\n    event.keyCode\n    //取消浏览器默认行为\n    event.preventDefault();\n    //取消事件冒泡\n    event.stopPropagation();\n    //...还有好些不是很常用属性，这里不一一列举\n}\n</script>\n</body>\n</html>', NULL, '2016-4-11 13:30:34', '2016-4-11 13:37:29', 0, 0);
INSERT INTO `demo` VALUES (501, 00000000163, 1, 0, 'js', '判断页面是否被iframe', '关键词', 'self!=top//暂不考虑跨域的问题！', 'if(self!=top){\n                    var parentTop = $(parent.document).scrollTop();\n                    $(this).find(\".modal-dialog\").css(\"margin-top\",parentTop+30);\n                }', NULL, '2016-4-11 16:30:24', '2016-4-11 16:30:54', 0, 0);
INSERT INTO `demo` VALUES (502, 00000000163, 1, 0, 'js', 'javascript type=text/template', '关键词', '描述', '<html> <head> <title>标题</title> </head> <body> <div id=\"comment_ul_2\"></div> <input type=\"button\" id=\"addFun\" value=\"click me\" /> <script type=\"text/javascript\"> var reg = new RegExp(\"\\[([^\\[\\]]*?)\\]\", \'igm\'); //i g m是指分别用于指定区分大小写的匹配、全局匹配和多行匹配。\n $(\"#addFun\").click(function() { var html = document.getElementById(\"commentTemplate\").innerHTML; var source = html.replace(reg, function(node, key) { return { \'UserImg\' : \'1\', \'UserName\' : \'张\', \'CreateDate\' : \'2011-1-1\' }[key]; }); $(\"#comment_ul_2\").append(source); }); var zzl = \"name:[name]\"; zzl = zzl.replace(reg, function(node, key) { return { \'name\' : \'小明\' }[key]; }); alert(zzl); </script> </body> </html>', NULL, '2016-4-11 23:58:59', '2016-4-12 00:12:06', 0, 0);
