INSERT INTO `demo` VALUES (504, 00000000381, 1, 0, 'js', 'novalidate', '关键词', '适用于：<form>，以及以下类型的 <input> 标签：text, search, url, telephone, email, password, date pickers, range 以及 color。', '<form action=\"demo_form.asp\" novalidate=\"novalidate\">\n  E-mail: <input type=\"email\" name=\"user_email\" />\n  <input type=\"submit\" />\n</form>', NULL, '2016-4-13 14:26:38', '2016-4-13 14:29:32', 0, 0);
INSERT INTO `demo` VALUES (505, 00000000172, 1, 0, 'js', '$.expr', '关键词', '扩展过滤器', '\n  // Case insensitive contains search\n  $.expr[\':\'].icontains = function (obj, index, meta) {\n    var $obj = $(obj);\n    var haystack = ($obj.data(\'tokens\') || $obj.text()).toUpperCase();\n    return haystack.includes(meta[3].toUpperCase());\n  };\n\n  // Case insensitive begins search\n  $.expr[\':\'].ibegins = function (obj, index, meta) {\n    var $obj = $(obj);\n    var haystack = ($obj.data(\'tokens\') || $obj.text()).toUpperCase();\n    return haystack.startsWith(meta[3].toUpperCase());\n  };\n\n  // Case and accent insensitive contains search\n  $.expr[\':\'].aicontains = function (obj, index, meta) {\n    var $obj = $(obj);\n    var haystack = ($obj.data(\'tokens\') || $obj.data(\'normalizedText\') || $obj.text()).toUpperCase();\n    return haystack.includes(meta[3].toUpperCase());\n  };\n\n  // Case and accent insensitive begins search\n  $.expr[\':\'].aibegins = function (obj, index, meta) {\n    var $obj = $(obj);\n    var haystack = ($obj.data(\'tokens\') || $obj.data(\'normalizedText\') || $obj.text()).toUpperCase();\n    return haystack.startsWith(meta[3].toUpperCase());\n  };\n', NULL, '2016-4-13 16:29:39', '2016-4-13 16:29:58', 0, 0);
