INSERT INTO `demo` VALUES (508, 00000000507, 1, 0, 'js', '基本命令', '关键词', '', 'cls------------清屏\n？任意字符----------url过滤查找\n选中后ctrl+1234--------标记为红蓝黄绿\ng/go ----------------------------单步前进，前进一步\n>100----------选出返回字节数超过100的会话\n@baidu.com------------选出指定host的会话，？baidu.com也ok\nbpafter /favicon.ico包含这些字符串的url的会话将被单步，再次输入bpafter解除\nbps 404-------------404状态码的会话被单步！\nbpu baidu.com ----------------------类似bpafter\nurlreplace a b -----------所有的请求被替换后转向,把a变成b，输入无参数的放开\nselect image select css select htm------------从Content- Type中匹配会话\nquit-----------关闭软件\n!listen 8889 4443------------------监听别的端口？', NULL, '2016-4-16 23:50:40', '2016-4-27 14:31:08', 0, 0);
INSERT INTO `demo` VALUES (509, 00000000172, 1, 0, 'js', '$on', '关键词', '', '//------------------demo1\nvar str=\"jsjsjsjsjsjjs\"\n  $(\"div\").on(\"click focus\",\"input select\",{\"mystr\":str},function(e){\n    $(this).text(e.data.mystr);\n  });\n//-----------------demo2\nvar str = \"呵呵\";\n  $(\"p\").on({\n    mouseover:function(){$(\"body\").css(\"background-color\",\"lightgray\");},  \n    mouseout:function(){$(\"body\").css(\"background-color\",\"lightblue\");}, \n    click:function(){$(\"body\").css(\"background-color\",\"yellow\");}  \n  },\"input select\",{\"mystr\":str});', NULL, '2016-4-17 00:34:27', '2016-5-11 17:04:14', 0, 0);
