INSERT INTO `demo` VALUES (517, 00000000515, 1, 0, 'php', '将指定字符串写入文件', '关键词', '', ' <?php\n$filename=\'test.txt\';\n$str=\'abc\'；\nwritefile($filename,$str);\nfunction writefile($fname,$str){\n$fp=fopen($fname,\"w\")\nfputs($fp,$str);\nfclose($fp);\n}?>\n', NULL, '2016-4-17 21:18:13', '2016-4-17 23:53:19', 0, 0);
