INSERT INTO `demo` VALUES (520, 00000000519, 1, 0, 'php', 'rand()', '关键词', '', '<?php\n$arr=array(\"123\",\"456\",\"789\");\n$array=array(\"12\",\"34\",\"56\");\n$rand=rand(0,2);\necho $arr[$rand].$array[$rand];\n?>', NULL, '2016-4-17 23:57:00', '2016-4-17 23:57:08', 0, 0);
INSERT INTO `demo` VALUES (521, 00000000519, 1, 0, 'php', 'time()', '关键词', '获取php中unix时间戳，time()为直接获取得到', '    <?php\necho(time());//1460908777\n?>  ', NULL, '2016-4-18 00:00:02', '2016-4-18 00:02:04', 0, 0);
