INSERT INTO `demo` VALUES (523, 00000000519, 1, 0, 'php', 'date()', '关键词', '', '<?php\necho(date(\'Y--m--d\'));//2016-04--18\necho(date(\'Y-m-d H:i:s\'));//2016-04--18\necho(date(\'Y-m-d\', time()));//2016-04--18\necho(date(\'Y-m-d\',1461081600));//2016-04-20\n?>', NULL, '2016-4-18 00:03:55', '2016-4-18 00:06:49', 0, 0);
INSERT INTO `demo` VALUES (524, 00000000272, 1, 0, 'html', 'canvas鼠标作画', '关键词', '', '    <!DOCTYPE html>\n    <html lang=\"en\">\n    <head>\n    <meta charset=\"utf-8\"/>\n    <script src=\"jquery.js\"></script>\n    </head>\n    <body>\n    <canvas width=\"1000\" height=\"1000\" id=\"myCanvas\"></canvas>\n    <script>\n    $(function(){\n        var myCanvas = document.getElementById(\"myCanvas\");\n        var context = myCanvas.getContext(\'2d\');\n        context.strokeStyle = \'red\';\n        context.lineWidth = 3;\n        var $canvas = $(\"#myCanvas\");\n        var canvasL = $canvas.offset().left;\n        var canvasT = $canvas.offset().top;\n        var drawing = false;\n        $canvas.mousedown(function(e){\n            drawing= true;\n            context.beginPath();\n            if(drawing){\n                e = $.event.fix(e);\n                context.moveTo(e.pageX-canvasL,e.pageY-canvasT);\n                console.log(\"moveTo:\"+(e.pageX-canvasL)+\"-\"+(e.pageY-canvasT));\n            }\n        });\n        $canvas.mousemove(function(e){\n            if(drawing){\n                e = $.event.fix(e);\n                context.lineTo(e.pageX-canvasL,e.pageY-canvasT);\n                context.closePath();\n                context.stroke();\n                context.moveTo(e.pageX-canvasL,e.pageY-canvasT);\n                console.log(\"lineTo:\"+(e.pageX-canvasL)+\"-\"+(e.pageY-canvasT));\n            }\n        });\n        $canvas.on(\"mouseup\",function(){\n            drawing= false;\n        });\n    });\n    </script>\n    </body>\n    </html>', NULL, '2016-4-18 13:59:44', '2016-4-18 16:57:25', 0, 0);
INSERT INTO `demo` VALUES (525, 00000000272, 1, 0, 'html', 'canvas手机端手写作画', '关键词', '', '    <!DOCTYPE html>\n    <html lang=\"en\">\n    <head>\n    <meta charset=\"utf-8\"/>\n    <meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0,maximum-scale=1.0,minimum-scale=1.0,user-scalable=no\">\n    <script src=\"jquery.js\"></script>\n    <style type=\"text/css\">\n        .myblock{display:inline-block;padding:10px;border:1px solid #ccc;margin:0 10px 10px 0}\n        .mycolorbox,.linewidth{position:relative;display:inline-block;width:60px;height:60px;box-sizing:border-box;}\n        .mycolorbox.cur,.linewidth.cur{border:4px dotted #ccc;}\n        .mycolorbox:nth-child(1){background-color:red;}\n        .mycolorbox:nth-child(2){background-color:green;}\n        .mycolorbox:nth-child(3){background-color:blue;}\n        .mycolorbox:nth-child(4){background-color:yellow;}\n        .mycolorbox:nth-child(5){background-color:black;}\n        .mycolorbox:nth-child(6){background-color:red;}\n        .mycolorbox:nth-child(7){background-color:grey;}\n        .mycolorbox:nth-child(8){background-color:pink;}\n        .linewidth:after{content: \"\";position:absolute;background-color: #000;border-radius: 50%;top:50%;left:50%;transform: translate(-50%,-50%);}\n        .linewidth:nth-child(1):after{width:5px;height: 5px}\n        .linewidth:nth-child(2):after{width:10px;height: 10px}\n        .linewidth:nth-child(3):after{width:15px;height: 15px}\n        button{padding:10px 10px;display:inline-block;}\n        button:first-of-type{margin-right:10px;}\n    </style>\n    </head>\n    <body>\n    <div class=\"myblock\">\n        <div class=\"mycolorbox cur\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n        <div class=\"mycolorbox\"></div>\n    </div>\n    <div class=\"myblock\">\n        <div class=\"linewidth cur\"></div>\n        <div class=\"linewidth\"></div>\n        <div class=\"linewidth\"></div>\n    </div><button onclick=\"getdata()\">保存</button><button onclick=\"cleardata()\">重置</button>\n    <canvas width=\"360\" height=\"600\" id=\"myCanvas\" style=\"border:1px solid #ccc\"></canvas>\n    <script>\n    function getdata(){\n        alert(document.getElementById(\"myCanvas\").toDataURL());\n    }\n    function cleardata(){\n        var dom =document.getElementById(\"myCanvas\") \n        dom.getContext(\"2d\").clearRect(0,0,dom.width,dom.height);\n    }\n    $(function(){\n        $(\".myblock .linewidth\").click(function(){\n            context.lineWidth = ($(this).index()+1)*5;\n            $(this).addClass(\"cur\").siblings().removeClass(\"cur\");\n        });\n        $(\".mycolorbox\").click(function(){\n            context.strokeStyle = $(this).css(\"background-color\");\n            $(this).addClass(\"cur\").siblings().removeClass(\"cur\");\n        });\n        var myCanvas = document.getElementById(\"myCanvas\");\n        myCanvas.width = $(window).width();\n        myCanvas.height = $(window).height();\n        var context = myCanvas.getContext(\'2d\');\n        context.strokeStyle = \'green\';\n        context.lineCap = \'round\';\n        context.lineWidth = 6;\n        var $canvas = $(\"#myCanvas\");\n        var canvasL = $canvas.offset().left;\n        var canvasT = $canvas.offset().top;\n        var drawing = false;\n        myCanvas.addEventListener(\"touchstart\",function(e){\n            drawing= true;\n            context.beginPath();\n            if(drawing){\n                context.moveTo(e.touches[0].pageX-canvasL,e.touches[0].pageY-canvasT);\n                // console.log(\"moveTo:\"+(e.touches[0].pageX-canvasL)+\"-\"+(e.touches[0].pageY-canvasT));\n            }\n            e.preventDefault();\n        });\n        myCanvas.addEventListener(\"touchmove\",function(e){\n            if(drawing){\n                context.lineTo(e.touches[0].pageX-canvasL,e.touches[0].pageY-canvasT);\n                context.stroke();\n                context.moveTo(e.touches[0].pageX-canvasL,e.touches[0].pageY-canvasT);\n                // console.log(\"lineTo:\"+(e.touches[0].pageX-canvasL)+\"-\"+(e.touches[0].pageY-canvasT));\n            }\n            e.preventDefault();\n        });\n        myCanvas.addEventListener(\"touchend\",function(e){\n            context.closePath();\n            drawing= false;\n            e.preventDefault();\n        });\n    });\n    </script>\n    </body>\n    </html>', NULL, '2016-4-18 16:42:47', '2016-4-20 00:50:38', 0, 0);
INSERT INTO `demo` VALUES (526, 00000000163, 1, 0, 'js', 'clientX/pageX/screenX', '关键词', '', '元素：\nelement.offsetLeft\nelement.offsetTop\n视口坐标：\nevent.clientX\nevent.clientY\n显示器坐标\nevent.screenX\n文档坐标\nevent.pageX', NULL, '2016-4-19 23:24:06', '2016-4-19 23:27:43', 0, 0);
INSERT INTO `demo` VALUES (527, 00000000255, 1, 0, 'css', 'appearance', '关键词', '', '.elmClass{\n   -webkit-appearance: value;\n   -moz-appearance:    value;\n   appearance:         value;\n}\np{\n    appearance:checkbox;\n    appearance:radio;\n    appearance:push-button;\n    appearance:square-button;\n    appearance:button;\n    appearance:button-bevel;\n    appearance:listbox;\n    appearance:listitem;\n    appearance:menulist;\n    appearance:menulist-button;\n    appearance:menulist-text;\n    appearance:menulist-textfield;\n    appearance:scrollbarbutton-up;\n    appearance:scrollbarbutton-down;\n    appearance:scrollbarbutton-left;\n    appearance:scrollbarbutton-right;\n    appearance:scrollbartrack-horizontal;\n    appearance:scrollbartrack-vertical;\n    appearance:scrollbarthumb-horizontal;\n    appearance:scrollbarthumb-vertical;\n    appearance:scrollbargripper-horizontal;\n    appearance:scrollbargripper-vertical;\n    appearance:slider-horizontal;\n    appearance:slider-vertical;\n    appearance:sliderthumb-horizontal;\n    appearance:sliderthumb-vertical;\n    appearance:caret;\n    appearance:searchfield;\n    appearance:searchfield-decoration;\n    appearance:searchfield-results-decoration;\n    appearance:searchfield-results-button;\n    appearance:searchfield-cancel-button;\n    appearance:textfield;\n    appearance:textarea;\n}', NULL, '2016-4-20 10:34:34', '2016-4-20 10:36:03', 0, 0);
INSERT INTO `demo` VALUES (528, 00000000292, 1, 0, 'js', 'ng-repeat', '关键词', '主要实现了列表的迭代，数据的切换，模块注入，再吧注入的模块中的服务注入到controll中去', '<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myapp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body ng-controller=\"mycontroller as mc\">\n<ul>\n    <li ng-repeat=\"item in mc.objarr\"><a href=\"{{item.link}}\">{{item.str}}</a></li>\n</ul>\n<button ng-click = \"mc.changedata()\">拉取数据</button>\n    <script>\n    var app = angular.module(\"myapp\",[\"myservice\"]);\n    var myservice = angular.module(\"myservice\",[]);\n    myservice.service(\"myajax\",function($timeout){\n        this.getdata = function(callback){\n            console.log(\"服务收到请求\");\n            var arr =  [{\n                        link:\"http://51.com\",\n                        str:\"虎翼\"\n                    },\n                    {\n                        link:\"http://laibatour.cn\",\n                        str:\"来吧\"\n                    },\n                    {\n                        link:\"http://sohu.com\",\n                        str:\"搜狐\"\n                    },\n                    {\n                        link:\"http://zhaopin.com\",\n                        str:\"智联\"\n                    }];\n            $timeout(function(){\n                callback(arr);\n            },1000);\n        }\n    });\n    app.controller(\"mycontroller\",[\"myajax\",\"$scope\",function(myajax,$scope){\n        var thisctrl = this;\n        this.changedata=function(){\n            console.log(\"准备请求服务\");\n            myajax.getdata(function(data){//定时函数引起了一个this的坑\n                $scope.$apply(function(){\n                    console.log(data);\n                    thisctrl.objarr = data;\n                });\n            });\n        }\n        this.objarr = [{\n            link:\"http://baidu.com\",\n            str:\"百度\"\n        },\n        {\n            link:\"http://sina.com.cn\",\n            str:\"新浪\"\n        },\n        {\n            link:\"http://qq.com\",\n            str:\"腾讯\"\n        },\n        {\n            link:\"http://www.163.com\",\n            str:\"网易\"\n        }];\n    }]);\n    </script>\n</body>\n</html>', NULL, '2016-4-20 13:04:12', '2016-4-20 13:15:15', 0, 0);
INSERT INTO `demo` VALUES (529, 00000000222, 1, 0, 'html', '相邻选择器', '关键词', '', '<!DOCTYPE HTML>\n<html>\n<head>\n<style type=\"text/css\">\nh1 + p {margin-top:50px;}/*第一个p*/\np+p{color:red}/*除了第一个p*/\n</style>\n</head>\n<body>\n<h1>This is a heading.</h1>\n<p>This is paragraph.</p>\n<p>This is paragraph.</p>\n<p>This is paragraph.</p>\n<p>This is paragraph.</p>\n<p>This is paragraph.</p>\n</body>\n</html>\n', NULL, '2016-4-20 17:54:58', '2016-4-20 17:55:15', 0, 0);
INSERT INTO `demo` VALUES (534, 00000000452, 1, 0, 'js', '源码分析', '关键词', '描述', '新代码', NULL, '2016-4-25 00:21:30', '2016-4-25 00:21:30', 0, 0);
INSERT INTO `demo` VALUES (535, 00000000534, 1, 0, 'js', 'undersource源码', '关键词', '描述', '/* Underscore.js 1.3.3*/\n/* (c) 2009-2012 Jeremy Ashkenas, DocumentCloud Inc.*/\n/* Underscore is freely distributable under the MIT license.*/\n/* Portions of Underscore are inspired or borrowed from Prototype,*/\n/* Oliver Steele\'s Functional, and John Resig\'s Micro-Templating.*/\n/* For all details and documentation:*/\n/* http:/*documentcloud.github.com/underscore*/\n(function() {\n \n    /* 创建一个全局对象, 在浏览器中表示为window对象, 在Node.js中表示global对象*/\n    var root = this;\n \n    /* 保存\"_\"(下划线变量)被覆盖之前的值*/\n    /* 如果出现命名冲突或考虑到规范, 可通过_.noConflict()方法恢复\"_\"被Underscore占用之前的值, 并返回Underscore对象以便重新命名*/\n    var previousUnderscore = root._;\n \n    /* 创建一个空的对象常量, 便于内部共享使用*/\n    var breaker = {};\n \n    /* 将内置对象的原型链缓存在局部变量, 方便快速调用*/\n    var ArrayProto = Array.prototype, /*\n*/    ObjProto = Object.prototype, /*\n*/    FuncProto = Function.prototype;\n \n    /* 将内置对象原型中的常用方法缓存在局部变量, 方便快速调用*/\n    var slice = ArrayProto.slice, /*\n*/    unshift = ArrayProto.unshift, /*\n*/    toString = ObjProto.toString, /*\n*/    hasOwnProperty = ObjProto.hasOwnProperty;\n \n    /* 这里定义了一些JavaScript 1.6提供的新方法*/\n    /* 如果宿主环境中支持这些方法则优先调用, 如果宿主环境中没有提供, 则会由Underscore实现*/\n    var nativeForEach = ArrayProto.forEach, /*\n*/    nativeMap = ArrayProto.map, /*\n*/    nativeReduce = ArrayProto.reduce, /*\n*/    nativeReduceRight = ArrayProto.reduceRight, /*\n*/    nativeFilter = ArrayProto.filter, /*\n*/    nativeEvery = ArrayProto.every, /*\n*/    nativeSome = ArrayProto.some, /*\n*/    nativeIndexOf = ArrayProto.indexOf, /*\n*/    nativeLastIndexOf = ArrayProto.lastIndexOf, /*\n*/    nativeIsArray = Array.isArray, /*\n*/    nativeKeys = Object.keys, /*\n*/    nativeBind = FuncProto.bind;\n \n    /* 创建对象式的调用方式, 将返回一个Underscore包装器, 包装器对象的原型中包含Underscore所有方法(类似与将DOM对象包装为一个jQuery对象)*/\n    var _ = function(obj) {\n        /* 所有Underscore对象在内部均通过wrapper对象进行构造*/\n        return new wrapper(obj);\n    };\n    /* 针对不同的宿主环境, 将Undersocre的命名变量存放到不同的对象中*/\n    if( typeof exports !== \'undefined\') {/* Node.js环境*/\n        if( typeof module !== \'undefined\' && module.exports) {\n            exports = module.exports = _;\n        }\n        exports._ = _;\n    } else {/* 浏览器环境中Underscore的命名变量被挂在window对象中*/\n        root[\'_\'] = _;\n    }\n \n    /* 版本声明*/\n    _.VERSION = \'1.3.3\';\n \n    /* 集合相关的方法(数据和对象的通用处理方法)*/\n    /* --------------------*/\n \n    /* 迭代处理器, 对集合中每一个元素执行处理器方法*/\n    var each = _.each = _.forEach = function(obj, iterator, context) {\n        /* 不处理空值*/\n        if(obj == null)\n            return;\n        if(nativeForEach && obj.forEach === nativeForEach) {\n            /* 如果宿主环境支持, 则优先调用JavaScript 1.6提供的forEach方法*/\n            obj.forEach(iterator, context);\n        } else if(obj.length === +obj.length) {\n            /* 对<数组>中每一个元素执行处理器方法*/\n            for(var i = 0, l = obj.length; i < l; i++) {\n                if( i in obj && iterator.call(context, obj[i], i, obj) === breaker)\n                    return;\n            }\n        } else {\n            /* 对对中每一个元素执行处理器方法*/\n            for(var key in obj) {\n                if(_.has(obj, key)) {\n                    if(iterator.call(context, obj[key], key, obj) === breaker)\n                        return;\n                }\n            }\n        }\n    };\n    /* 迭代处理器, 与each方法的差异在于map会存储每次迭代的返回值, 并作为一个新的数组返回*/\n    _.map = _.collect = function(obj, iterator, context) {\n        /* 用于存放返回值的数组*/\n        var results = [];\n        if(obj == null)\n            return results;\n        /* 优先调用宿主环境提供的map方法*/\n        if(nativeMap && obj.map === nativeMap)\n            return obj.map(iterator, context);\n        /* 迭代处理集合中的元素*/\n        each(obj, function(value, index, list) {\n            /* 将每次迭代处理的返回值存储到results数组*/\n            results[results.length] = iterator.call(context, value, index, list);\n        });\n        /* 返回处理结果*/\n        if(obj.length === +obj.length)\n            results.length = obj.length;\n        return results;\n    };\n    /* 将集合中每个元素放入迭代处理器, 并将本次迭代的返回值作为\"memo\"传递到下一次迭代, 一般用于累计结果或连接数据*/\n    _.reduce = _.foldl = _.inject = function(obj, iterator, memo, context) {\n        /* 通过参数数量检查是否存在初始值*/\n        var initial = arguments.length > 2;\n        if(obj == null)\n            obj = [];\n        /* 优先调用宿主环境提供的reduce方法*/\n        if(nativeReduce && obj.reduce === nativeReduce && false) {\n            if(context)\n                iterator = _.bind(iterator, context);\n            return initial ? obj.reduce(iterator, memo) : obj.reduce(iterator);\n        }\n        /* 迭代处理集合中的元素*/\n        each(obj, function(value, index, list) {\n            if(!initial) {\n                /* 如果没有初始值, 则将第一个元素作为初始值; 如果被处理的是对象集合, 则默认值为第一个属性的值*/\n                memo = value;\n                initial = true;\n            } else {\n                /* 记录处理结果, 并将结果传递给下一次迭代*/\n                memo = iterator.call(context, memo, value, index, list);\n            }\n        });\n        if(!initial)\n            throw new TypeError(\'Reduce of empty array with no initial value\');\n        return memo;\n    };\n    /* 与reduce作用相似, 将逆向迭代集合中的元素(即从最后一个元素开始直到第一个元素)*/\n    _.reduceRight = _.foldr = function(obj, iterator, memo, context) {\n        var initial = arguments.length > 2;\n        if(obj == null)\n            obj = [];\n        /* 优先调用宿主环境提供的reduceRight方法*/\n        if(nativeReduceRight && obj.reduceRight === nativeReduceRight) {\n            if(context)\n                iterator = _.bind(iterator, context);\n            return initial ? obj.reduceRight(iterator, memo) : obj.reduceRight(iterator);\n        }\n        /* 逆转集合中的元素顺序*/\n        var reversed = _.toArray(obj).reverse();\n        if(context && !initial)\n            iterator = _.bind(iterator, context);\n        /* 通过reduce方法处理数据*/\n        return initial ? _.reduce(reversed, iterator, memo, context) : _.reduce(reversed, iterator);\n    };\n    /* 遍历集合中的元素, 返回第一个能够通过处理器验证的元素*/\n    _.find = _.detect = function(obj, iterator, context) {\n        /* result存放第一个能够通过验证的元素*/\n        var result;\n        /* 通过any方法遍历数据, 并记录通过验证的元素*/\n        /* (如果是在迭代中检查处理器返回状态, 这里使用each方法会更合适)*/\n        any(obj, function(value, index, list) {\n            /* 如果处理器返回的结果被转换为Boolean类型后值为true, 则当前记录并返回当前元素*/\n            if(iterator.call(context, value, index, list)) {\n                result = value;\n                return true;\n            }\n        });\n        return result;\n    };\n    /* 与find方法作用类似, 但filter方法会记录下集合中所有通过验证的元素*/\n    _.filter = _.select = function(obj, iterator, context) {\n        /* 用于存储通过验证的元素数组*/\n        var results = [];\n        if(obj == null)\n            return results;\n        /* 优先调用宿主环境提供的filter方法*/\n        if(nativeFilter && obj.filter === nativeFilter)\n            return obj.filter(iterator, context);\n        /* 迭代集合中的元素, 并将通过处理器验证的元素放到数组中并返回*/\n        each(obj, function(value, index, list) {\n            if(iterator.call(context, value, index, list))\n                results[results.length] = value;\n        });\n        return results;\n    };\n    /* 与filter方法作用相反, 即返回没有通过处理器验证的元素列表*/\n    _.reject = function(obj, iterator, context) {\n        var results = [];\n        if(obj == null)\n            return results;\n        each(obj, function(value, index, list) {\n            if(!iterator.call(context, value, index, list))\n                results[results.length] = value;\n        });\n        return results;\n    };\n    /* 如果集合中所有元素均能通过处理器验证, 则返回true*/\n    _.every = _.all = function(obj, iterator, context) {\n        var result = true;\n        if(obj == null)\n            return result;\n        /* 优先调用宿主环境提供的every方法*/\n        if(nativeEvery && obj.every === nativeEvery)\n            return obj.every(iterator, context);\n        /* 迭代集合中的元素*/\n        each(obj, function(value, index, list) {\n            /* 这里理解为 result = (result && iterator.call(context, value, index, list))*/\n            /* 验证处理器的结果被转换为Boolean类型后是否为true值*/\n            if(!( result = result && iterator.call(context, value, index, list)))\n                return breaker;\n        });\n        return !!result;\n    };\n    /* 检查集合中任何一个元素在被转换为Boolean类型时, 是否为true值?或者通过处理器处理后, 是否值为true?*/\n    var any = _.some = _.any = function(obj, iterator, context) {\n        /* 如果没有指定处理器参数, 则默认的处理器函数会返回元素本身, 并在迭代时通过将元素转换为Boolean类型来判断是否为true值*/\n        iterator || ( iterator = _.identity);\n        var result = false;\n        if(obj == null)\n            return result;\n        /* 优先调用宿主环境提供的some方法*/\n        if(nativeSome && obj.some === nativeSome)\n            return obj.some(iterator, context);\n        /* 迭代集合中的元素*/\n        each(obj, function(value, index, list) {\n            if(result || ( result = iterator.call(context, value, index, list)))\n                return breaker;\n        });\n        return !!result;\n    };\n    /* 检查集合中是否有值与目标参数完全匹配(同时将匹配数据类型)*/\n    _.include = _.contains = function(obj, target) {\n        var found = false;\n        if(obj == null)\n            return found;\n        /* 优先调用宿主环境提供的Array.prototype.indexOf方法*/\n        if(nativeIndexOf && obj.indexOf === nativeIndexOf)\n            return obj.indexOf(target) != -1;\n        /* 通过any方法迭代集合中的元素, 验证元素的值和类型与目标是否完全匹配*/\n        found = any(obj, function(value) {\n            return value === target;\n        });\n        return found;\n    };\n    /* 依次调用集合中所有元素的同名方法, 从第3个参数开始, 将被以此传入到元素的调用方法中*/\n    /* 返回一个数组, 存储了所有方法的处理结果*/\n    _.invoke = function(obj, method) {\n        /* 调用同名方法时传递的参数(从第3个参数开始)*/\n        var args = slice.call(arguments, 2);\n        /* 依次调用每个元素的方法, 并将结果放入数组中返回*/\n        return _.map(obj, function(value) {\n            return (_.isFunction(method) ? method || value : value[method]).apply(value, args);\n        });\n    };\n    /* 遍历一个由对象列表组成的数组, 并返回每个对象中的指定属性的值列表*/\n    _.pluck = function(obj, key) {\n        /* 如果某一个对象中不存在该属性, 则返回undefined*/\n        return _.map(obj, function(value) {\n            return value[key];\n        });\n    };\n    /* 返回集合中的最大值, 如果不存在可比较的值, 则返回undefined*/\n    _.max = function(obj, iterator, context) {\n        /* 如果集合是一个数组, 且没有使用处理器, 则使用Math.max获取最大值*/\n        /* 一般会是在一个数组存储了一系列Number类型的数据*/\n        if(!iterator && _.isArray(obj) && obj[0] === +obj[0])\n            return Math.max.apply(Math, obj);\n        /* 对于空值, 直接返回负无穷大*/\n        if(!iterator && _.isEmpty(obj))\n            return -Infinity;\n        /* 一个临时的对象, computed用于在比较过程中存储最大值(临时的)*/\n        var result = {\n            computed : -Infinity\n        };\n        /* 迭代集合中的元素*/\n        each(obj, function(value, index, list) {\n            /* 如果指定了处理器参数, 则比较的数据为处理器返回的值, 否则直接使用each遍历时的默认值*/\n            var computed = iterator ? iterator.call(context, value, index, list) : value;\n            /* 如果比较值相比上一个值要大, 则将当前值放入result.value*/\n            computed >= result.computed && ( result = {\n                value : value,\n                computed : computed\n            });\n        });\n        /* 返回最大值*/\n        return result.value;\n    };\n    /* 返回集合中的最小值, 处理过程与max方法一致*/\n    _.min = function(obj, iterator, context) {\n        if(!iterator && _.isArray(obj) && obj[0] === +obj[0])\n            return Math.min.apply(Math, obj);\n        if(!iterator && _.isEmpty(obj))\n            return Infinity;\n        var result = {\n            computed : Infinity\n        };\n        each(obj, function(value, index, list) {\n            var computed = iterator ? iterator.call(context, value, index, list) : value;\n            computed < result.computed && ( result = {\n                value : value,\n                computed : computed\n            });\n        });\n        return result.value;\n    };\n    /* 通过随机数, 让数组无须排列*/\n    _.shuffle = function(obj) {\n        /* shuffled变量存储处理过程及最终的结果数据*/\n        var shuffled = [], rand;\n        /* 迭代集合中的元素*/\n        each(obj, function(value, index, list) {\n            /* 生成一个随机数, 随机数在<0-当前已处理的数量>之间*/\n            rand = Math.floor(Math.random() * (index + 1));\n            /* 将已经随机得到的元素放到shuffled数组末尾*/\n            shuffled[index] = shuffled[rand];\n            /* 在前面得到的随机数的位置插入最新值*/\n            shuffled[rand] = value;\n        });\n        /* 返回一个数组, 该数组中存储了经过随机混排的集合元素*/\n        return shuffled;\n    };\n    /* 对集合中元素, 按照特定的字段或值进行排列*/\n    /* 相比Array.prototype.sort方法, sortBy方法支持对对象排序*/\n    _.sortBy = function(obj, val, context) {\n        /* val应该是对象的一个属性, 或一个处理器函数, 如果是一个处理器, 则应该返回需要进行比较的数据*/\n        var iterator = _.isFunction(val) ? val : function(obj) {\n            return obj[val];\n        };\n        /* 调用顺序: _.pluck(_.map().sort());*/\n        /* 调用_.map()方法遍历集合, 并将集合中的元素放到value节点, 将元素中需要进行比较的数据放到criteria属性中*/\n        /* 调用sort()方法将集合中的元素按照criteria属性中的数据进行顺序排序*/\n        /* 调用pluck获取排序后的对象集合并返回*/\n        return _.pluck(_.map(obj, function(value, index, list) {\n            return {\n                value : value,\n                criteria : iterator.call(context, value, index, list)\n            };\n        }).sort(function(left, right) {\n            var a = left.criteria, b = right.criteria;\n            if(a ===\n                void 0)\n                return 1;\n            if(b ===\n                void 0)\n                return -1;\n            return a < b ? -1 : a > b ? 1 : 0;\n        }), \'value\');\n    };\n    /* 将集合中的元素, 按处理器返回的key分为多个数组*/\n    _.groupBy = function(obj, val) {\n        var result = {};\n        /* val将被转换为进行分组的处理器函数, 如果val不是一个Function类型的数据, 则将被作为筛选元素时的key值*/\n        var iterator = _.isFunction(val) ? val : function(obj) {\n            return obj[val];\n        };\n        /* 迭代集合中的元素*/\n        each(obj, function(value, index) {\n            /* 将处理器的返回值作为key, 并将相同的key元素放到一个新的数组*/\n            var key = iterator(value, index);\n            (result[key] || (result[key] = [])).push(value);\n        });\n        /* 返回已分组的数据*/\n        return result;\n    };\n    _.sortedIndex = function(array, obj, iterator) {\n        iterator || ( iterator = _.identity);\n        var low = 0, h