INSERT INTO `demo` VALUES (541, 00000000292, 1, 0, 'html', 'ng-class', '关键词', '1.{red:isred==5,border:isborder==6}  //大括号的方式，类名无需加引号，后面的是变量或者是表达式\n2.{5:\'red\',6:\'border\'}[toggle]  //花括号+中括号，适合同一个样式的两个形态，样式名必须加引号，中括号里面是变量或者表达式', '<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myapp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"jquery.js\"></script>\n    <script src=\"angular.min.js\"></script>\n    <style>\n        .red{background: red}\n        .border{border:5px dashed green;}\n    </style>\n</head>\n<body ng-controller =\"mycontroller\">\n<div ng-class=\"{red:isred==5,border:isborder==6}\" style=\"width:200px;height:200px\"></div>\n<div ng-class=\"{5:\'red\',6:\'border\'}[toggle]\" style=\"width:200px;height:200px\"></div>\n<script>\n    var app = angular.module(\"myapp\",[]);\n    app.controller(\"mycontroller\",function($scope){\n        $scope.isred=5;\n        $scope.isborder=6;\n        $scope.toggle=6;\n    });\n</script>\n</body>\n</html>', NULL, '2016-4-28 12:47:19', '2016-4-28 12:49:21', 0, 0);
INSERT INTO `demo` VALUES (542, 00000000292, 1, 0, 'html', 'ng-checked/ng-change/ng-model', '关键词', '多个参数控制，略显麻烦，ng-model 在等于value的时候，ng-checked=\"true\"\n同样，当设置ng-checked=\"true\"的时候，value有一个值，那么ng-model绑定的变量就等于这个value值', '<input  type=\"radio\"   name=\"searchType\" ng-change=\"conf()\" ng-model=\"flighttype\" value=\"wf\" ng-checked=\"true\">', NULL, '2016-4-28 21:18:51', '2016-4-28 21:21:26', 0, 0);
