INSERT INTO `demo` VALUES (544, 00000000543, 1, 0, 'js', '安装', '关键词', '', 'cd C:\\Program Files\\nodejs\nnpm -v\nnpm install express -g\nnpm config set prefix \"C:\\Program Files\\nodejs\"\nnpm config set cache \"C:\\Program Files\\nodejs\\cache\"\nnpm install -g express-generator\nexpress  myapp\ncd myapp\nnpm install\nnpm start\nhttp://localhost:3000/\nnpm stop\nnpm install socket.io\nnode server.js\n\n  ', NULL, '2016-5-2 00:52:59', '2016-5-23 12:48:56', 0, 0);
INSERT INTO `demo` VALUES (545, 00000000329, 1, 0, 'html', 'websocket客户端', '关键词', '.onopen、.onclose、.onmessage、.onerror、.send', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n    <title>Ssocket</title>\n    <script type=\"text/javascript\" src=\"https://cdn.socket.io/socket.io-1.4.5.js\"></script>\n</head>\n\n<body>\n<input type=\"text\" id=\"myinput\">\n<button onclick=\"send()\">发送消息</button>\n    <script type=\"text/javascript\">\n    function send(){\n        var val = document.getElementById(\"myinput\").value;\n        socket.emit(\'news\', { data:val});\n        console.log(\"emit:\"+val);\n    }\n      var socket = io.connect(\'http://222.132.50.11:3000/\');     \n      socket.on(\'news\', function (data) {    \n        console.log(data.data);\n      });\n    </script>\n    \n</body>\n</html>', NULL, '2016-5-2 22:33:21', '2016-5-3 00:04:53', 0, 0);
INSERT INTO `demo` VALUES (546, 00000000329, 1, 0, 'js', 'websocket服务端', '关键词', '服务端还可以是：faye-websocket-node：github: https://github.com/faye/faye-websocket-node', '\nvar app = require(\'http\').createServer(handler), \n    io = require(\'socket.io\').listen(app), \n    fs = require(\'fs\')\n\napp.listen(3000,function(){\n    console.log(\"3000port\");\n});\nio.set(\'log level\', 1);//将socket.io中的debug信息关闭\n\nfunction handler (req, res) {\n  fs.readFile(__dirname + \'/index.html\',function (err, data) {  \n    if (err) {\n      res.writeHead(500);\n      return res.end(\'Error loading index.html\');\n    }    \n    res.writeHead(200, {\'Content-Type\': \'text/html\'});    \n    res.end(data);\n  });\n}\n\nio.sockets.on(\'connection\', function (socket) {\n    var count = 0;\n    var server=\"\";\n    setInterval(function(){\n        socket.emit(\'news\', { data: server+count });\n        count++;\n    },1000);\n    socket.on(\'news\', function (data) {\n      server=data.data;\n      console.log(data.data);\n    });\n});\n//==========================\n// var app = require(\'express\')();\n// var http = require(\'http\').Server(app);\n// var io = require(\'socket.io\')(http);\n\n// app.get(\'/\', function(req, res){\n//     res.send(\'<h1>Welcome Realtime Server</h1>\');\n// });\n\n// http.listen(3000, function(){\n//     console.log(\'listening on *:3000\');\n// });\n//==================\n// var http = require(\"http\"),\n//     io = require(\"socket.io\");\n \n// // Create HTTP server\n// var server = http.createServer(function(request, response) {\n//     response.writeHead({ \"Content-Type\": \"text/html\" });\n//     response.end(\"HTML5 WebSocket Demo\");\n// });\n// server.listen(3001, \"ok.94007.com\");\n \n// // Wrap HTTP server by socket.io\n// var socket = io.listen(server);\n// socket.on(\"connection\", function(client) {\n//     console.log(\"connected\");\n \n//     client.on(\"message\", function(data) {\n//         client.send(\"Hello \" + data);\n//     });\n \n//     client.on(\"disconnect\", function() {\n//         console.log(\"disconnected\");\n//     });\n// });\n//============================', NULL, '2016-5-3 00:05:12', '2016-5-3 00:08:50', 0, 0);
