INSERT INTO `demo` VALUES (548, 00000000292, 1, 0, 'js', '$routeProvider', '关键词', '', 'demoApp.config([\'$routeProvider\',function($routeProvider) {  \n$routeProvider.when(\'/list\', {  \ntemplateUrl: \'route/list.html\',  \n  controller: \'routeListController\'\n}).when(\'/list/:id\', {  \n  templateUrl: \'route/detail.html\',\n   controller: \'routeDetailController\'\n  }).otherwise({  \n        redirectTo: \'/list\'  \n     });  \n}]);', NULL, '2016-5-4 08:48:01', '2016-5-4 08:48:23', 0, 0);
