INSERT INTO `demo` VALUES (550, 00000000172, 1, 0, 'js', '$.grep()', '关键词', '', '\n        $scope.cityfilter = function(str){\n          var speelREG = new RegExp(\"^\"+str,\"i\");\n          var airPlaneCodeREG = new RegExp(\"^\"+str+\"|,str\");\n          return $.grep(myCityArr,function(f){\n            return speelREG.test(f.spell)||airPlaneCodeREG.test(f.airPlaneCode)||f.name.indexOf(str)!=-1\n          });\n        }', NULL, '2016-5-4 13:42:56', '2016-5-4 13:43:02', 0, 0);
INSERT INTO `demo` VALUES (551, 00000000172, 1, 0, 'js', '$.fn.serialize()', '关键词', '序列化表单， [ˈsɪəriəlaɪz] ；序列化', '$(\"form\").serialize();//\"tourCode=werwer&beginDate=2016-05-05&endDate=2016-05-13&fromCityCode=110100&toCityCode=310100&teamCountry%5B%5D=AE&peopleNum%5B%5D=2&teamCountry%5B%5D=AM&peopleNum%5B%5D=3\"', NULL, '2016-5-4 19:48:16', '2016-5-4 19:49:35', 0, 0);
INSERT INTO `demo` VALUES (552, 00000000400, 1, 0, 'html', 'page页码指令', '关键词', '使用：在scope上面写一个page对象，然后随意操作page对象即可', '<!DOCTYPE html>\n<html lang=\"en\" ng-app=\"myapp\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script src=\"jquery.js\"></script>\n    <script src=\"angular.min.js\"></script>\n</head>\n<body ng-controller =\"myctrl as ctrl\">\n    <div lbpage ></div>\n    <button ng-click=\"nextpage()\">下一页</button>\n    <script type=\"text/javascript\">\n        var app = angular.module(\"myapp\",[]);\n        app.directive(\"lbpage\",function($compile){\n            return {\n                restrict:\"A\",\n                link:function mylink(scope,element,attr) {\n                    element.html(makePage(scope.page.pageCount,scope.page.curIndex,scope.page.pageLimit));\n                    scope.$watch(\"page\",function(newValue, oldValue, scope){\n                        element.html($compile(makePage(scope.page.pageCount,scope.page.curIndex,scope.page.pageLimit))(scope));\n                    },true);\n                    function makePage(pageCount, curIndex, pageLimit) { //总页，当前页\n                      var pageCount = parseInt(pageCount);\n                      var curIndex = parseInt(curIndex) || 1;\n                      var pageLimit = parseInt(pageLimit) || 10; //默认10;\n                      var pageArr = [\n                      ];\n                      var pagePlaceHolder = \'<span class=\"page-placeholder\">…</span>\';\n                      if (pageCount > pageLimit) {\n                        if (pageCount - curIndex < pageLimit - 4) { //缩头 1。。 34567891011\n                          // console.log(\"缩头路线\");\n                          for (var i = 0; i < pageLimit - 2; i++) { //倒数\n                            pageArr.push(getPageNumHtml(pageCount - i));\n                          }\n                          pageArr.reverse();\n                          pageArr.unshift(pagePlaceHolder);\n                          pageArr.unshift(getPageNumHtml(1));\n                        } else if (curIndex < pageLimit - 4) { //缩尾     123456789  。。100\n                          // console.log(\"缩尾路线\");\n                          for (var i = 1; i < pageLimit - 2; i++) { //倒数\n                            pageArr.push(getPageNumHtml(i));\n                          }\n                          pageArr.push(pagePlaceHolder);\n                          pageArr.push(getPageNumHtml(pageCount));\n                        } else { //双缩1。。     3456789     。。100\n                          // console.log(\"双缩路线\");\n                          pageArr.push(getPageNumHtml(1));\n                          pageArr.push(pagePlaceHolder);\n                          for (var i = curIndex - (pageLimit - 4) / 2; i < curIndex + (pageLimit - 4) / 2 + 1; i++) {\n                            pageArr.push(getPageNumHtml(i));\n                          }\n                          pageArr.push(pagePlaceHolder);\n                          pageArr.push(getPageNumHtml(pageCount));\n                        }\n                        $html = $(pageArr.join(\'\'));\n                        $html.filter(function () {\n                          return $(this).text() == curIndex;\n                        }).addClass(\'cur\');\n                        return $html;\n                      }\n                    }\n                    scope.changepage = function(n){\n                      scope.page.curIndex = n;\n                    }\n                    function getPageNumHtml(n){\n                      return \'<a href=\\\"javascript:;\\\" ng-click = \\\"changepage(\'+n+\')\\\">\'+n+\'</a>\';\n                    }\n                }\n            }\n        });\n        app.controller(\"myctrl\",function($scope,$filter){\n            $scope.page = {pageCount:20,curIndex:1,pageLimit:10};\n        });\n    </script>\n</body>\n</html>', NULL, '2016-5-5 01:12:22', '2016-5-5 16:26:47', 0, 0);
