INSERT INTO `demo` VALUES (555, 00000000272, 1, 0, 'js', 'mydatequeue1.0', '关键词', '', 'function calendarqueue(setting){\n        var dayStrArr = [\"周日\",\"周一\",\"周二\",\"周三\",\"周四\",\"周五\",\"周六\"];\n        var monthStrArr = [\"Jan\",\"Feb\",\"Mar\",\"Apr\",\"May\",\"Jun\",\"Jul\",\"Aug\",\"Sep\",\"Oct\",\"Nov\",\"Dec\"];\n        //原点时间\n        var origindatetime =typeof(setting.origindate)==\"undefined\"?new Date(dateFormatSlash(new Date())):new Date(dateFormatSlash(setting.origindate));\n        // var currentMonth = new Date();\n        var monthWidth = 140;\n        var showdatetime = new Date(origindatetime.getTime());\n        goDate(origindatetime);//入口\n        $(\"#rightarrow\").unbind(\"click\").click(function(){//右箭头  UL向左移动1个日历宽度\n            $(\"#fs_dateprice\").stop(true,true);\n            var nowLeft = $(\"#fs_dateprice\").position().left;\n            //算出天数差\n            var clone_origin = new Date(origindatetime.getTime());\n            clone_origin.setDate(clone_origin.getDate()-parseInt(nowLeft/monthWidth));\n            clone_origin.setDate(clone_origin.getDate()+7);\n            var newDate = new Date(clone_origin.getTime());//这里记录时间，换算成预加载的时间差dom完毕后发送请求\n            newDate.setDate(newDate.getDate()+7);\n            var start = dateFormatMinus(newDate);\n            newDate.setDate(newDate.getDate()+7);\n            var end = dateFormatMinus(newDate);\n            var i = 0;\n            do{\n            makeDate(clone_origin);\n            clone_origin.setDate(clone_origin.getDate()+1);\n            i++\n            }while(i<13);\n            sendForPrice(start,end);//请求price\n            //新的7天生成完毕\n            showdatetime.setDate(showdatetime.getDate()+7);\n            slideToDate(showdatetime);\n        });\n        $(\"#leftarrow\").unbind(\"click\").click(function(){//左箭头  UL向右移动1个日历宽度\n            $(\"#fs_dateprice\").stop(true,true);\n            var nowLeft = $(\"#fs_dateprice\").position().left;\n            //算出天数差\n            var clone_origin = new Date(origindatetime.getTime());\n            clone_origin.setDate(clone_origin.getDate()-parseInt(nowLeft/monthWidth));\n            clone_origin.setDate(clone_origin.getDate()-1);\n            var i = 0;\n            do{\n            makeDate(clone_origin);\n            clone_origin.setDate(clone_origin.getDate()-1);\n            i++\n            }while(i<13);\n            // $(\"#fs_dateprice\").animate({\"left\": nowLeft+monthWidth*7});\n            showdatetime.setDate(showdatetime.getDate()-7);\n            slideToDate(showdatetime);\n        });\n        function slideToDate(datetime){\n            // console.log(\"定位到\"+datetime);\n            var left = $(\"#\"+dateFormatMinus(datetime)).position().left;\n            $(\"#fs_dateprice\").animate({\"left\": 0-left});\n        }\n        //点选队列标记未active\n        // $(\"#fs_dateprice\").on(\"click\",\"li.hasprice\",function(){\n        $(\"#fs_dateprice\").off(\"click\").on(\"click\",\"li\",function(){\n            var datetime = $(this).data(\"data-date\");\n            setting.callback(datetime);\n            // goDate(datetime);\n        });\n        function goDate(targetDate) {//参数为时间对象\n            //ajax数据请求\n            targetDate  = new Date(dateFormatSlash(targetDate));//刷新重置\n            var id = dateFormatMinus(targetDate);\n            var targetDom = $(\"#fs_dateprice\").find(\"#\" + id);\n            if(targetDom.size()==0){\n                makeDate(targetDate);//生成这一天\n                targetDom = $(\"#fs_dateprice\").find(\"#\" + id);\n            }\n            var targetLeft = targetDom.position().left;\n            // $(\"#fs_dateprice\").stop().animate({\"left\": 0 - targetLeft}, 400);\n            targetDom.addClass(\"active\").siblings().removeClass(\"active\");//标记！\n            var newdate = new Date(targetDate.getTime());\n            //预加载14天\n            var start = dateFormatMinus(newdate);\n            for(var i=1;i<=13;i++){\n                newdate.setDate(newdate.getDate() +1);\n                makeDate(newdate);\n            }\n            var end = dateFormatMinus(newdate);\n            // 生成之后去后台取一次数据\n            sendForPrice(start,end);//请求price\n        }\n        function makeDate(thisdate){\n            if($(\"#fs_dateprice\").find(\"#\" + dateFormatMinus(thisdate)).size()>0){//生成月份的重复检查\n                return false;\n            }\n            var thisdate  = new Date(dateFormatSlash(thisdate));//刷新重置\n            //left\n            var left = getGapDate(thisdate)*monthWidth;\n            //day\n            var day = dayStrArr[thisdate.getDay()];\n            //month\n            var month = thisdate.getMonth()+1;\n            //date\n            var date = thisdate.getDate();\n            //price\n            var tpl =\"\";\n            tpl += \"<li style=\\\"left:\"+left+\"px\\\" id=\\\"\"+dateFormatMinus(thisdate)+\"\\\">\";\n            tpl += \"    <div class=\\\"queue-date-box\\\">\";\n            tpl += \"        <span class=\\\"span1\\\">no seats</span>\";\n            tpl += \"        <span class=\\\"span2\\\">\"+month+\"-\"+date+\"<br>\"+day+\"</span>\";\n            tpl += \"    </div>\";\n            tpl += \"</li>\";\n            var $tpl = $(tpl);\n            $tpl.data(\"data-date\",thisdate);\n            $tpl.click(dateclick);\n            $(\"#fs_dateprice\").append($tpl);\n        }\n        function dateclick(){\n            $(this).addClass(\"active\").siblings().removeClass(\"active\");\n        }\n        function getGapMonth(thisdate){//宽度X月数差距\n            return ((thisdate.getYear() * 12 + thisdate.getMonth()) - (origindatetime.getYear() * 12 + origindatetime.getMonth())) * monthWidth;\n        }\n        function getGapDate(thisdate){//宽度X月数差距\n            return (thisdate.getTime()-origindatetime.getTime())/(24*60*60*1000);\n        }\n        function dateFormatMinus(datetime){\n            var month = datetime.getMonth()+1;\n            month = month>9?month:\"0\"+month;\n            var date = datetime.getDate();\n            date = date>9?date:\"0\"+date;\n            return datetime.getFullYear()+\"-\"+month+\"-\"+date;\n        }\n        function dateFormatSlash(datetime){\n            var month = datetime.getMonth()+1;\n            month = month>9?month:\"0\"+month;\n            var date = datetime.getDate();\n            date = date>9?date:\"0\"+date;\n            return datetime.getFullYear()+\"/\"+month+\"/\"+date;\n        }\n        function hasData(){\n            $(\"#emp_flight\").addClass(\"hide\");\n            $(\"#sm_right\").removeClass(\"hide\");\n        }\n        function noData(){\n            $(\"#sm_right\").addClass(\"hide\");\n            $(\"#emp_flight\").removeClass(\"hide\");\n        }\n        function sendForPrice(start,end){\n            $.get(setting.getPriceURL,{start:start,end:end},function(data){\n                parseDatePrice(data.match(/\"HashMap\":{([^\\{\\}]*)}/)[1]);\n            });\n        }\n        function parseDatePrice(str){//假想数据格式\"2016-05-01\":\"900.0\",\"2016-05-02\":\"400.0\"\n            if(str==\"\")return;\n            var dateArr = str.replace(/\\\"/g,\"\").split(\",\");\n            $.each(dateArr,function(n,f){\n                var strArr = f.split(\":\");\n                $(\"#fs_dateprice\").find(\"#\"+strArr[0]+\" .span1\").text(\"￥\"+strArr[1]);\n            });\n        }\n    }\n    \n            // calendarqueue({\n            //   origindate:new Date(startdate),\n            //   // getPriceURL:\"${link.contextPath}/es/flightPrice/flightNo/searchMinPriceHead.do?flightNo=G1234\"\n            //   getPriceURL:\"${link.contextPath}/es/flightPrice/flightNo/searchMinPriceHead.do?\"+$.param(obj),\n            //   callback:function(datetime){//点击日历上的日期将触发：\n            //     // 1.修改静态时间\n            //     $scope.searchForm.actiontime = $filter(\"date\")(datetime,\"yyyy-MM-dd\");\n            //     $scope.searchForm.lockqueue = true;\n            //     console.log(\"时间调整为:\"+$scope.searchForm.actiontime);\n            //     // 2.使用静态数据刷新\n            //     $scope.search();\n            //   }\n            // });', NULL, '2016-5-7 11:48:30', '2016-5-7 11:48:36', 0, 0);
INSERT INTO `demo` VALUES (556, 00000000163, 1, 0, 'js', 'input自定义输入限制', '关键词', '$(\'input\').on(\'input propertychange\', function (e) {\n  this.value = this.value.replace(/[^\\x00-\\xff]/g,\"\");\n});', '  var rep = /(^\\d+)|(^[a-zA-Z\\s]+)/;\n $(\"input\").on(\"input propertychange\",function(e){\n var _this = this;\n this.value.replace(rep,function($1,$2,$3){\n if($2) {_this.value = $2;}\n if($3) {_this.value = $3;}\n  })\n});\n\n低版本的`jquery:\n $($0).bind(\"input propertychange\",function(e){\n var _this = this;\n   _this.value=\"1\";\n});', NULL, '2016-5-7 18:22:49', '2016-6-14 17:08:05', 0, 0);
INSERT INTO `demo` VALUES (557, 00000000292, 1, 0, 'js', 'filter|date', '关键词', '', '本地化日期格式化：\n({{ today | date:\'medium\' }})Feb 15, 2016 10:17:57 PM\n({{ today | date:\'short\' }})2/15/16 10:17 PM\n({{ today | date:\'fullDate\' }})Monday, February 15, 2016\n({{ today | date:\'longDate\' }})February 15, 2016\n({{ today | date:\'mediumDate\' }})Feb 15, 2016\n({{ today | date:\'shortDate\' }})2/15/16\n({{ today | date:\'mediumTime\' }})10:17:57 PM\n({{ today | date:\'shortTime\' }})10:17 PM\n年份格式化：\n四位年份：({{ today | date:\'yyyy\' }})2016\n两位年份：({{ today | date:\'yy\' }})16\n一位年份：({{ today | date:\'y\' }})2016\n月份格式化：\n英文月份：({{ today | date:\'MMMM\' }})February\n英文月份简写：({{ today | date:\'MMM\' }})Feb\n两位数字月份：({{ today | date:\'MM\' }})02\n一年中的第几个月份：({{ today | date:\'M\' }})2\n日期格式化：\n数字日期：({{ today | date:\'dd\' }})15\n一个月中的第几天：({{ today | date:\'d\' }})15\n英文星期：({{ today | date:\'EEEE\' }})Monday\n英文星期简写：({{ today | date:\'EEE\' }})Mon\n小时格式化：\n24小时制数字小时：({{ today | date:\'HH\' }})22\n一天中的第几个小时：({{ today | date:\'H\' }})22\n12小时制数字小时：({{ today | date:\'hh\' }})10\n上午或下午的第几个小时：({{ today | date:\'h\' }})10\n分钟格式化：\n数字分钟数：({{ today | date:\'mm\' }})17\n一个小时中的第几分钟：({{ today | date:\'m\' }})17\n秒数格式化：\n数字秒数：({{ today | date:\'ss\' }})57\n一分钟中内的第几秒：({{ today | date:\'s\' }})57\n毫秒数格式化：\n毫秒数：({{ today | date:\'sss\' }})649\n字符格式化：\n上下午标识：({{ today | date:\'a\' }})PM\n四位时区标识：({{ today | date:\'Z\' }})+0800\n自定义日期格式化：\n年月日：({{ today | date:\'yyyy-MM-dd\' }})2016-02-15\n时分秒：({{ today | date:\'HH:mm:ss.sss\' }})22:17:57.649', NULL, '2016-5-10 08:39:33', '2016-5-17 12:28:03', 0, 0);
