INSERT INTO `demo` VALUES (562, 00000000292, 1, 0, 'html', 'ng-template', '关键词', '', '<script type=\"text/ng-template\" id = \"addtourcountry\">\n<dd class=\"cf\">\n    <span class=\"tour-input-wrap\">\n        <input type=\"text\" class=\"countryselect\" lbcountry />\n        <input type=\"hidden\" name=\"teamCountry[]\" />\n    </span><span class=\"tour-input-wrap2\"><font color=\"red\">*</font></span>\n    <div class=\"cf tour-input-wrap2 cf\">\n        <i class=\"fl\">人数</i>\n        <input type=\"hidden\" value=\"1\" name = \"peopleNum[]\"/>\n        <div class=\"count_div fl cf\">\n            <span class=\"fl reduce_span\">-</span>\n            <input class=\"fl lb-num\" type=\"text\" value=\"1\">\n            <span class=\"fl add_span\">+</span>\n        </div>\n    </div>\n</dd>\n</script>', NULL, '2016-5-17 11:44:20', '2016-5-17 12:26:59', 0, 0);
INSERT INTO `demo` VALUES (563, 00000000163, 1, 0, 'html', '百度地图api', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <script type=\"text/javascript\" src=\"http://api.map.baidu.com/api?v=2.0&ak=fHStIi8vm3YZBUIt4mzMWOylR5WmfEZe\"></script>\n    <script src=\"http://www.laibatour.com/statics/js/jquery.js\"></script>\n</head>\n<body>\n<div id=\"laibamap\" style=\"width:600px;height:400px\"></div>\n<script type=\"text/javascript\">\nvar map = new BMap.Map(laibamap);          // 创建地图实例\nvar point = new BMap.Point(116.404,39.915);  // 创建点坐标\nmap.centerAndZoom(point, 15);               // 初始化地图，设置中心点坐标和地图级别\n// map.addControl(new BMap.NavigationControl());//默认左上角控件\n// map.addControl(new BMap.ScaleControl());//标尺比例\n// map.addControl(new BMap.MapTypeControl());//卫星。三维的切换控制\n// map.addControl(new BMap.NavigationControl({\"anchor\":BMAP_ANCHOR_TOP_LEFT}));//位置\n// map.addControl(new BMap.NavigationControl({\"anchor\":BMAP_ANCHOR_TOP_RIGHT}));\n// map.addControl(new BMap.NavigationControl({\"anchor\":BMAP_ANCHOR_BOTTOM_LEFT}));\n// map.addControl(new BMap.NavigationControl({\"anchor\":BMAP_ANCHOR_BOTTOM_RIGHT}));\n// map.addControl(new BMap.NavigationControl({\"type\":BMAP_NAVIGATION_CONTROL_LARGE}));//外形\n// map.addControl(new BMap.NavigationControl({\"type\":BMAP_NAVIGATION_CONTROL_SMALL}));\n// map.addControl(new BMap.NavigationControl({\"type\":BMAP_NAVIGATION_CONTROL_PAN}));\n// map.addControl(new BMap.NavigationControl({\"type\":BMAP_NAVIGATION_CONTROL_ZOOM}));\n// map.addControl(new BMap.OverviewMapControl());  //添加折叠的缩略图\n// map.setCurrentCity(\"北京\");//没看懂\nfunction showmap(id,x,y,z){\n    var x = x||116.404;\n    var y = y||39.915;\n    var z = z||15;\n    $(\"body\").append(\"<div id=\\\"\"+id+\"\\\" style=\\\"width:300px;height:300px\\\"></div>\");\n    var map = new BMap.Map(id);          // 创建地图实例\n    var point = new BMap.Point(x, y);  // 创建点坐标\n    map.centerAndZoom(point, z);                 // 初始化地图，设置中心点坐标和地图级别\n}\n// function showmap(x,y){\n//     if(typeof(x)==\"undefined\"||typeof(y)==\"undefined\")return false;\n//     if($(\"#laiba_map_wrap\").size()==0){\n//         var tpl = \"\";\n//         tpl += \'<div id=\\\"laiba_map_wrap\\\" class=\\\"laiba-map-wrap\\\">\';\n//         tpl += \'  <div id=\\\"laiba_map\\\" class=\\\"laiba-map\\\"></div>\';\n//         tpl += \'</div>\';\n//         $(\"body\").append(tpl);\n//     }\n//     var map = new BMap.Map(\"laiba_map\");          // 创建地图实例\n//     var point = new BMap.Point(x, y);  // 创建点坐标\n//     map.centerAndZoom(point, 15);\n// }\n</script>\n</body>\n</html>', NULL, '2016-5-17 23:55:06', '2016-5-17 23:55:16', 0, 0);
INSERT INTO `demo` VALUES (564, 00000000163, 1, 0, 'js', '弹出式百度地图', '关键词', '', '\n/*地图*/\n.laiba-map-wrap{position:fixed;top:0;left:0;bottom:0;right:0;background-color:rgba(0,0,0,.5);display:none;z-index:999999;}\n.laiba-map{width:600px;height:400px;background-color:#fff;top:50%;left:50%;position:absolute;margin-left:-300px;margin-top:-200px}\n.laiba-map-close{font-size: 30px;color:#fff;position: absolute;top: 4px;right: 4px;z-index: 1;width: 30px;height: 30px;background: rgba(0,0,0,.5);line-height: 25px;text-align: center;border-radius: 50%;cursor: pointer;}\n.laiba-map-close:hover{color:red}\n.laiba-map-innerwrap{width:600px;height:400px;}\n        ctrl.showmap = function(x,y){\n            if(typeof(x)==\"undefined\"||typeof(y)==\"undefined\")return false;\n            if($(\"#laiba_map_wrap\").size()==0){\n                var tpl = \"\";\n                tpl += \'<div id=\\\"laiba_map_wrap\\\" class=\\\"laiba-map-wrap\\\">\';\n                tpl += \'  <div id=\\\"laiba_map\\\" class=\\\"laiba-map\\\">\';\n                tpl += \'     <span class = \"laiba-map-close\">&times;</span>\';\n                tpl += \'     <div class=\\\"laiba-map-innerwrap\\\" id=\\\"laiba_map_innerwrap\\\">\';\n                tpl += \'     </div>\';\n                tpl += \'  </div>\';\n                tpl += \'</div>\';\n                tpl = $(tpl);\n                tpl.find(\".laiba-map-close\").click(function(){\n                    tpl.hide();\n                });\n                $(\"body\").append(tpl);\n            }else{\n                $(\"#laiba_map_innerwrap\").empty();\n            }\n            $(\"#laiba_map_wrap\").show();\n            var map = new BMap.Map(\"laiba_map_innerwrap\");          // 创建地图实例\n            map.centerAndZoom(new BMap.Point(x, y), 15);\n        }', NULL, '2016-5-17 23:55:06', '2016-5-17 23:56:32', 0, 0);
