INSERT INTO `demo` VALUES (572, 00000000571, 1, 0, 'js', '基本', '关键词', '描述', 'npm access //--\nnpm add-user //--\nnpm adduser //--\nnpm apihelp //--\nnpm author //--\nnpm bin //--\nnpm bugs //--\nnpm c //--\nnpm cache //--\nnpm completion //--\nnpm config //--\nnpm ddp //--\nnpm dedupe //--\nnpm deprecate //--\nnpm dist-tag //--\nnpm dist-tags //--\nnpm docs //--\nnpm edit //--\nnpm explore //--\nnpm faq //--\nnpm find //--\nnpm find-dupes //--\nnpm get //--\nnpm help //--\nnpm help-search //--\nnpm home //--\nnpm i //--\nnpm info //--\nnpm init //--\nnpm install //--\nnpm issues //--\nnpm la //--\nnpm link //--\nnpm list //--\nnpm ll //--\nnpm ln //--\nnpm login //--\nnpm logout //--\nnpm ls //--\nnpm outdated //--\nnpm owner //--\nnpm pack //--\nnpm ping //--\nnpm prefix //--\nnpm prune //--\nnpm publish //--\nnpm r //--\nnpm rb //--\nnpm rebuild //--\nnpm remove //--\nnpm repo //--\nnpm restart //--\nnpm rm //--\nnpm root //--\nnpm run-script //--\nnpm s //--\nnpm se //--\nnpm search //--\nnpm set //--\nnpm show //--\nnpm shrinkwrap //--\nnpm star //--\nnpm stars //--\nnpm start //--\nnpm stop //--\nnpm t //--\nnpm tag //--\nnpm team //--\nnpm test //--\nnpm tst //--\nnpm un //--\nnpm uninstall //--\nnpm unlink //--\nnpm unpublish //--\nnpm unstar //--\nnpm up //--\nnpm update //--\nnpm upgrade //--\nnpm v //--\nnpm version //--\nnpm view //--\nnpm whoami //--\n', NULL, '2016-5-20 17:16:24', '2016-5-27 11:01:54', 0, 0);
