INSERT INTO `demo` VALUES (586, 00000000360, 1, 0, 'js', 'sublime text csslint', '关键词', '1.安装node.js\n2.安装csslint，jshint\n3.安装sublimelinter\n4sublimelinter-csslint，安装。\n5sublimelinter-jshint，安装。', '新数据', NULL, '2016-5-22 12:49:31', '2016-5-22 15:42:02', 0, 0);
INSERT INTO `demo` VALUES (587, 00000000360, 1, 0, 'js', 'webstorm快捷键', '关键词', '1.换行：File -> settings -> Editor-->general--> “Use Soft Wraps in editor”\n2.同文件切为两屏：右键文件标签 -> spilt vertically(左右两屏)或者spilt horizontally(上下两屏)\n3. 代码上右键选择localhistory，可以查看代码所有的改动', 'ctrl+d//复制当前行\nctrl+shift+alt+N       //通过一个字符快速查找位置（必记）\nctrl+shift+N           //通过文件名快速查找工程内的文件（必记）\nctrl+F              //在文件内快速查找代码\nF2    //多个警告之间切换，alt+enter打开警告，enter执行默认处理，非常方便\nF3                  //查找下一个\nshift+F3              //查找上一个\nctrl+R               //文件内代码替换\nctrl+shift+R           //范围内替换\nctrl+shift+F        //范围内查找\nctrl+]/[   //方法块的最前与最后\nalt+up/down  //上一个方法、下一个方法\nctrl+G  //到达指定行\nalt+F1  //倒数show in explor打开当前文件所在的文件夹，必用\nesc //光标移动到编辑区域\nctrl + Y //删除当前行\nctrl+ alt +L   //格式化代码\nalt + insert //新建文件\nalt  + 1234//调整界面展示更多控制模块\nalt+←/→ //左右切换文件\nctrl + F4 //关闭当前标签页面\nalt+j //相当于sb的ctrl+d，\nalt + shift +j//不小心选多了，撤销最后一个选择，折回\nalt + 鼠标左键  //激活多处光标\nctrl+z/ctrl+shift +Z   //撤销与取消撤销\nshift+enter  //无论何处，新开一行\nctrl+shift+enter//单行css变多行\nctrl + 左键点，//跳转至变量或函数声明处\nctrl + j//输出模板，如何自定义模版呢\nshift + f6 //全局重构\nctrl + shift +j //合并下一行到本行\nctrl + shift +a //全局搜索应用，搜索“Recognized File Types”，在html中添加vm，tpl等\n', NULL, '2016-5-22 22:55:09', '2016-6-21 14:55:28', 0, 0);
