INSERT INTO `demo` VALUES (593, 00000000588, 1, 0, 'js', '生成结构/demo', '关键词', '定位到目标文件夹下敲命令', '新目录结构：\njdf install init xxx\n比较简单，生成简单的空文件夹\n注1：json文件不允许有注释，单双引号使用时也需要统一 注\n2：windows7下在当前文件夹打开命令行的方法：Shift+鼠标右键，选择\"在此处打开命令窗口\" 注\n3：windows下CMD路径常用操作如下\nC:\\Documents and Settings\\Administrator>d: //C盘进入D盘\nC:\\Documents and Settings\\Administrator>cd xxx //进行C盘xxx目录\nC:\\Documents and Settings\\Administrator\\xxx>cd .. //返回上一层目录      \n生成测试demo：\njdf install demo\njdf release', NULL, '2016-5-23 13:17:55', '2016-5-27 14:40:33', 0, 0);
INSERT INTO `demo` VALUES (594, 00000000566, 1, 0, 'js', '配置', '关键词', '描述', '新代码', NULL, '2016-5-23 13:30:33', '2016-5-23 13:30:33', 0, 0);
INSERT INTO `demo` VALUES (595, 00000000594, 1, 0, 'js', 'config.json', '关键词', 'jspn', 'config.json需要放在当前项目的根目录下, 详细配置如下：\n\"projectPath\": null,// - 工程目录前缀\n例如下面一段sass代码，经过jdf output之后，会在background中加上projectPath，用来标识这张图片的项目地址。\n.list{\nbackground: url(i/icon.png);\n}\n.list{background:url(http://misc.360buyimg.com/Test/widget/w1/i/icon.png)}\n\"host\": null,// - 远端机器IP\n\"user\": null,// - 远端机器user\n\"password\": null,// - 远端机器password\n\"baseDir\": \"\",// - 静态文件名称\n\"cssDir\": \"css\",// - css文件夹名称\n\"imagesDir\": \"css/i\",// - images文件夹名称\n\"jsDir\": \"js\",// - js文件夹名称\n\"htmlDir\": \"html\",// - html文件夹名称\n\"widgetDir\": \"widget\",// - widget文件夹名称\n\"buildDirName\": \"html\",// - 编译的html文件夹名称\n\"outputDirName\": \"build\",// - 输出文件夹名称\n\"outputCustom\": null,// - 自定义输出文件夹\n\"widgetOutputName\": \"widget\",// - 输出的所有widget合并后的文件名\n\"widgetInputName\": [],// - 指定需要输出的widget名称\n\"localServerPort\": 80,// - 本地服务器端口\n\"configJsonFileContent\": configJsonFileContent,// - jdf配置文件的默认配置内容\nvar configJsonFileContent{\n\"host\": \"ftpServerIp\",\n\"user\": \"anonymous\",\n\"password\": \"anonymous\",\n\"projectPath\": \"\"\n}\n\"cdn\": \"http://misc.360buyimg.com\",// - 静态cdn域名\n\"newcdn\": \"http://page.jd.com:81\",// - newcdn\n\"serverDir\": \"misc.360buyimg.com\",// - 上传至远端服务器文件夹的名称\n\"previewServerDir\": \"page.jd.com\",// - html文件夹上传至服务器所在的文件夹名称\n\"widgetServerDir\": \"jdfwidget.jd.com\",// - widget服务器所在的文件夹名称\n\"build\"\n\"jsPlace\": \"insertBody\",// - 调试时js文件位置 insertHead|insertBody\n\"widgetIncludeComment\":true,// - widget引用默认带注释,设置false后不再带注释\n\"livereload\":false,// - 是否开启liveload\n\"sass\":true,// - 是否开启sass编译\n\"less\":true,// - 是否开启less编译\n\"csslint\": false,// - 是否开启csslint\n\"weinre\": false,// - 是否开启移动设备调试\nweinreUrl: \"http://123.56.105.44:8080\",// - 调试移动设备的服务器地址\n\"output\"\n\"concat\":{},// - 文件合并\n\"output\":{\n\"concat\":{\n    \"js/a_js.js\":[\"js/index.js\", \"js/index2.js\"],\n    \"css/b_css.css\":[\"css/index.css\",\"css/index2.css\"]\n}\n}\n\"cssImagesUrlReplace\": true,// - css中图片url加cdn替换\n\"jsPlace\": \"insertBody\",// - 编译后js文件位置 insertHead|insertBody\n\"cssCombo\": true,// - css进行combo\n\"jsCombo\": true,// - js进行combo todo\n\"combineWidgetCss\":false,// - 合并所有引用的widget中的css\n\"combineWidgetJs\":false,// - 合并所有引用的widget中的js\n\"hasBanner\": 1,// - 压缩后的js和css是否有banner前缀，支持三种形式：0，不需要banner；1，banner为时间戳的形式，2，banner为md5值。\n下面代码示例的第一行注释为时间戳形式的banner\n/* Test w1.css Date:2015-08-13 15:04:07 */\n.list{background:url(http://misc.360buyimg.com/Test/widget/w1/i/icon.png)}\n下面代码示例的第一行注释为md5值形式的banner\n/* Test w1.css md5:f4fe4a055715c703557d008daf868c43 */\n.list{background:url(http://misc.360buyimg.com/Test/widget/w1/i/icon.png)}\n\"vm\":true,// - 是否开启vm编译\n\"compressJs\":true,// - 是否开启压缩js文件\n\"compressCss\":true,// - 是否开启压缩css文件\n\"compressPng\":true,// - 是否开启压缩png图片\n\"cssSprite\":true,// - 是否开启css sprite功能\n\"cssSpriteMode\": 1,// - 0: 将所有css文件中的背景图合并成一张sprite图片，1: 将每一个widget中的背景图分别合并成一张图片\n\"cssSpriteMargin\": 10,// - css sprite图片之间的间距\n\"cssSpriteDirection\": vertical,// - vertical：垂直合并，horizontal：水平合并\nbase64: false,// - 是否对图片进行base64编码\nbackground: url(i/icon13.png?__base64) no-repeat center right;\nbackground:url(data:image/png;base64,) no-repeat center right}\n\"imagesSuffix\": 0\n0：不添加任何后缀\n1：给css中需要cssSprite的背景图添加后缀，后缀会被添加在文件扩展名的后面。例如：test.png => test.png?20150319161000\n2：给css中需要cssSprite的背景图添加后缀，后缀会被添加在文件名的后面，生成一个新的文件。例如：test.png => test20150319161000.png\n\"jsRemove\",// - 移除js中函数或者方法,比如console,y.log即配置为[\'console\',\'y.log\']\nexcludeFiles: null,// - 输出时想要过滤的文件/文件夹，目前只支持正则表达式且不要带前后斜杠\n\"widget\":\nwidget预览所依赖的js\n\"js\":[\n    \"http://misc.360buyimg.com/jdf/lib/jquery-1.6.4.js\",\n    \"http://misc.360buyimg.com/jdf/1.0.0/unit/base/1.0.0/base.js\"\n]\nwidget预览所依赖的css\n\"css\":[\n    \"http://misc.360buyimg.com/lib/skin/2013/base.css\"\n]\n\"createFiles\":[\"vm\"],// - 新建widget文件夹的文件类型', NULL, '2016-5-23 13:30:45', '2016-5-27 15:29:31', 0, 0);
INSERT INTO `demo` VALUES (596, 00000000594, 1, 0, 'js', 'widget命令', '关键词', 'comment[ˈkɒment]注释', '// 在页面中统一引入\n{%widget name=\"test\"%}// 此时当前widget文件夹下的vm编译到页面上,js和css也加载至页面上\n{%widget name=\"test\" type=\"vm\"%}// 在页面中单独引入widget的vm文件\n{%widget name=\"test\" type=\"js\"%}// 在页面中单独引入widget的js文件\n{%widget name=\"test\" type=\"css\"%}// 在页面中单独引入widget的css文件\n// widget引入时注释配置\n// 在页面中引入，不带文件路径注释\n{%widget name=\"test\" comment=\"false\"%}\n// 或在config.json里面配置统一的配置项\nbuild: {\n    widgetIncludeComment:true //默认为true，不带可以设置成false\n}\n// 开发目录\nwidget //组件目录，包括模板组件，js组件，css组件\n  └── test\n        ├── example //举例\n        ├── test.vm //vm模板\n        ├── test.md //文档\n        ├── test.css //css文件\n        ├── i/ //等待上线的图片文件夹\n        ├── images/ //素材图片文件夹\n        └── test.js //js文件\n// 页面编译输出\n// 执行jdf build\n<!-- js，css -->\n<link type=\"text/css\" rel=\"stylesheet\"  href=\"/widget/test/test.css\" source=\"widget\"/>\n<script type=\"text/javascript\" src=\"/widget/test/test.js\" source=\"widget\"/></script>\n\n<!-- vm -->\n<div class=\"test\">this is test</div>\n// 页面交付输出\n// 执行jdf output\n// 所有widget模块中css文件combo如下\n<link type=\"text/css\" rel=\"stylesheet\" href=\"http://cdn/??widget/test/test.css,widget/b/b.css\"  source=\"widget\"/>\n// 所有widget模块中js文件combo如下\n<script type=\"text/javascript\" src=\"http://cdn/??widget/test/test.js,widget/b/b.js\" source=\"widget\"/></script>\n相关命令cmd\nwidget -all preview all widget //预览所有项目中所有widget\nwidget -preview xxx preview a widget //预览一个widget模块\nwidget -install xxx install a widget to local //安装一个widget模块到当前工程\nwidget -publish xxx publish a widget to server //发布一个widget模块到服务端\nwidget -create xxx create a widget to local //在本地项目新建一个widget,会生成widget文件夹和vm,css,js,json文件\nwidget -list get widget list from server //取得服务端所有widget列表\n', NULL, '2016-5-23 13:43:30', '2016-5-26 10:44:48', 0, 0);
INSERT INTO `demo` VALUES (597, 00000000588, 1, 0, 'js', '建模块widget/安装已有模块', '关键词', '', '新建：\njdf widget -create accordion   //执行后根据提示按yyyy键，结果生成了多个空文件\n安装：\njdf widget -create accordion //_promise._err,无法安装，报错\n预览所有：\nwidget -all preview all widget //提示不存在，报错据提示按yyyy键，结果生成了多个空文件  ', NULL, '2016-5-23 14:03:23', '2016-5-23 15:46:18', 0, 0);
INSERT INTO `demo` VALUES (598, 00000000588, 1, 1, 'js', '新建模块widget', '关键词', '描述', '新代码', NULL, '2016-5-23 14:03:24', '2016-5-23 14:04:24', 0, 0);
INSERT INTO `demo` VALUES (599, 00000000588, 1, 0, 'js', '预览', '关键词', '', '//执行：\njdf build\n//然后在项目中建一个index.html 写入hello jdf\n访问http://localhost/index.html即可！\n然后按键盘ctrl + C退出执行\n//输入：\njdf build -open//再次执行，会自动使用默认浏览器打开，不会不会自己寻找index.html文件\n注意：\n// 本地服务器默认启用80端口，如果此端口被占用，工具会自动启动1080端口，也可以通过config.json中localServerPort指定新端口\n// 命令执行后工具本地服务器会一直运行，可以使用ctrl+c命令退出本地server\n// 如果发现本地服务器在浏览器输出的文件夹和本地项目不一致，可通过jdf clean，清除服务器后台缓存，强制同步一次\n// 本地调试服务器启动成功后，可能通过jdf build -open命令自动打开浏览器，也可以复制http://localhost/在浏览上打开，同时后台内置了监听文件夹功能，如果在IDE里修改、新增、删除任何文件/文件夹，均会同步至后台，浏览器里访问总是最新的代码', NULL, '2016-5-23 14:11:23', '2016-5-23 14:32:59', 0, 0);
INSERT INTO `demo` VALUES (600, 00000000588, 1, 0, 'js', '编译', '关键词', '', '//还是再刚才的目录下面，执行：\njdf release\njdf release -open也有效果\n//结果发现引入的两个js并未合并first.js,second.js', NULL, '2016-5-23 14:33:13', '2016-5-23 14:34:37', 0, 0);
INSERT INTO `demo` VALUES (601, 00000000588, 1, 0, 'js', '发布', '关键词', '', '//项目输出\njdf output//输出项目文件夹，包括压缩合并后的css，js，images，静态资源加cdn前缀，同时压缩所有png图片\njdf output js/test.js，css //自定义输出自己需要的文件或文件夹\njdf output js/first.js,js/second.js\n//注意：输出以后，起项目的build文件夹下面查看输出情况\n\n//项目联调和发布\njdf upload //发布至远端145机器，主要包括css/js/widget，供产品，设计师查看效果，以及后端工程师联调\njdf upload -preview //输出html，并上传至http://page.jd.com下\n\n//项目备份\njdf output -backup //备份app目录至tags文件夹，供和已线上版本对比', NULL, '2016-5-23 14:39:19', '2016-5-23 15:12:13', 0, 0);
INSERT INTO `demo` VALUES (602, 00000000588, 1, 0, 'css', 'sass', '关键词', '', '新数据', NULL, '2016-5-23 15:15:36', '2016-5-23 15:15:46', 0, 0);
INSERT INTO `demo` VALUES (603, 00000000594, 1, 0, 'css', '自动图片精灵', '关键词', '在url后面追加?__sprite,然后设置号x y的坐标即可,系统如果想编译,那么会根绝坐标来计算新的坐标并吧所有图片合并!\n1.支持no-repeat，background-position；不支持repeat-x，repeat-y\n2.需要通过设置config.json的{{output.csssprite}}键值设置为true/false进行开启/关闭，图片的间距可以设置config.json的{{output.cssspriteMargin}}如：\"cssSpriteMargin\": 10，配置不需要写单位\n3.如果是使用rem的单位,需要需要在__sprite后再追加一个比例:__sprite__rem20;', '/*编译前*/\n.csssprite .abtest_huafei s {\n    background:url(i/icon_01.png?__sprite) no-repeat;\n}\n.csssprite .abtest_lvxing s {\n    background:url(i/icon_03.png?__sprite) no-repeat 6px 0px;\n}\n.csssprite .abtest_caipiao s {\n    background:url(i/icon_05.png?__sprite) no-repeat 5px 0px;\n}\n/*编译后*/\n.csssprite .abtest_huafei s {\n    background:url(i/sprite_csssprite.png?__sprite) no-repeat;\n    background-position:0 0\n}\n.csssprite .abtest_lvxing s {\n    background:url(i/sprite_csssprite.png?__sprite) no-repeat 6px 0;\n    background-position:6px -39px\n}\n.csssprite .abtest_caipiao s {\n    background:url(i/sprite_csssprite.png?__sprite) no-repeat 5px 0;\n    background-position:5px -78px\n}\n/*如果单位是rem，需要自带rem比例：__rem20*/\nhtml{\n    font-size: 20px;\n}\n.icon1, .icon2{\n    width: 1.8rem;\n    height: 1.8rem;\n    margin: 10px;\n    background: url(i/icon7.png?__sprite__rem20) no-repeat;\n    border: 1px solid black;\n}\n.icon2{\n    background: url(i/icon8.png?__sprite__rem20) no-repeat;\n}\n/*如上代码编译后*/\nhtml {\n    font-size: 20px\n}\n.icon1, .icon2 {\n    width: 1.8rem;\n    height: 1.8rem;\n    margin: 10px;\n    background: url(http://misc.360buyimg.com/jdf/Test/widget/w2/i/w2.png?__sprite__rem20) no-repeat;\n    background-position: 0 0;\n    background-size: 1.8rem 4.6rem;\n    border: 1px solid #000\n}\n.icon2 {\n    background: url(http://misc.360buyimg.com/jdf/Test/widget/w2/i/w2.png?__sprite__rem20) no-repeat;\n    background-position: 0 -2.3rem;\n    background-size: 1.8rem 4.6rem\n}', NULL, '2016-5-23 15:22:59', '2016-6-16 16:30:34', 0, 0);
INSERT INTO `demo` VALUES (604, 00000000456, 1, 0, 'js', 'scss', '关键词', '描述', '新代码', NULL, '2016-5-23 15:55:24', '2016-5-23 15:55:24', 0, 0);
INSERT INTO `demo` VALUES (605, 00000000604, 1, 0, 'js', '在webstorm中配置环境', '关键词', '参考地址：https://gems.ruby-china.org/', '    1.安装ruby\n然后开始--ruby--命令行\ngem sources --add http://gems.ruby-china.org --remove https://rubygems.org/\ngem install sass\n\n2.新建scss文件，根据提示配置watch  按照攻略填写，其中定位到刚才的ruby的安装目录下的bin下面的sass.bat\n这里有些参数可以配置，不需要管，现在的sass文件已经被监视了，只要又任何的改动，就会在源文件旁边生成相应的css文件了', NULL, '2016-5-23 15:55:43', '2016-5-23 17:47:17', 0, 0);
INSERT INTO `demo` VALUES (606, 00000000456, 1, 0, 'js', 'LESS', '关键词', '描述', '新代码', NULL, '2016-5-23 16:00:48', '2016-5-23 16:00:48', 0, 0);
INSERT INTO `demo` VALUES (607, 00000000606, 1, 0, 'js', '在webstorm中配置less', '关键词', '', '1.先安装nodejs然后：\nnpm install less\nwebstorm的file->settings -> Tools -> External Tools\n点击+号\n名字随便写LESS\nprogram:C:\\Program Files\\nodejs\\node.exe\nparameters:C:\\Users\\dangtianliang\\node_modules\\less\\bin\\lessc $FilePath$ $FileDir$\\$FileNameWithoutExtension$.css\nWorking directory:C:\\Program Files\\nodejs\n配置完毕\nkeymap--external tolls 找到less，配置快捷键alt +b\n新建一个less文件\n', NULL, '2016-5-23 16:01:01', '2016-5-23 18:19:01', 0, 0);
INSERT INTO `demo` VALUES (608, 00000000604, 1, 0, 'js', 'sass/scss&less', '关键词', '一：Sass与Scss有什么差别\nSass原先跟Haml一样的缩排语法，必须严格缩进，不必写引号结束，类似咖啡script的展现，对于写惯Css的前端来说是很不直观的，也不能将原来的Css加到Sass里面，因此Sass改良了语法，Sass 3就变成了Scss(Sassy CSS)。与原来的语法兼容，只是用{}取代了原来的缩进\n二：Sass/Scss&Less区别？\n1.Sass是基于Ruby的，是在服务端处理的，而Less是需要引入less.js来处理Less代码输出Css到浏览器，也可以在开发环节使用Less，然后编译成Css文件，直接放到项目中，也有Less.app、SimpleLess、CodeKit.app这样的工具，也有在线编译地址。\n2.变量符不一样，less是@，而Scss是$，而且变量的作用域也不一样，后面会讲到。\n3.输出设置，Less没有输出设置，Sass提供4中输出选项：nested, compact, compressed 和 expanded。\n4.Sass支持条件语句，可以使用if{}else{},for{}循环等等。而Less不支持。', '新数据', NULL, '2016-5-23 17:28:26', '2016-5-23 23:19:27', 0, 0);
INSERT INTO `demo` VALUES (609, 00000000360, 1, 0, 'js', '其它webstorm快捷键', '关键词', '', 'Ctrl + Space ;//Basic code completion (the name of anyclass, method or variable)\nCtrl + Shift + Enter ;//Complete statement\nCtrl + P ;//Parameter info (within method call arguments)\nCtrl + Q ;//Quick documentation lookup\nCtrl + mouse over code Brief Info\nCtrl + F1 ;//Show descriptions of error or warning at caret\nAlt + Insert ;//Generate code...\nCtrl + Alt + T ;//Surround with... (if..else, try..catch, for, etc.)\nCtrl + / ;//Comment/uncomment with line comment\nCtrl + Shift + / ;//Comment/uncomment with block comment\nCtrl + W ;//Select successively increasing code blocks\nCtrl + Shift + W ;//Decrease current selection to previous state\nAlt + Q ;//Context info\nAlt + Enter ;//Show intention actions and quick-fixes\nCtrl + Alt + L ;//Reformat code\nCtrl + Alt + I ;//Auto-indent line(s)\nTab / Shift + Tab ;//Indent/unindent selected lines\nCtrl + X , Shift + Delete ;//Cut current line or selected block to clipboard\nCtrl + C , Ctrl + Insert   ;//  Copy current line or selected block to clipboard\nCtrl + V , Shift + Insert;// Paste from clipboard\nCtrl + Shift + V    ;// Paste from recent buffers...\nCtrl + D ;//Duplicate current line or selected block\nCtrl + Y ;//Delete line at caret\nCtrl + Shift + J ;//Join lines\nCtrl + Enter ;//Split lines\nShift + Enter ;//Start new line\nCtrl + Shift + U    ;// Toggle case for word at caret or selected block\nCtrl + Shift + ] ;/// [ Select till code block end/start\nCtrl + Delete ;//Delete to word end\nCtrl + Backspace ;//Delete to word start\nCtrl + NumPad+/- Expand/collapse code block\nCtrl + Shift + NumPad+ Expand ;//all\nCtrl + Shift + NumPad- Collapse all\nCtrl + F4 ;//Close active editor tab\nMultiple carets and selections\nAlt + Click ;//Add or remove caret\nShift + Ctrl + Alt + J ;//Select all occurrences\nAlt + J ;//Select next occurrence\nAlt + Shift + J ;//Unselect occurrence\nEsc Unselect all occurrences or carets\nRunning\nAlt + Shift + F10;///F9     Select configuration and run/debug\nShift + F10;///F9 Run/Debug\nCtrl + Shift + F10;///F9     Run/Debug context configuration from editor\nAlt + Shift + R ;//Rerun tests\nDebugging\nF8 Step over\nF7 Step into\nShift + F7 ;//Smart step into\nShift + F8 ;//Step out\nAlt + F9 ;//Run to cursor\nAlt + F8 ;//Evaluate expression\nF9 Resume\nCtrl + F8 ;//Toggle breakpoint\nCtrl+Shift+F8 ;//View breakpoints\nNavigation\nCtrl + N ;//Go to class\nCtrl + Shift + N    ;// Go to file\nCtrl + Alt + Shift + N ;//Go to symbol\nAlt + Right ;//Go to next editor tab\nAlt + Left ;//Go to previous editor tab\nF12 ;//Go back to previous tool window\nEsc ;//Go to editor (from tool window)\nShift + Esc ;//Hide active or last active window\nCtrl + Shift + F4    ;// Close active run/messages/find/... tab\nCtrl + G ;//Go to line\nCtrl + E ;//Recent files popup\nCtrl + Alt + Left;///Right Navigate back/forward\nCtrl + Shift + Backspace Navigate to last edit location\nAlt + F1 ;//Select current file or symbol in any view\nCtrl + B , Ctrl + Click ;//Go to declaration\nCtrl + Alt + B ;//Go to implementation(s)\nCtrl + Shift + I    ;// Open quick definition lookup\nCtrl + Shift + B ;//Go to type declaration\nCtrl + U ;//Go to super-method/super-class\nAlt + Up;///Down Go to previous/next method\nCtrl + ] ;/// [ Move to code block end/start\nCtrl + F12 ;//File structure popup\nCtrl + H ;//Type hierarchy\nCtrl + Alt + H ;//Call hierarchy\nF2 / Shift + F2 ;//Next/previous highlighted error\nF4, Ctrl + Ente ;//Jump to source\nAlt + Home ;//Jump to navigation bar\nF11;// Toggle bookmark\nCtrl + F11 ;//Toggle bookmark with mnemonic\nCtrl + #[0-;//9] Go to numbered bookmark\nShift + F11 ;//Show bookmarks\nVCS/Local History\nAlt + BackQuote ;//(`) ‘VCS’ quick popup\nCtrl + K ;//Commit project to VCS\nCtrl + T ;//Update project from VCS\nAlt + Shift + C ;//View recent changes\nSearch/Replace\nCtrl + F ;//Find\nF3 Find next\nShift + F3 ;//Find previous\nCtrl + R ;//Replace\nCtrl + Shift + F ;//Find in path\nCtrl + Shift + R ;//Replace in path\nUsage Search\nAlt + F7 / Ctrl + F7    //Find usages / Find usages in file\nCtrl + Shift + F7    ;// Highlight usages in file\nCtrl + Alt + F7 ;//Show usages\nRefactoring\nF5 Copy\nF6 Move\nAlt + Delete ;//Safe delete\nShift + F6 ;//Rename\nCtrl + Alt + N ;//Inline variable\nCtrl + Alt + M ;//Extract method\nCtrl + Alt + V ;//Introduce variable\nCtrl + Alt + C ;//Introduce constant\nCtrl + Alt + P ;//Introduce parameter\nCtrl + F6 ;//Change function signature\nGeneral\nCtrl + Shift + A ;//Find action\nDouble Shift Search everywhere\nAlt + #[0-;//9] Open corresponding tool window\nCtrl + Shift + F12 ;//Toggle maximizing editor\nAlt + Shift + F ;//Add to favorites\nAlt + Shift + I    ;// Inspect current file with current profile\nCtrl + BackQuote ;//(`) Quick switch current scheme\nCtrl + Alt + S ;//Open settings dialog\nCtrl + Tab ;//Switch between tabs and tool window', NULL, '2016-5-23 17:59:26', '2016-5-23 18:02:08', 0, 0);
INSERT INTO `demo` VALUES (610, 00000000430, 1, 0, 'js', 'git新项目流程', '关键词', 'remote远程，origin源，develop 发展，master主要的', '    1.右键新建仓库--》打勾》\n2.右键setting设置--填写用户名和邮箱\n3.右键图形界面git clone.\n输入地址：http://source.jd.com/app/JDC_channel_newarrivals.git.\n$ git branch -a //查看看服务端所有分支情况.\n$ git checkout -b 分之名 remotes/origin/分支名字//拉取成功！.\n$ git add test.txt\n$ git commit -m \"dangtianliang\"\n$ git push\njdf build -open//成功使用本地环境查看项目  ', NULL, '2016-5-23 18:29:35', '2016-5-25 17:24:41', 0, 0);
INSERT INTO `demo` VALUES (611, 00000000567, 1, 0, 'css', 'lib.scss分析', '关键词', '可用方法:\n@include prefixer($property, $value, $prefixes: o webkit);\n@include disable-prefix-for-all();\n@include keyframes($name, $prefixes: webkit o );\n@include transform($property: none);\n@include transform-origin($axes: 50%);\n@include transform-style ($style: flat);\n@include animation ($animations...);\n@include animation-delay ($times...);\n@include transition ($properties...);\n@include clearfix ();\n@include inline-block();\n@include r-corners ($r...);\n@include gradual-change($s:#f8f8f8,$e:#ebebeb);\n@include mediaMin($w,$class);\n@include mediaMax($w,$class);\n@include mediaMinMax($minw,$maxw,$class);\n@include box-shadow($x: 0px, $y: 3px, $blur: 5px, $alpha: 0.5);\n@include alpha($o:70);\n@include arrow($width,$color,$direction);\n\n字体:\n$font-st:\'SimSun\';\n$font-yahei:\'Microsoft Yahei\';\n$font-verdana:verdana;\n\n颜色:\n$color01:#e43a3d;\n$color02:#71b247;\n$color03:#999;\n$color04:#ff6c00;\n$color05:#005ea7;\n$color06:#666;\n$header: #b32d36;', '/*浏览器开关*/\n$prefixForWebkit:             true !default;\n$prefixForMozilla:            true !default;\n$prefixForMicrosoft:          true !default;\n$prefixForOpera:              false !default; //opera从版本15开始转向webkit，所以默认为false，不输出o前缀\n$prefixNo:                    true !default;\n\n/*自动添加兼容前缀,3个参数依次为:属性,值,空格分割的浏览器内核要求*/\n@mixin prefixer($property, $value, $prefixes: o webkit) {\n  @each $prefix in $prefixes {\n    @if $prefix == webkit and $prefixForWebkit == true {\n      -webkit-#{$property}: $value;\n    }\n    @else if $prefix == moz and $prefixForMozilla == true {\n      -moz-#{$property}: $value;\n    }\n    @else if $prefix == ms and $prefixForMicrosoft == true {\n      -ms-#{$property}: $value;\n    }\n    @else if $prefix == o and $prefixForOpera == true {\n      -o-#{$property}: $value;\n    }\n  }\n  @if $prefixNo {\n    #{$property}: $value;\n  }\n}\n\n/*关闭所有的内核兼容要求,以配合其他函数*/\n@mixin disable-prefix-for-all() {/*@include disable-prefix-for-all ();*/\n  $prefixForWebkit:      false;\n  $prefixForMozilla:     false;\n  $prefixForMicrosoft:   false;\n  $prefixForOpera:       false;\n  $prefixNo:             false;\n}\n\n/*自动生成keyframes的兼容代码,参数分别为keyframes的name,空格分割的浏览器内核,{}中为正常的内容,这个函数篇幅比较长*/\n@mixin keyframes($name, $prefixes: webkit o ) {\n  $originalPrefixForWebkit: $prefixForWebkit;\n  $originalPrefixForMozilla: $prefixForMozilla;\n  $originalPrefixForMicrosoft: $prefixForMicrosoft;\n  $originalPrefixForOpera: $prefixForOpera;\n  $originalPrefixNo: $prefixNo;\n\n  @each $prefix in $prefixes {\n    @if $prefix == webkit and $originalPrefixForWebkit == true {\n      @include disable-prefix-for-all();\n      $prefixForWebkit: true;\n      @-webkit-keyframes #{$name} {\n        @content;\n      }\n    }\n    @if $prefix == moz and $originalPrefixForMozilla == true {\n      @include disable-prefix-for-all();\n      $prefixForMozilla: true;\n      @-moz-keyframes #{$name} {\n        @content;\n      }\n    }\n    @if $prefix == ms and $originalPrefixForMicrosoft == true {\n      @include disable-prefix-for-all();\n      $prefixForMicrosoft: true;\n      @-ms-keyframes #{$name} {\n        @content;\n      }\n    }\n    @if $prefix == o and $originalPrefixForOpera == true {\n      @include disable-prefix-for-all();\n      $prefixForOpera: true;\n      @-o-keyframes #{$name} {\n        @content;\n      }\n    }\n  }\n\n  @include disable-prefix-for-all();\n  $prefixNo: true;\n  @keyframes #{$name} {\n    @content;\n  }\n\n  $prefixForWebkit:       $originalPrefixForWebkit;\n  $prefixForMozilla:      $originalPrefixForMozilla;\n  $prefixForMicrosoft:    $originalPrefixForMicrosoft;\n  $prefixForOpera:        $originalPrefixForOpera;\n  $prefixNo:              $originalPrefixNo;\n}\n\n/*keyframes例子:*/\n@include keyframes(pulse, webkit moz){\n  0% {\n      opacity: 1;\n      @include transform(scale(1));\n  }\n  50% {\n      opacity: 0.7;\n      @include transform(scale(0.9));\n  }\n  100% {\n      opacity: 1;\n      @include transform(scale(1));\n  }\n};\n\n/*transform的兼容代码生成函数,其中又内调了prefixer函数*/\n@mixin transform($property: none) {/*默认无值传入*/\n  @include prefixer(transform, $property, webkit moz spec);\n}\n/*例子:*/\n@include transform(rotate(-4deg));\n@include transform(rotate(-4deg) translate(6px, 18px) scale(1));\n\n/*transform-origin生成设置动画原点的兼容代码的函数*/\n@mixin transform-origin($axes: 50%) {/* (x-axis - left | center | right  | length | %)(y-axis - top  | center | bottom | length | %) */\n  @include prefixer(transform-origin, $axes, webkit moz spec);\n}\n/*例子:*/\n@include transform-origin(center bottom 0);\n@include transform-origin(505, 50%);\n\n/*transform-style生成兼容代码,动画是2d还是3d,内部调用了prefixer*/\n@mixin transform-style ($style: flat) {/*flat|preserve-3d*/\n  @include prefixer(transform-style, $style, webkit moz spec);\n}\n/*animation兼容代码生成*/\n@mixin animation ($animations...) {\n  @include prefixer(animation, $animations, webkit moz spec);\n}\n/*例子:*/\n@include animation(pop_move_1 6s infinite);\n\n/*animation-delay兼容代码生成*/\n@mixin animation-delay ($times...) {\n  @include prefixer(animation-delay, $times, webkit moz spec);\n}\n/*例子:*/\n@include animation-delay(0.2s);\n\n/*transition兼容代码生成*/\n@mixin transition ($properties...) {\n  @if length($properties) >= 1 {\n    @include prefixer(transition, $properties, webkit moz spec);\n  }\n\n  @else {\n    $properties: all 0.15s ease-out;\n    @include prefixer(transition, $properties, webkit moz spec);\n  }\n}\n/*例子*/\n@include transition(all 0.2s ease-in-out, opacity 1s);\n\n/*常用字体*/\n$font-st:\'SimSun\';\n$font-yahei:\'Microsoft Yahei\';\n$font-verdana:verdana;\n\n/*常用颜色*/\n$color01:#e43a3d;        //红色\n$color02:#71b247;        //绿色\n$color03:#999;            //灰色\n$color04:#ff6c00;        //黄色\n$color05:#005ea7;        //蓝色\n$color06:#666;            //深灰色\n$header: #b32d36;    //频道主色\n\n/*清除浮动,用在wrap元素上*/\n@mixin clearfix {/*@include clearfix();*/\n    &:after {\n        content: \".\";\n        display: block;\n        height: 0;\n        clear: both;\n        visibility:hidden\n      }\n  display: inline-block;\n  * html & {height:1%}\n  display:block;\n  *+html &{min-height:1%}\n}\n\n$lte7:false;\n\n/*inline-block*/\n@mixin inline-block {/*@include inline-block();*/\n  display: inline-block;\n  *display: inline;*zoom:1;\n}\n\n/*圆角*/\n@mixin r-corners ($r...){/*@include r-corners();*/\n    -webkit-border-radius: $r;\n    -moz-border-radius: $r;\n    border-radius: $r;\n}\n\n/*渐变*/\n@mixin gradual-change($s:#f8f8f8,$e:#ebebeb){/*@include gradual-change(#000,#fff);*/\n    background-color:$s;\n    background-image: -moz-linear-gradient(top, $s,$e);\n    background-image: -webkit-gradient(linear, left top, left bottom, color-stop(0, $s), color-stop(1, $e));\n    filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#{$s}\', endColorstr=\'#{$e}\', GradientType=\'0\');\n    -ms-filter:progid:DXImageTransform.Microsoft.gradient(startColorstr=\'#{$s}\', endColorstr=\'#{$e}\');\n    background-image: linear-gradient(to bottom, $s 0%, $e 100%);\n}\n\n/*最小宽*/\n@mixin mediaMin($w,$class){ /*@include mediaMin(768px,.header){color:red;};*/\n    @media screen and(min-width: #{$w}){\n        @content;\n    }\n    .#{$class}{\n        @content;\n    }\n}\n\n/*最大宽*/\n@mixin mediaMax($w,$class){\n    @media screen and(max-width: #{$w}){\n        @content;\n    }\n    .#{$class}{\n        @content;\n    }\n}\n\n/*最小宽，最大宽，类名*/\n@mixin mediaMinMax($minw,$maxw,$class){\n    @media screen and(min-width: #{$minw}) and(max-width: #{$maxw}){\n        @content;\n    }\n    .#{$class}{\n        @content;\n    }\n}\n\n/*阴影*/\n@mixin box-shadow($x: 0px, $y: 3px, $blur: 5px, $alpha: 0.5) {/*@include 2px,2px,2px,0.5);*/\n  -webkit-box-shadow: $x $y $blur rgba(0, 0, 0, $alpha);\n  -moz-box-shadow: $x $y $blur rgba(0, 0, 0, $alpha);\n  box-shadow: $x $y $blur rgba(0, 0, 0, $alpha);\n}\n\n/*半透明*/\n@mixin alpha($o:70) { /*@include alpha(70);*/\n  filter: alpha(opacity=$o);\n  -moz-opacity: $o/100;\n  opacity: $o/100;\n}\n\n/*三角*/\n@mixin arrow($width,$color,$direction){/*任意样式选择器:@include arrow(8px,red,right);*/\n  width: 0;\n  height: 0;\n  line-height: 0;\n  font-size: 0;\n  @if $direction == \'left\'{\n      border-color: transparent $color transparent  transparent ;\n      border-style: dashed solid dashed dashed;\n  }\n  @if $direction == \'right\'{\n      border-color: transparent transparent transparent $color;\n      border-style: dashed dashed dashed solid;\n  }\n  @if $direction == \'up\'{\n      border-color: transparent transparent $color transparent ;\n      border-style: dashed dashed solid dashed;\n  }\n  @if $direction == \'down\'{\n      border-color: $color transparent transparent transparent;\n      border-style: solid dashed dashed dashed;\n  }\n  border-width: $width;\n  position: absolute;\n}', NULL, '2016-5-24 11:38:56', '2016-6-17 15:44:59', 0, 0);
INSERT INTO `demo` VALUES (612, 00000000567, 1, 1, 'js', 'scsslib', '关键词', '描述', '新代码', NULL, '2016-5-24 11:38:56', '2016-5-24 15:49:44', 0, 0);
INSERT INTO `demo` VALUES (613, 00000000567, 1, 0, 'js', 'css书写原则', '关键词', '1类名的第一个字符不能使用数字！它在很多浏览器中无法起作用\n2尽量用小写英文\n3尽量采用简写，减少代码量\n4CSS须兼容主流浏览器\n5所有装饰性的图片（如背景图），要定义在CSS中\n6ID必须是唯一的\n7单位建议使用\"px\"“em”和“%”\n8CSS中不要使用expression\n9CSS中不要使用滤镜', '新数据', NULL, '2016-5-24 15:50:46', '2016-5-24 15:51:04', 0, 0);
INSERT INTO `demo` VALUES (614, 00000000567, 1, 0, 'css', 'css排列顺序', '关键词', '', '1--------------------\ndisplay\nvisibility\nposition\nfloat\nlist-style\nclear\ncursor\n\n2--------------------\nmargin\npadding\nwidth\nheight\n\n3--------------------\nline-height\nfont(color/font-family/font-size/font-weight)\ntext-decorationtext-align\nvertical-align\nwhite-space\n\n4--------------------\nborder\nbackground\n\n5--------------------\noverflow\nz-index\nzoom', NULL, '2016-5-24 15:51:27', '2016-6-17 15:40:56', 0, 0);
INSERT INTO `demo` VALUES (615, 00000000567, 1, 0, 'js', '页面栅格', '关键词', '', '1.\n首页：\n990：210+550+210\n1210：210+670+310\n\n//频道页：\n990：210+550+210\n1210：210+770+210\n\n//列表页/商品详细页：\n990：211+769（210+770）\n1210：211+989（210+990）\n\n//图书/音像频道：（目前仅有窄版）\n990：210+550+210\n---------------------------------------\n2.页面常用宽度，采用栅格算法（20*n-10）\n.g-0 {width: 100%;}   (n=0表示自适应)\n.g-8 {width:150px;}   (n=8)\n.g-a {width:190px;}   (n=a=10)\n.g-a1 {width:210px;}  (n=a1=11)\n.g-a5 {width:290px;}  (n=a5=15)\n.g-b1 {width:410px;}  (n=b1=21)\n.g-b4 {width:470px;}  (n=b4=24)\n.g-b8 {width:550px;}  (n=b8=28)\n.g-b9 {width:570px;}  (n=b9=29)\n.g-c9 {width:770px;}  (n=c9=39)\n.g-d {width:790px;}   (n=d=40)\n.g-e {width:990px;}   (n=e=50)\n3.自适应偏移\n//自适应宽度\n.g-80 {margin-left:160px;}\n//(注：8表示左侧宽度是8*20=160，0表示右侧自适应)\n.g-08 {margin-right:160px;}\n//(注：0表示左侧自适应，0表示右侧宽度是8*20=160)', NULL, '2016-5-24 15:53:19', '2016-5-24 15:55:48', 0, 0);
INSERT INTO `demo` VALUES (616, 00000000567, 1, 0, 'css', '注释', '关键词', '', '/*  \n*@Description: public common css （可写中文）  \n*@Author:      sev7n  \n*@Update:      sev7n(2011-08-09 17:22)  \n*/', NULL, '2016-5-24 15:56:10', '2016-5-24 15:56:19', 0, 0);
INSERT INTO `demo` VALUES (617, 00000000567, 1, 0, 'html', 'zindex', '关键词', '1页面弹窗、气泡为999\n2普通区块为10-90内10的倍数\n3区块展开、弹出为当前父层级上个位增加', '<ul class=\"post-bd\">  \n    <li class=\"post-to\">  \n        <div class=\"post-tag\"></div>  \n        <div class=\"post-add\"></div>\n    </li>  \n    <li class=\"post-editor\"></li>  \n    <li class=\"post-app\"></li>  \n</ul>\n.post-to {z-index:90;}   \n.post-tag {z-index:99;}   \n.post-add {z-index:98;}   \n.post-editor {z-index:80;}   \n.post-app {z-index:70;}', NULL, '2016-5-24 15:56:49', '2016-5-24 15:57:56', 0, 0);
INSERT INTO `demo` VALUES (618, 00000000163, 1, 0, 'js', '转义字符', '关键词', '', '\"<\" -  &lt;\n\">\" - &gt;\n\"&\" - &amp;\n引号 - &quot;\n空格 - &nbsp;\n\"X号\" - &times;\n￥ - &yen;\ncopty - &copy;\n', NULL, '2016-5-24 17:27:42', '2016-5-24 17:30:53', 0, 0);
INSERT INTO `demo` VALUES (619, 00000000566, 1, 0, 'js', 'html', '关键词', '描述', '新代码', NULL, '2016-5-24 17:36:39', '2016-5-24 17:36:39', 0, 0);
INSERT INTO `demo` VALUES (620, 00000000619, 1, 0, 'js', '属性不允许简写', '关键词', '', 'compact compact=\"compact\"\nchecked checked=\"checked\"\ndeclare declare=\"declare\"\nreadonly readonly=\"readonly\"\ndisabled disabled=\"disabled\"\nselected selected=\"selected\"\ndefer defer=\"defer\"\nismap ismap=\"ismap\"\nnohref nohref=\"nohref\"\nnoshade noshade=\"noshade\"\nnowrap nowrap=\"nowrap\"\nmultiple multiple=\"multiple\"\nnoresize noresize=\"noresize\"', NULL, '2016-5-24 17:37:03', '2016-5-24 17:37:08', 0, 0);
