INSERT INTO `demo` VALUES (642, 00000000454, 1, 0, 'js', 'seajs', '关键词', '描述', '新代码', NULL, '2016-5-27 12:21:53', '2016-5-27 12:21:53', 0, 0);
INSERT INTO `demo` VALUES (643, 00000000642, 1, 0, 'js', 'jd中seajs的初始化', '关键词', '', 'seajs.config({\n    base: pageConfig.jdfBaseUri,\n    alias: {},\n    map: [],\n    preload: preloadArray,\n    debug: 0\n});', NULL, '2016-5-27 12:22:00', '2016-5-27 12:22:41', 0, 0);
INSERT INTO `demo` VALUES (644, 00000000642, 1, 0, 'js', 'seajs详解', '关键词', '1.兼容到ie5.5\n2.seajs.config可多次配置,将自动合并和覆盖\n3.gallery[ˈgæləri]长廊--alias[ˈeɪliəs]别名\n4.常用的配置项是 alias、paths、base，其他配置项有需要时，来查查文档就会用了。。。。', '//------------配置\nseajs.config({\n  base: \'http://example.com/path/to/base/\',//建议不设置,其他js将相对于Sea.js\n  alias: {//别名配置\n    \'es5-safe\': \'gallery/es5-safe/0.9.3/es5-safe\',\n    \'json\': \'gallery/json/1.0.2/json\',\n    \'jquery\': \'jquery/jquery/1.10.1/jquery\',//使用的时候:var $ = require(\'jquery\');\n    \'app/biz\': \'http://path/to/app/biz.js\'//用的时候:var biz = require(\'app/biz\');\n  },\n  paths: {//配合alias,解决路径层级过深,可配置多个\n    \'gallery\': \'https://a.alipayobjects.com/gallery\',\n    //var underscore = require(\'gallery/underscore\');\n    //=> 加载的是 https://a.alipayobjects.com/gallery/underscore.js\n    \'app\': \'path/to/app\'//var biz = require(\'app/biz\');=> 加载的是 path/to/app/biz.js\n  },\n  vars: {//变量\n    \'locale\': \'zh-cn\'\n    //var lang = require(\'./i18n/{locale}.js\');\n     //=> 加载的是 path/to/i18n/zh-cn.js\n  },\n  map: [//映射(替换)\n    [\'http://example.com/js/app/\', \'http://localhost/js/app/\'],\n    [ \'.js\', \'-debug.js\' ]\n    //var a = require(\'./a\');\n    //=> 加载的是 path/to/a-debug.js\n  ],\n  preload: [//预加载,这只是配置,触发实在use执行的时候,如果在defind中去配置它,不一定生效\n    Function.prototype.bind ? \'\' : \'es5-safe\',\n    this.JSON ? \'\' : \'json\'\n  ],\n  debug:0,//值为true时，加载器不会删除动态插入的 script 标签。很多插件依据这个来config。\n  charset: \'utf-8\'\n});\n//------------------------入口\nseajs.use(\"abc/main\");//不带回调\nseajs.use(\'./main\', function(main) {//加载单个依赖,执行指定回调\n  main.init();\n});\nseajs.use([\'./a\', \'./b\'], function(a, b) {//加载多个依赖,同时加载完毕时执行回调\n  a.init();\n  b.init();\n});\n//-------------------------模块的初始化\n// 所有模块都通过 define 来定义\ndefine(function(require, exports, module) {\n  // 通过 require 引入依赖\n  var $ = require(\'jquery\');\n  var Spinning = require(\'./spinning\');\n  // 通过 exports 对外提供接口\n  exports.doSomething = ...\n  // 或者通过 module.exports 提供整个接口\n  module.exports = ...\n});\n', NULL, '2016-5-27 12:23:08', '2016-5-27 13:40:16', 0, 0);
