INSERT INTO `demo` VALUES (651, 00000000566, 1, 1, 'js', '基于seajs', '关键词', '描述', '新代码', NULL, '2016-5-27 15:34:32', '2016-5-27 15:35:10', 0, 0);
INSERT INTO `demo` VALUES (652, 00000000650, 1, 0, 'js', '基于seajs的组件的写法', '关键词', '组件又分:\n1.ui和unit(单元)组件\n2.widget中js组件\n3.非标准化组件', '//组件源码\ndefine(function(require, exports, module){\n    var a = require(\'widget/a/a.js\');//加载器会保证require加载完成后才执行init\n    var b = require(\'widget/b/b.js\');\n    function init(){\n        //todo\n    }\n    exports.init = init;\n    //or return init;\n});\n//编译后\ndefine([\'js/test.js\'], [\'/widget/a/a.js\', \'widget/b/b.js\' ], function(require, exports, module){\n    require(\"widget/a/a.js\"),require(\"widget/b/b.js\");\n    function init(){}\n    exports.init = init;\n});\n------------------------------------------------\n//组件的调用方式:\n1.ui和unit组件引用方法\nseajs.use([\'jdf/1.0.0/unit/event/1.0.0/event.js\'],function(event){ \n    //todo,回调写点东西\n})\n2.项目内js引用方法\nseajs.use([\'/js/a.js\',\'/js/b.js\'],function(a,b){ \n//todo ,也是回调写点东西\n})\n//工具编译后:(注意path已经使用了正确的path)\nseajs.use([\'projectPaht/js/a.js\',\'projectPaht/js/b.js\'],function(a,b){\n //todo \n});', NULL, '2016-5-27 15:35:18', '2016-5-27 15:42:49', 0, 0);
INSERT INTO `demo` VALUES (653, 00000000604, 1, 0, 'js', 'scss的格式化', '关键词', 'http://sebastianpontow.de/css2compass/', '可以正常写完css的嵌套,然后csscomb一下,再转为scss,\n或者编辑器直接写scss,然后chrome中写入映射,可以直接修改scss文件', NULL, '2016-6-1 17:54:57', '2016-6-1 17:57:26', 0, 0);
INSERT INTO `demo` VALUES (654, 00000000566, 1, 0, 'js', 'CMS写法', '关键词', '描述', '新代码', NULL, '2016-6-2 09:34:55', '2016-6-2 09:34:55', 0, 0);
INSERT INTO `demo` VALUES (655, 00000000654, 1, 0, 'js', '元件数据遍历之foreach', '关键词', '1. 如果只想在页面看到的结果是遍历后的所有value值得，那么模板中直接这样调用：\n<{$var|print_r}>\n2. 如果想和PHP一样显示完整的数组结构，正确的方法是在函数前加个@，意思是把变量作为整体去对待，那么模板中这样调用：\n<{$var|@print_r}>    例如:<{{{$commodity_pool}}|@var_dump}>,怎么还必须再section中才能使用!\n3.其中{}类似<?php  ?>,可以直接写php语句, 比如打印出遍历对象:{var_dump({{$commodity_pool}})},但是很多php语法不能用', '        {$portal_cell_id = $portal_cell_id + 1}\n{foreach {{$Activity}} as $row}//这个不是遍,历,是统一使用 $row来代表数据实体,应该试试<{$var|@print_r}>\n    {foreach $row.apply_list as $key => $value}//$row.apply_list拿到列表,并对列表遍历\n{$img=\'\'}\n{$url=\'\'}\n     {foreach $value as $key2 => $value2}// $value为本条数据,本条数据应该是json格式,遍历每一个数据,检查code属性,然后取value值;\n        {if $value2[\'code\'] == \'activity_img\'}\n            {$img = {$value2[\'value\']} }//拿到了img的url的值\n       {else if $value2[\'code\'] == \'activity_url\'}\n            {$url = {$value2[\'value\']} }//拿到了超链接的值\n       {/if}\n    {/foreach}\n    <li>\n      <a href=\"{$url}\" target=\"_blank\"><img data-lazy-img=\"{$img}\" width=\"245\" height=\"202\" src=\"\" clstag=\"firsttype|keycount|{$portal_id}|HP{$portal_floor_id}_{$portal_cell_id}_{$key}\"></a>\n    </li>\n    {/foreach}\n{/foreach}\n\n{$portal_cell_id = $portal_cell_id + 1}\n{foreach {{$Activity}} as $row}\n    {foreach $row.apply_list as $key => $value}\n      {foreach $value as $key2 => $value2}\n          <li class=\"m-item\" clstag=\"firsttype|keycount|{$portal_id}|SPC{$portal_floor_id}_{$portal_cell_id}_{$key}\" >\n            <div class=\"m-item-inner\">\n              <div class=\"m-img\">\n                <a href=\"//item.jd.com/{$key2}.html\" title=\"{$value2[\'name\']}\" target=\"_blank\">\n                  <img data-lazy-img=\"{$value2[\'imagePath\']}\" src=\"\" width=\"160\" height=\"160\" alt=\"{$value2[\'name\']}\"/>\n                </a>\n              </div>\n              <div class=\"m-info\">\n                <a class=\"m-title\" title=\"{$value2[\'name\']}\" href=\"//item.jd.com/{$key2}.html\" target=\"_blank\">{$value2[\'name\']}</a>\n                <p class=\"m-price\"><b data-price-id=\"{$key2}\"></b></p>\n              </div>\n            </div>\n          </li>\n      {/foreach}\n    {/foreach}\n{/foreach}', NULL, '2016-6-2 11:18:14', '2016-6-12 14:26:13', 0, 0);
INSERT INTO `demo` VALUES (656, 00000000654, 1, 0, 'html', '原价数据遍历section+loop', '关键词', '{{$newsTitle}}[sn]为单条数据,{$smarty.section.sn.index}为其索引', '{section name=sn loop={{$newsTitle}}}\n<li class=\"fore{$smarty.section.sn.index}\"><span>{{{$newsTitle}}[sn].NAME}</span><b></b></li>\n{/section}\n---------------------------------------------------------------------------\n<!-- section的嵌套 -->\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsTitle}}}<!-- 第一层遍历{{$newsTitle}} -->\n<dl class=\"item fore{$smarty.section.sn.index+1}\">\n  <dt class=\"item-title\">\n    <a href=\"{{{$newsTitle}}[sn].URL}\" clstag=\"channel|keycount|{$portal_id}|FLA{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\" target=\"_blank\">\n      {{{$newsTitle}}[sn].NAME}<i class=\"menu-arrow\">&gt;</i>\n    </a>\n  </dt>\n  <dd class=\"item-cont\">\n    <ul class=\"item-list clearfix\">\n      {assign var=\"icount\" value=1}<!-- 变量的定义,使用,自增长 -->\n      {section name=ch loop={{$newsTitle}}[sn].children}<!-- 第二层遍历{{$newsTitle}}[sn].children -->\n      <li class=\"title-name\">\n          <a href=\"{{{$newsTitle}}[sn].children[ch].URL}\" target=\"_blank\"  clstag=\"channel|keycount|{$portal_id}|FLB{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}_{$icount}\">{{{$newsTitle}}[sn].children[ch].NAME}</a>\n      </li>\n      {$icount = $icount +1}\n      {/section}\n    </ul>\n  </dd>\n  <s class=\"triangle\"></s>\n</dl>\n{/section}\n', NULL, '2016-6-2 13:44:25', '2016-6-2 14:50:37', 0, 0);
INSERT INTO `demo` VALUES (657, 00000000654, 1, 0, 'html', 'cms使用', '关键词', '', '编辑副本权限：admin 21c9697ffa58632db26d208c1b98536b\n--------------\n  <!-- 1.引用外部文件时 需要加协议头http: widget/?? -->\n  <!-- 2.每个页面头部需要新建变量 -->\n  {assign var=\"portal_floor_id\" value=0}<!-- 楼层 -->\n  {assign var=\"portal_cell_id\" value=0}<!-- 原件 -->\n\n  <!-- 3.每个楼层头部对变量进行+1 -->\n  {$portal_floor_id = $portal_floor_id + 1}<!-- 楼层+1 -->\n  楼层最外层添加一个唯一class名portal_floor{$portal_floor_id}<!-- 楼层dom加样式 -->\n\n  <!-- 4、每个元件头部对变量进行+1 -->\n  {$portal_cell_id = $portal_cell_id + 1}<!-- 元件+1 -->\n------------------\n  <!-- 文字 -->\n  {$portal_cell_id = $portal_cell_id + 1}<!-- 元件+1 -->\n  {section name=sn loop={{$newsTitle}}}\n    <!-- 直接取name值 -->\n    <h3>{{{$newsTitle}}[sn].NAME}</h3>\n  {/section}\n-------------------\n  {{{$header_style_data}}.0.name}\n  {{{$book_style_data}}.0.name}\n  取商品池里的价格数据的模块最外层需要添加data-price-area=\"need\"属性\n-----------------------\n  <!-- 小图文有三个name:NAME1 NAME NAME2 -->\n  <!-- *图片素材=》小图文：有可以有三个文字段，分别是，{{{$newsPic}}[sn].NAME1}，{{{$newsPic}}[sn].NAME}，{{{$newsPic}}[sn].NAME2} -->\n  <div class=\"p-info\">\n    <span class=\"num\">{{{$newsPic}}[sn].NAME2}</span>\n    <a class=\"p-name\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n    <a class=\"p-cont\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME1}</a>\n  </div>\n----------------------------\n  {$portal_cell_id = $portal_cell_id + 1}\n  {section name=sn loop={{$commodity_pool}}}\n  <!-- {{$commodity_pool}}[sn].属性名 -->\n  <!-- {$smarty.section.sn.index+1}索引 -->\n  <!-- 埋点规则(XXX自定义)最终前端生成类似:clstag=\"channel|keycount|726|SPC7_26_1\" -->\n  <!-- clstag=\"channel|keycount|{$portal_id}|XXX{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\" -->\n  <li class=\"item fore{$smarty.section.sn.index+1}\" clstag=\"channel|keycount|{$portal_id}|SPC{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\">\n    <div class=\"p-img\">\n      <a href=\"{{{$commodity_pool}}[sn].url}\" title=\"{{{$commodity_pool}}[sn].title}\" target=\"_blank\"><img width=\"170\" height=\"138\" data-lazy-img=\"{{{$commodity_pool}}[sn].picUrl}\"></a>\n    </div>\n    <div class=\"p-name\">\n      <a href=\"{{{$commodity_pool}}[sn].url}\" title=\"{{{$commodity_pool}}[sn].title}\" target=\"_blank\">{{{$commodity_pool}}[sn].title}</a>\n    </div>\n    <div class=\"p-price\">\n      <span class=\"price\" data-price-id=\"{{{$commodity_pool}}[sn].skuId}\"></span>\n\n    </div>\n  </li>\n  {/section}\n----------------------------\n  <!-- {{{$newsPic}}[sn].NAME} -->\n  <!-- {{{$newsPic}}[sn].URL} -->\n  <!-- {{{$newsPic}}[sn].PIC} -->\n  {$portal_cell_id = $portal_cell_id + 1}\n  {section name=sn loop={{$newsPic}}}\n  <div class=\"item\">\n      <a clstag=\"channel|keycount|{$portal_id}|PIC{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\" target=\"_blank\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\">\n          <img width=\"220\" height=\"219\" src=\"{{{$newsPic}}[sn].PIC}\" /> \n      </a>\n  </div>\n  {/section}\n-------------------------------\n  {section name=sn loop={{$newsTitle}}}\n      <span class=\"item ui-slider-trigger-item\"></span>\n  {/section}\n------------------------------\n  <!-- {{{$newsPic}}[sn].bgColor} -->\n  <!-- {{{$newsPic}}[sn].URL} -->\n  <!-- {{{$newsPic}}[sn].PIC} -->\n  {$portal_cell_id = $portal_cell_id + 1}\n  {section name=sn loop={{$newsPic}}}\n    <li class=\"item ui-slider-item\" style=\"background-color: {{{$newsPic}}[sn].bgColor};\" clstag=\"channel|keycount|{$portal_id}|JDT{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\">\n      <div class=\"i-wrap\">\n        <div class=\"i-inner\">\n          <a target=\"_blank\" href=\"{{{$newsPic}}[sn].URL}\">\n            <img src=\"{{{$newsPic}}[sn].PIC}\" width=\"968\" height=\"390\" alt=\"\" />\n          </a>\n        </div>\n      </div>\n    </li>\n  {/section}\n----------------------------------------------------------\n  <!-- {{{$newsPic}}[sn].URL} -->\n  <!-- {{{$newsPic}}[sn].PIC} -->\n  {$portal_cell_id = $portal_cell_id + 1}\n  {section name=sn loop={{$newsPic}}}\n  <div class=\"fashion-item fashion-left border-item\" clstag=\"channel|keycount|{$portal_id}|newarrivals{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\">\n    <a target=\"_blank\" href=\"{{{$newsPic}}[sn].URL}\">\n        <img width=\"490\" height=\"510\" data-lazy-img=\"{{{$newsPic}}[sn].PIC}\" />\n        <b class=\"fashion-border\"></b>\n    </a> \n  </div>\n  {/section}\n------------------------------------------------------------\n  <!-- 价格和评论的使用方式案例 -->\n  <!-- {{{$commodity_pool}}[sn].url} -->\n  <!-- {{{$commodity_pool}}[sn].title} -->\n  <!-- {{{$commodity_pool}}[sn].picUrl} -->\n  <!-- {{{$commodity_pool}}[sn].title} -->\n  <!-- {{{$commodity_pool}}[sn].url} -->\n  <!-- {{{$commodity_pool}}[sn].title} -->\n  <!-- {{{$commodity_pool}}[sn].skuId} -->\n  <!-- {{{$commodity_pool}}[sn].url} -->\n  <!-- {{{$commodity_pool}}[sn].title} -->\n  <!-- {{{$commodity_pool}}[sn].skuId} -->\n  {$portal_cell_id = $portal_cell_id + 1}\n  {section name=sn loop={{$commodity_pool}}}\n    <li>\n      <p class=\"pic\"><a href=\"{{{$commodity_pool}}[sn].url}\" title=\"{{{$commodity_pool}}[sn].title}\" target=\"_blank\"><img data-lazy-img=\"{{{$commodity_pool}}[sn].picUrl}\" alt=\"{{{$commodity_pool}}[sn].title}\" width=\"150\" height=\"140\" /></a></p>\n      <p class=\"tit\"><a href=\"{{{$commodity_pool}}[sn].url}\" title=\"{{{$commodity_pool}}[sn].title}\" target=\"_blank\">{{{$commodity_pool}}[sn].title}</a></p>\n      <p class=\"tip\">\n        <em data-price-id=\"{{{$commodity_pool}}[sn].skuId}\"></em><span>|</span>\n        <a href=\"{{{$commodity_pool}}[sn].url}\" title=\"{{{$commodity_pool}}[sn].title}\" target=\"_blank\">\n          <em class=\"num\" data-comment-id=\"{{{$commodity_pool}}[sn].skuId}\"></em>人评价\n        </a>\n      </p>\n    </li>\n  {/section}\n', NULL, '2016-6-2 14:27:55', '2016-6-2 14:28:28', 0, 0);
INSERT INTO `demo` VALUES (658, 00000000654, 1, 0, 'js', 'cms使用2', '关键词', '', '========================================\n标签名:{{$newsTitle}}\n字段名称及其解释:\n    [\n      {\n        \'label\': \'文字\',\n        \'name\': \'NAME\',\n        \'type\': \'text\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'链接\',\n        \'name\': \'URL\',\n        \'type\': \'url\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'是否标红\',\n        \'name\': \'YFLAG\',\n        \'type\': \'select\',\n        \'required\': \'0\',\n        \'DATA\': [\n          {\n            \'name\': \'是\',\n            \'value\': \'1\'\n          },\n          {\n            \'name\': \'否\',\n            \'value\': \'0\'\n          }\n        ]\n      },\n      {\n        \'label\': \'单选\',\n        \'name\': \'radios\',\n        \'type\': \'radio\',\n        \'required\': \'1\',\n        \'DATA\': [\n          {\n            \'name\': \'nan\',\n            \'value\': \'boy\'\n          },\n          {\n            \'name\': \'女\',\n            \'value\': \'nv\'\n          }\n        ]\n      },\n      {\n        \'label\': \'日期\',\n        \'name\': \'dates\',\n        \'type\': \'date\',\n        \'required\': \'-1\'\n      },\n      {\n        \'label\': \'textarea类型\',\n        \'name\': \'contents\',\n        \'type\': \'textarea\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'多选\',\n        \'name\': \'checkbx\',\n        \'type\': \'checkbox\',\n        \'required\': \'-1\',\n        \'DATA\': [\n          {\n            \'name\': \'provice\',\n            \'value\': \'hongkong\'\n          }\n        ]\n      }\n    ]\n----------------\n基本用法:\n{section name=sn loop={{$newsTitle}}}\n    <a class=\"cutclass\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n{/section}\n----------------\n是否标红\n{section name=sn loop={{$newsTitle}}}\n    {if {{{$newsTitle}}[sn].YFLAG} eq \'1\'}\n        <a class=\"cutclass\" style=\"color:red;\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {else}\n        <a class=\"cutclass\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {/if}\n{/section}\n----------------------\n单选按钮\n{section name=sn loop={{$newsTitle}}}\n    {if {{{$newsTitle}}[sn].type} eq \'radio\'}\n        <a class=\"cutclass\" checked=\"checked\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {else}\n        <a class=\"cutclass\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {/if}\n{/section}\n-------------------------\n多选按钮\n{section name=sn loop={{$newsTitle}}}\n    {if {{{$newsTitle}}[sn].type} eq \'checkbox\'}\n        <a class=\"cutclass\" checked=\"checked\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {else}\n        <a class=\"cutclass\" title=\"{{{$newsTitle}}[sn].NAME}\" href=\"{{{$newsTitle}}[sn].URL}\" target=\"_blank\">{{{$newsTitle}}[sn].NAME}</a>\n    {/if}\n{/section}\n=====================================\n标签名:{{$newsPic}}\n字段名称及其解释:\n    [\n      {\n        \'label\': \'文字\',\n        \'name\': \'NAME\',\n        \'type\': \'text\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'链接\',\n        \'name\': \'URL\',\n        \'type\': \'url\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'图片链接\',\n        \'name\': \'PIC\',\n        \'type\': \'textarea\',\n        \'required\': \'0\',\n        \'CUSTOM_ATTR\': [\n          {\n            \'name\': \'upload\',\n            \'value\': \'1\'\n          }\n        ]\n      },\n      {\n        \'label\': \'窄屏图片链接\',\n        \'name\': \'PIC1\',\n        \'type\': \'textarea\',\n        \'required\': \'0\',\n        \'CUSTOM_ATTR\': [\n          {\n            \'name\': \'upload\',\n            \'value\': \'1\'\n          }\n        ]\n      },\n      {\n        \'label\': \'副标题1\',\n        \'name\': \'NAME1\',\n        \'type\': \'textarea\',\n        \'required\': \'0\'\n      },\n      {\n        \'label\': \'副标题2\',\n        \'name\': \'NAME2\',\n        \'type\': \'textarea\',\n        \'required\': \'0\'\n      },\n      {\n        \'label\': \'锚点\',\n        \'name\': \'ANCHOR\',\n        \'type\': \'select\',\n        \'required\': \'0\',\n        \'DATA\': [\n          {\n            \'name\': \'可点\',\n            \'value\': \'1\'\n          },\n          {\n            \'name\': \'不可点\',\n            \'value\': \'0\'\n          }\n        ]\n      }\n    ]\n------------------------------\n用法:\n    {section name=sn loop={{$newsPic}}}\n        <a class=\"cutclass\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n    {/section}\n------------------------------\n是否标红\n    {section name=sn loop={{$newsPic}}}\n        {if {{{$newsPic}}[sn].YFLAG} eq \'1\'}\n            <a class=\"cutclass\" style=\"color:red;\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {else}\n            <a class=\"cutclass\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {/if}\n    {/section}\n------------------------\n单选按钮\n    {section name=sn loop={{$newsPic}}}\n        {if {{{$newsPic}}[sn].type} eq \'radio\'}\n            <a class=\"cutclass\" checked=\"checked\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {else}\n            <a class=\"cutclass\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {/if}\n    {/section}\n--------------------------\n多选按钮\n    {section name=sn loop={{$newsPic}}}\n        {if {{{$newsPic}}[sn].type} eq \'checkbox\'}\n            <a class=\"cutclass\" checked=\"checked\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {else}\n            <a class=\"cutclass\" title=\"{{{$newsPic}}[sn].NAME}\" href=\"{{{$newsPic}}[sn].URL}\" target=\"_blank\">{{{$newsPic}}[sn].NAME}</a>\n        {/if}\n    {/section}\n====================================\n标签名:{{$commodity_pool}}\n字段名称及其解释:\n    [\n      {\n        \'label\': \'商品池ID\',\n        \'name\': \'POOLID\',\n        \'type\': \'text\',\n        \'required\': \'1\',\n        \'CUSTOM_ATTR\': [\n          {\n            \'name\': \'pattern\',\n            \'value\': \'\\\\\\\\d+\'\n          }\n        ]\n      },\n      {\n        \'label\': \'商品数量\',\n        \'name\': \'COUNT\',\n        \'type\': \'text\',\n        \'required\': \'1\'\n      },\n      {\n        \'label\': \'商品最少数量\',\n        \'name\': \'MINCOUNT\',\n        \'type\': \'text\',\n        \'required\': \'0\'\n      },\n      {\n        \'label\': \'别名\',\n        \'name\': \'NAME\',\n        \'type\': \'text\',\n        \'required\': \'0\'\n      }\n    ]\n-------------------------\n基本用法:\n    {section name=sn loop={{$commodity_pool}}}\n        <a class=\"cutclass\" title=\"{{{$commodity_pool}}[sn].NAME}\" href=\"{{{$commodity_pool}}[sn].URL}\" target=\"_blank\">{{{$commodity_pool}}[sn].NAME}</a>\n    {/section}\n-------------------------\n单选按钮\n    {section name=sn loop={{$commodity_pool}}}\n        {if {{{$commodity_pool}}[sn].type} eq \'radio\'}\n            <a class=\"cutclass\" checked=\"checked\" title=\"{{{$commodity_pool}}[sn].NAME}\" href=\"{{{$commodity_pool}}[sn].URL}\" target=\"_blank\">{{{$commodity_pool}}[sn].NAME}</a>\n        {else}\n            <a class=\"cutclass\" title=\"{{{$commodity_pool}}[sn].NAME}\" href=\"{{{$commodity_pool}}[sn].URL}\" target=\"_blank\">{{{$commodity_pool}}[sn].NAME}</a>\n        {/if}\n    {/section}\n--------------------------\n多选按钮\n    {section name=sn loop={{$commodity_pool}}}\n        {if {{{$commodity_pool}}[sn].type} eq \'checkbox\'}\n            <a class=\"cutclass\" checked=\"checked\" title=\"{{{$commodity_pool}}[sn].NAME}\" href=\"{{{$commodity_pool}}[sn].URL}\" target=\"_blank\">{{{$commodity_pool}}[sn].NAME}</a>\n        {else}\n            <a class=\"cutclass\" title=\"{{{$commodity_pool}}[sn].NAME}\" href=\"{{{$commodity_pool}}[sn].URL}\" target=\"_blank\">{{{$commodity_pool}}[sn].NAME}</a>\n        {/if}\n    {/section}', NULL, '2016-6-2 15:09:20', '2016-6-2 15:09:42', 0, 0);
INSERT INTO `demo` VALUES (659, 00000000654, 1, 0, 'js', '焦点逻辑判断(根据索引)', '关键词', '1. {if {$smarty.section.sn.index+1} eq \'1\'}\n2.{if $smarty.section.sn.index eq 0}//建议这种方式', '{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsPic}}}\n    {if {$smarty.section.sn.index+1} eq \'1\'}\n        <li class=\"newlook-title current\">\n             <span>{{{$newsTitle}}[sn].NAME}</span> <b></b>\n        </li>\n    {else}\n        <li class=\"newlook-title current\">\n             <span>{{{$newsTitle}}[sn].NAME}</span> <b></b>\n        </li>\n    {/if}\n{/section}\n-----------------------------------------\n{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$newsPic}}}\n<li{if $smarty.section.sn.index eq 0} class=\"curr\"{/if}{if $smarty.section.sn.index eq 4} class=\"end\"{/if} clstag=\"channel|keycount|{$portal_id}|master{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\">\n                    <p class=\"num\">{$smarty.section.sn.index+1}.</p>\n                    <div class=\"con clearfix\">\n                        <div class=\"con-l\">\n                            <a href=\"{{{$newsPic}}[sn].URL}\" title=\"\" target=\"_blank\">\n                                <img data-lazy-img=\"{{{$newsPic}}[sn].PIC}\" alt=\"\" width=\"47\" height=\"47\" />\n                            </a>\n                        </div>\n                        <div class=\"con-r\">\n                            <p class=\"name\">{{{$newsPic}}[sn].NAME}</p>\n                            <p class=\"clearfix\">\n                                <span class=\"tip01\">{{{$newsPic}}[sn].NAME1}</span>\n                                <span class=\"tip01\">发帖数：{{{$newsPic}}[sn].NAME2}</span>\n                            </p>\n                        </div>\n                    </div>\n                    <div class=\"note\">\n                        <p class=\"note01\">热门帖子：</p>\n                        <p class=\"note02\"><a href=\"{{{$newsPic}}[sn].CUSTOM2}\" title=\"\" target=\"_blank\">{{{$newsPic}}[sn].CUSTOM1}</a></p>\n                    </div>\n                </li>\n{/section}', NULL, '2016-6-2 15:55:25', '2016-6-12 15:50:28', 0, 0);
INSERT INTO `demo` VALUES (660, 00000000654, 1, 0, 'js', '我的cms实例', '关键词', '', '{$portal_cell_id = $portal_cell_id + 1}\n{section name=sn loop={{$commodity_pool}}}\n    <li class=\"newlook-item clearfix item{$smarty.section.sn.index+1}\" data-price-area=\"need\" clstag=\"channel|keycount|{$portal_id}|LKF{$portal_floor_id}_{$portal_cell_id}_{$smarty.section.sn.index+1}\">\n        <div class=\"p-video fl\">\n            <iframe src=\"{{{$commodity_pool}}[sn].promoteText}&auto_play=0&gpcflag=1&width=354&height=264\" frameborder=\"0\" scrolling=\"no\" style=\"display:block;width:354px;height:264px;\"></iframe>\n        </div>\n        <div class=\"p-info fl\">\n            <div class=\"p-name\"><a href=\"{{{$commodity_pool}}[sn].url}\">{{{$commodity_pool}}[sn].title}</a>\n            </div>\n            <div class=\"p-detail\">{{{$commodity_pool}}[sn].tag}</div>\n            <div class=\"p-price\" data-price-id=\"{{{$commodity_pool}}[sn].skuId}\"></div>\n            <div class=\"p-buy\">\n                <a class=\"btn-buy\" href=\"{{{$commodity_pool}}[sn].url}\">立即购买</a>\n            </div>\n        </div>\n        <div class=\"p-img fl\">\n            <a href=\"{{{$commodity_pool}}[sn].url}\">\n                <img src=\"{{{$commodity_pool}}[sn].picUrl}\" alt=\"{{{$commodity_pool}}[sn].title}\">\n            </a>\n        </div>\n    </li>\n{/section}', NULL, '2016-6-2 18:22:06', '2016-6-6 14:57:17', 0, 0);
INSERT INTO `demo` VALUES (686, 00000000604, 1, 0, 'js', 'css2scss', '关键词', 'http://sebastianpontow.de/css2compass/    有诸多可选设置\nhttp://css2sass.herokuapp.com/    简单直接用', '新数据', NULL, '2016-6-16 14:49:20', '2016-6-22 14:19:35', 0, 0);
INSERT INTO `demo` VALUES (687, 00000000574, 1, 0, 'css', '3像素bug', '关键词', '当浮动元素与非浮动元素相邻时，这个3像素的Bug就会出现', '1.非浮动元素被挤压了3像素,所以再挤回去,使用_margin向外挤,如果已经是0,则用-3px\n2.浮动元素的右边-3px也有效果!\n3.有的时候需要1和2同时用才生效', NULL, '2016-6-16 17:53:27', '2016-6-17 14:37:21', 0, 0);
INSERT INTO `demo` VALUES (689, 00000000654, 1, 0, 'js', '广告位', '关键词', '教程:http://fe.jd.com:8090/pages/viewpage.action?pageId=6225959\n后台:http://admin.nfa.jd.com/ads/channel/list', 'http://nfa.jd.com/loadFa_toJson.action?aid=0_0_****\nhttp://nfa.jd.com/loadFa_toJson.action?aid=0_0_6502  数据生成的地址类似', NULL, '2016-6-22 15:17:58', '2016-6-22 15:19:26', 0, 0);
INSERT INTO `demo` VALUES (690, 00000000483, 1, 0, 'js', 'livestyle插件的安装总结', '关键词', '1浏览器中的任何网页可以映射到编辑器中的任何css文件.\n2编辑器的批量操作也将再线上得到集中展示\n3可以即时的绑定scss.但是不能在google的样式编辑器中调整!只能再元素样式表单个调整!\n4.不是批量保存,值修改针对的样式,其他样式竟然无视差异!', '新数据', NULL, '2016-6-22 17:36:02', '2016-6-22 17:36:38', 0, 0);
INSERT INTO `demo` VALUES (691, 00000000574, 1, 0, 'js', 'ie67图片1像素bug', '关键词', 'bug描述:IE6、IE7中常常会遇到图片上方会产生1像素空白距离。\n解决方案:\n1.通过CSS对图片加一个浮动属性，比如.pigzz img{ float:left }\n2.将图片高度处理为单数（1、3、5、7单数），比如图片本身为200px高度，为了解决我们将图片PS处理成201px或199px高度。图片本身高度为202px双数在IE6和IE7浏览器中就会在图片上方产生多1px的空白距离。所以制作图片切图时候，让图片高度为单数（奇数）即可解决。', '只能改float或者position:absolute了~  改图不现实!', NULL, '2016-6-23 14:25:24', '2016-6-24 14:13:06', 0, 0);
INSERT INTO `demo` VALUES (692, 00000000339, 1, 0, 'html', '内置遮罩层', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <style>\n        .p-action {\n          display: none;\n          position: absolute;\n          top: 0;\n          right: 0;\n          bottom: 0;\n          left: 0;\n          _width: 100%;\n          .a-mask {\n            position: absolute;\n            top: 0;\n            right: 0;\n            bottom: 0;\n            left: 0;\n            background-color: #000;\n            @include alpha(70);\n          }\n          .a-content {\n            position: relative;\n            z-index: 1;\n            .a-msg {\n              padding: 75px 15px 45px;\n              font-size: 16px;\n              color: #fff;\n              text-align: center;\n            }\n            .a-btns {\n              text-align: center;\n              .a-yes {\n                margin-right: 10px;\n              }\n              .a-btn {\n                width: 92px;\n                height: 35px;\n                @include inline-block();\n                @include r-corners(2px);\n                text-align: center;\n                font-size: 16px;\n                line-height: 34px;\n                color: #fff;\n                background-color: #999;\n                cursor: pointer;\n              }\n              .cur {\n                background-color: $color;\n              }\n            }\n          }\n        }\n    </style>\n</head>\n<body>    \n    <div class=\"p-action\">\n        <div class=\"a-mask\"></div>\n        <div class=\"a-content\">\n            <p class=\"a-msg\">确定取消关注吗?</p>\n            <p class=\"a-btns\">\n                <span class=\"a-btn a-yes\">确定</span>\n                <span class=\"a-btn a-no cur\">放弃</span>\n            </p>\n        </div>\n    </div>\n</body>\n</html>', NULL, '2016-6-23 18:08:54', '2016-6-23 18:11:30', 0, 0);
INSERT INTO `demo` VALUES (693, 00000000339, 1, 0, 'html', 'page页码的dom结构', '关键词', '', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <style>\n    .page {\n      font-size: 12px;\n      text-align: center;\n      color: #333;\n      padding: 50px 0 130px;\n      span, a {\n        @include inline-block();\n        line-height: 32px;\n        vertical-align: middle;\n        padding: 0 15px;\n        border: 1px solid #ddd;\n        margin-right: 3px;\n      }\n      .pageprev, .pagenext {\n        color: #ccc;\n      }\n      .action {\n        color: #333;\n      }\n      .pagenum {\n        font-family: Arial;\n        background-color: #f3f3f3;\n        &:hover{\n            color:$color\n        }\n      }\n      .cur {\n        border: 0;\n        color: $color;\n        background-color: transparent;\n        cursor:default;\n      }\n      .ellip {\n        line-height: 14px;\n        border: 0;\n        padding: 0 2px;\n      }\n      .pagetotal {\n        color: #999;\n      }\n    }\n    </style>\n</head>\n<body>\n        <div class=\"page\">\n            <a href=\"javascript:;\" class=\"pageprev\">&lt;&nbsp;上一页</a>\n            <a href=\"javascript:;\" class=\"pagenum cur\">1</a>\n            <a href=\"javascript:;\" class=\"pagenum\">2</a>\n            <a href=\"javascript:;\" class=\"pagenum\">3</a>\n            <a href=\"javascript:;\" class=\"pagenum\">4</a>\n            <a href=\"javascript:;\" class=\"pagenum\">5</a>\n            <span class=\"ellip\">...</span>\n            <a href=\"javascript:;\" class=\"pagenum\">45</a>\n            <a href=\"javascript:;\" class=\"pagenext action\">下一页&nbsp;&gt;</a>\n            <span class=\"pagetotal\">共50页</span>\n        </div>\n</body>\n</html>', NULL, '2016-6-23 18:11:46', '2016-6-23 18:12:56', 0, 0);
INSERT INTO `demo` VALUES (694, 00000000162, 1, 0, 'js', 'js模拟上线', '关键词', '描述', '新代码', NULL, '2016-6-24 09:34:03', '2016-6-24 09:34:03', 0, 0);
INSERT INTO `demo` VALUES (695, 00000000574, 1, 0, 'html', 'ie6下的双类名问题', '关键词', '总结如下:\n1.双类名会被无视调第一个类名,所以二者联合不会起到任何提权问题\n2.但是如果双类名如果写在了较后面,会对前面同优先级的选择器有覆盖作用,所以依然可以使用js构建双类来改变元素样式!必须保证顺序,否则双类名照样被单类名从下面干掉!', '<!doctype html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <title>Document</title>\n    <style>\n        div{width:100px;height:100px;}\n        .red{background-color:red}\n        .green{background-color:green}\n        .red.green{background-color:blue}\n    </style>\n</head>\n<body>\n<div class=\"red\"><span>123456</span></div>\n<div class=\"green\"><span>23456</span>1234</div><!--在ie6下面被覆盖为了蓝色-->\n<div class=\"red green\"><span>23456</span>1234</div>\n</body>\n</html>', NULL, '2016-6-24 14:02:29', '2016-6-24 14:12:04', 0, 0);
INSERT INTO `demo` VALUES (696, 00000000574, 1, 0, 'css', 'ie789的半透明背景问题', '关键词', '现在浏览器直接rgba即可,对于ie系列,6是无法办到的,789可以使用filter的渐变来模拟,其中颜色部分前面两位要设置16进制来标识半透明,附带16进制半透明的js算法', 'background: rgba(1,163,150,.85);\nbackground-color: $color;\nfilter: progid:DXImageTransform.Microsoft.gradient(startColorstr=#3301a396, endColorstr=#3301a396);\n\nvar  a = 0.7;\nconsole.log((a*255).toString(16).split(\".\")[0])', NULL, '2016-6-24 15:04:00', '2016-6-24 15:09:33', 0, 0);
INSERT INTO `demo` VALUES (697, 00000000566, 1, 0, 'js', '插件拆解', '关键词', '描述', '新代码', NULL, '2016-6-24 15:50:26', '2016-6-24 15:50:26', 0, 0);
INSERT INTO `demo` VALUES (698, 00000000697, 1, 0, 'js', 'gotop', '关键词', '1.dom为js中拼凑!\n2.采用算法定位,而不是样式定位!', '    //依赖\nseajs.use([\'jdf/1.0.0/ui/gotop/1.0.0/gotop\'],function(){ \n    var gotop = $(\'.go-top\');\n    gotop.gotop({\n        hasAnimate: true\n    });\n});\n//定位依赖\'jdf/1.0.0/ui/fixable/1.0.0/fixable\'\n//定位初始化:\ngoTop.fixable({\n    x: \'right\',\n    y: \'bottom\',\n    xValue: _wx,\n    yValue: 42,\n    zIndex: 10,\n    context: contentFloor\n});\n//使用:\n$($0).gotop({\n        hasAnimate: true\n    });\n//核心源码:\n$(\"html,body\").animate({\n                        scrollTop : 0\n                    },1000);  ', NULL, '2016-6-24 15:50:35', '2016-6-29 10:55:06', 0, 0);
